#[allow(clippy::too_many_arguments)]
fn capture_ready_storage_transaction_at_with_cancel(
    backend: &mut HvfBackend,
    mmio_dispatcher: &Arc<Mutex<MmioDispatcher>>,
    runtime_resources: &Arm64BootRuntimeResources,
    pci_data_devices: &mut Option<HvfArm64BootPciDataDevices>,
    block_device_metrics: &SharedBlockDeviceMetricsRegistry,
    gic: &HvfGicMetadata,
    block_retry_wakeup_scheduler: &HvfArm64BootLimiterRetryWakeupScheduler,
    pmem_retry_wakeup_scheduler: &HvfArm64BootLimiterRetryWakeupScheduler,
    configs: &CaptureReadyStorageConfigs,
    guard: &HvfArm64BootLimiterRetryWakeupQuiescenceGuard,
    now: Instant,
    mode: CaptureReadyStorageMode,
    mut is_cancelled: impl FnMut(HvfArm64BootStorageCaptureStage) -> bool,
) -> Result<CaptureReadyStorageResult, HvfArm64BootStorageCaptureError> {
    if !Arc::ptr_eq(&guard.block.shared, &block_retry_wakeup_scheduler.shared)
        || !Arc::ptr_eq(&guard.pmem.shared, &pmem_retry_wakeup_scheduler.shared)
    {
        return Err(HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::WrongQuiescenceGuard,
            false,
        ));
    }
    let shared_block_retry =
        storage_retry_state(guard.block_retry_state_at(now).map_err(|_| {
            HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::RetryState,
                false,
            )
        })?);
    let shared_pmem_retry = storage_retry_state(guard.pmem_retry_state_at(now).map_err(|_| {
        HvfArm64BootStorageCaptureError::new(HvfArm64BootStorageCaptureErrorKind::RetryState, false)
    })?);
    let mut block_retry_attribution =
        CaptureReadySharedStorageRetryAttribution::new(shared_block_retry);
    let mut pmem_retry_attribution =
        CaptureReadySharedStorageRetryAttribution::new(shared_pmem_retry);
    let mut mmio_dispatcher_guard =
        lock_boot_mmio_dispatcher(mmio_dispatcher).map_err(|error| match error {
            HvfArm64BootMmioDispatcherError::Busy => HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::MmioDispatcherBusy,
                false,
            ),
            HvfArm64BootMmioDispatcherError::Poisoned => HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::MmioDispatcherPoisoned,
                false,
            ),
        })?;

    if is_cancelled(HvfArm64BootStorageCaptureStage::Inventory) {
        return Err(HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::Cancelled,
            false,
        ));
    }

    // This scan is deliberately first: vhost rejection cannot follow Async
    // admission changes, guest-memory writes, or artifact preparation.
    for device in &runtime_resources.block_devices {
        let kind = runtime_resources
            .capture_ready_mmio_block_backend_kind(
                &mut mmio_dispatcher_guard,
                device.registration.drive_id(),
            )
            .map_err(|_| {
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::BlockCapture,
                    false,
                )
            })?;
        if kind == VirtioBlockBackendKind::VhostUser {
            return Err(HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::VhostUserUnsupported,
                false,
            ));
        }
    }
    if let Some(pci) = pci_data_devices.as_ref() {
        for device in &pci.block {
            let kind = device
                .published
                .endpoint()
                .block_backend_kind()
                .map_err(|_| {
                    HvfArm64BootStorageCaptureError::new(
                        HvfArm64BootStorageCaptureErrorKind::BlockCapture,
                        false,
                    )
                })?;
            if kind == VirtioBlockBackendKind::VhostUser {
                return Err(HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::VhostUserUnsupported,
                    false,
                ));
            }
        }
    }

    let profile_preflight_failed = match mode {
        CaptureReadyStorageMode::Diagnostic => false,
        CaptureReadyStorageMode::SnapshotV2MultiBlock => {
            !configs.pmem().is_empty()
                || !runtime_resources.pmem_devices.is_empty()
                || !runtime_resources.pmem_mmio_devices.is_empty()
                || pci_data_devices
                    .as_ref()
                    .is_some_and(|devices| !devices.pmem.is_empty())
                || SnapshotV2MultiBlockDeviceGraph::preflight_capture_configs(
                    NATIVE_V2_MULTI_BLOCK_DEVICE_GRAPH_COMPATIBILITY_VERSION,
                    configs.drives(),
                )
                .is_err()
        }
        CaptureReadyStorageMode::SnapshotV2Storage => {
            SnapshotV2StorageDeviceGraph::preflight_capture_configs(
                NATIVE_V2_STORAGE_DEVICE_GRAPH_COMPATIBILITY_VERSION,
                configs.drives(),
                configs.pmem(),
            )
            .is_err()
        }
    };
    if profile_preflight_failed {
        return Err(HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
            false,
        ));
    }

    let pci_block_count = pci_data_devices
        .as_ref()
        .map_or(0, |devices| devices.block.len());
    let pci_pmem_count = pci_data_devices
        .as_ref()
        .map_or(0, |devices| devices.pmem.len());
    if !runtime_resources.pci_block_devices.is_empty()
        || runtime_resources.block_devices.len() + pci_block_count != configs.drives().len()
        || runtime_resources.pmem_mmio_devices.len() + pci_pmem_count != configs.pmem().len()
        || runtime_resources.pmem_devices.len() != configs.pmem().len()
    {
        return Err(HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
            false,
        ));
    }

    let allocation_error = |_| {
        HvfArm64BootStorageCaptureError::new(HvfArm64BootStorageCaptureErrorKind::Allocation, false)
    };
    let mut block_owners = Vec::new();
    block_owners
        .try_reserve_exact(configs.drives().len())
        .map_err(allocation_error)?;
    let mut pmem_owners = Vec::new();
    pmem_owners
        .try_reserve_exact(configs.pmem().len())
        .map_err(allocation_error)?;
    let mut async_owners = Vec::new();
    async_owners
        .try_reserve_exact(configs.drives().len())
        .map_err(allocation_error)?;
    let mut block_persistence_bindings: Vec<VirtioBlockSnapshotPersistenceBinding> = Vec::new();
    if matches!(
        mode,
        CaptureReadyStorageMode::SnapshotV2MultiBlock | CaptureReadyStorageMode::SnapshotV2Storage
    ) {
        block_persistence_bindings
            .try_reserve_exact(configs.drives().len())
            .map_err(allocation_error)?;
    }
    let mut pmem_persistence_bindings: Vec<PmemSnapshotPersistenceBinding> = Vec::new();
    if mode == CaptureReadyStorageMode::SnapshotV2Storage {
        pmem_persistence_bindings
            .try_reserve_exact(configs.pmem().len())
            .map_err(allocation_error)?;
    }
    let mut mmio_block_interrupts = Vec::new();
    mmio_block_interrupts
        .try_reserve_exact(configs.drives().len())
        .map_err(allocation_error)?;
    let mut generations = Vec::new();
    generations
        .try_reserve_exact(configs.drives().len())
        .map_err(allocation_error)?;
    let mut block_states = Vec::new();
    block_states
        .try_reserve_exact(configs.drives().len())
        .map_err(allocation_error)?;
    let mut pmem_states = Vec::new();
    pmem_states
        .try_reserve_exact(configs.pmem().len())
        .map_err(allocation_error)?;

    for config in configs.drives() {
        let mut mmio_matches = runtime_resources
            .block_devices
            .iter()
            .filter(|device| device.registration.drive_id() == config.drive_id());
        let mmio_match = mmio_matches
            .next()
            .map(|device| device.fdt_device.interrupt_line);
        let duplicate_mmio = mmio_matches.next().is_some();
        let mut pci_matches = pci_data_devices
            .as_ref()
            .into_iter()
            .flat_map(|devices| devices.block.iter().enumerate())
            .filter(|(_, device)| device.drive_id == config.drive_id());
        let pci_match = pci_matches.next().map(|(index, _)| index);
        let duplicate_pci = pci_matches.next().is_some();
        let owner = match (mmio_match, duplicate_mmio, pci_match, duplicate_pci) {
            (Some(interrupt_line), false, None, false) => {
                let pending = runtime_resources
                    .capture_ready_mmio_block_has_pending_rate_limited_queue(
                        &mut mmio_dispatcher_guard,
                        config.drive_id(),
                    )
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::BlockCapture,
                            false,
                        )
                    })?;
                CaptureReadyBlockOwner::Mmio {
                    retry: block_retry_attribution.attribute(pending)?,
                    interrupt_line,
                }
            }
            (None, false, Some(index), false) => {
                let device = pci_data_devices
                    .as_ref()
                    .and_then(|devices| devices.block.get(index))
                    .ok_or_else(|| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                            false,
                        )
                    })?;
                if device.is_root_device != config.is_root_device()
                    || (mode != CaptureReadyStorageMode::Diagnostic
                        && config.is_root_device()
                        && device.origin != StorageDeviceOrigin::Startup)
                {
                    return Err(HvfArm64BootStorageCaptureError::new(
                        HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                        false,
                    ));
                }
                let retry = storage_retry_state_at(device.retry_deadline, now)?;
                block_retry_attribution.account_endpoint_retry(retry)?;
                CaptureReadyBlockOwner::Pci { index, retry }
            }
            _ => {
                return Err(HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                    false,
                ));
            }
        };
        block_owners.push(owner);
    }
    block_retry_attribution.finish()?;

    for config in configs.pmem() {
        let mut mmio_matches = runtime_resources
            .pmem_mmio_devices
            .iter()
            .filter(|device| device.registration.pmem_id() == config.id());
        let mmio_match = mmio_matches.next().is_some();
        let duplicate_mmio = mmio_matches.next().is_some();
        let mut pci_matches = pci_data_devices
            .as_ref()
            .into_iter()
            .flat_map(|devices| devices.pmem.iter().enumerate())
            .filter(|(_, device)| device.pmem_id == config.id());
        let pci_match = pci_matches.next().map(|(index, _)| index);
        let duplicate_pci = pci_matches.next().is_some();
        let owner = match (mmio_match, duplicate_mmio, pci_match, duplicate_pci) {
            (true, false, None, false) => {
                let pending = runtime_resources
                    .capture_ready_mmio_pmem_has_pending_rate_limited_queue(
                        &mut mmio_dispatcher_guard,
                        config.id(),
                    )
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::PmemCapture,
                            false,
                        )
                    })?;
                CaptureReadyPmemOwner::Mmio {
                    retry: pmem_retry_attribution.attribute(pending)?,
                }
            }
            (false, false, Some(index), false) => {
                let device = pci_data_devices
                    .as_ref()
                    .and_then(|devices| devices.pmem.get(index))
                    .ok_or_else(|| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                            false,
                        )
                    })?;
                if mode == CaptureReadyStorageMode::SnapshotV2Storage
                    && config.root_device()
                    && device.origin != StorageDeviceOrigin::Startup
                {
                    return Err(HvfArm64BootStorageCaptureError::new(
                        HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
                        false,
                    ));
                }
                let retry = storage_retry_state_at(device.retry_deadline, now)?;
                pmem_retry_attribution.account_endpoint_retry(retry)?;
                CaptureReadyPmemOwner::Pci { index, retry }
            }
            _ => {
                return Err(HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                    false,
                ));
            }
        };
        pmem_owners.push(owner);
    }
    pmem_retry_attribution.finish()?;

    if mode != CaptureReadyStorageMode::Diagnostic {
        let first_is_mmio = block_owners
            .first()
            .map(|owner| matches!(owner, CaptureReadyBlockOwner::Mmio { .. }))
            .or_else(|| {
                pmem_owners
                    .first()
                    .map(|owner| matches!(owner, CaptureReadyPmemOwner::Mmio { .. }))
            });
        let uniform_transport = first_is_mmio.is_some_and(|expected_mmio| {
            block_owners
                .iter()
                .all(|owner| matches!(owner, CaptureReadyBlockOwner::Mmio { .. }) == expected_mmio)
                && pmem_owners.iter().all(|owner| {
                    matches!(owner, CaptureReadyPmemOwner::Mmio { .. }) == expected_mmio
                })
        });
        if !uniform_transport {
            return Err(HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
                false,
            ));
        }
    }

    if mode == CaptureReadyStorageMode::SnapshotV2Storage {
        for config in configs.pmem() {
            pmem_persistence_bindings.push(
                runtime_resources
                    .capture_ready_pmem_snapshot_persistence_binding(config)
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
                            false,
                        )
                    })?,
            );
        }
    }

    for (config_index, (config, owner)) in configs
        .drives()
        .iter()
        .zip(block_owners.iter().copied())
        .enumerate()
    {
        let binding = if matches!(
            mode,
            CaptureReadyStorageMode::SnapshotV2MultiBlock
                | CaptureReadyStorageMode::SnapshotV2Storage
        ) {
            let persistence = match owner {
                CaptureReadyBlockOwner::Mmio { .. } => runtime_resources
                    .capture_ready_mmio_block_snapshot_persistence_binding(
                        &mut mmio_dispatcher_guard,
                        config,
                    )
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
                            false,
                        )
                    })?,
                CaptureReadyBlockOwner::Pci { index, .. } => pci_data_devices
                    .as_ref()
                    .and_then(|devices| devices.block.get(index))
                    .ok_or_else(|| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                            false,
                        )
                    })?
                    .published
                    .endpoint()
                    .block_snapshot_persistence_binding(config)
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
                            false,
                        )
                    })?,
            };
            if Some(persistence.io_engine()) != config.io_engine() {
                return Err(HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
                    false,
                ));
            }
            let binding = persistence.async_binding();
            block_persistence_bindings.push(persistence);
            binding
        } else {
            match owner {
                CaptureReadyBlockOwner::Mmio { .. } => runtime_resources
                    .capture_ready_mmio_block_async_binding(
                        &mut mmio_dispatcher_guard,
                        config.drive_id(),
                    )
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::AsyncPreparation,
                            false,
                        )
                    })?,
                CaptureReadyBlockOwner::Pci { index, .. } => pci_data_devices
                    .as_ref()
                    .and_then(|devices| devices.block.get(index))
                    .ok_or_else(|| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                            false,
                        )
                    })?
                    .published
                    .endpoint()
                    .block_async_binding()
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::AsyncPreparation,
                            false,
                        )
                    })?,
            }
        };
        match (config.io_engine(), binding) {
            (Some(DriveIoEngine::Sync), None) => {}
            (Some(DriveIoEngine::Async), Some((runtime, generation))) => {
                if !runtime.same_runtime(&runtime_resources.block_async_runtime)
                    || generations.contains(&generation)
                {
                    return Err(HvfArm64BootStorageCaptureError::new(
                        HvfArm64BootStorageCaptureErrorKind::AsyncPreparation,
                        false,
                    ));
                }
                generations.push(generation);
                async_owners.push(CaptureReadyAsyncOwner {
                    config_index,
                    owner,
                });
            }
            (Some(DriveIoEngine::Sync), Some(_))
            | (Some(DriveIoEngine::Async), None)
            | (None, _) => {
                return Err(HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::AsyncPreparation,
                    false,
                ));
            }
        }
    }

    let memory = backend.mapped_guest_memory_mut().map_err(|_| {
        HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::GuestMemory,
            false,
        )
    })?;
    if is_cancelled(HvfArm64BootStorageCaptureStage::StopAsync) {
        return Err(HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::Cancelled,
            false,
        ));
    }
    runtime_resources
        .block_async_runtime
        .stop_generations(&generations)
        .map_err(|_| {
            HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::AsyncPreparation,
                false,
            )
        })?;

    let mut primary = None;
    for generation in generations.iter().copied() {
        let drained = match mode {
            CaptureReadyStorageMode::Diagnostic => runtime_resources
                .block_async_runtime
                .quiesce_generation(generation, memory),
            CaptureReadyStorageMode::SnapshotV2MultiBlock
            | CaptureReadyStorageMode::SnapshotV2Storage => runtime_resources
                .block_async_runtime
                .drain_stopped_generation(generation, memory),
        };
        if drained.is_err() {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::AsyncDrain,
                    true,
                ),
            );
        }
        if is_cancelled(HvfArm64BootStorageCaptureStage::DrainAsync) {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::Cancelled,
                    false,
                ),
            );
        }
    }

    if matches!(
        mode,
        CaptureReadyStorageMode::SnapshotV2MultiBlock | CaptureReadyStorageMode::SnapshotV2Storage
    ) {
        if primary.is_none() && is_cancelled(HvfArm64BootStorageCaptureStage::Persist) {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::Cancelled,
                    false,
                ),
            );
        }
        if primary.is_none() && block_persistence_bindings.len() != configs.drives().len() {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
                    false,
                ),
            );
        }
        if primary.is_none() {
            for ((config, owner), persistence) in configs
                .drives()
                .iter()
                .zip(block_owners.iter().copied())
                .zip(block_persistence_bindings.iter())
            {
                if !persistence.is_read_only() {
                    let persisted = match owner {
                        CaptureReadyBlockOwner::Mmio { .. } => runtime_resources
                            .persist_capture_ready_mmio_block_snapshot_backing(
                                &mut mmio_dispatcher_guard,
                                config,
                            )
                            .map_err(|_| {
                                HvfArm64BootStorageCaptureError::new(
                                    HvfArm64BootStorageCaptureErrorKind::Persistence,
                                    false,
                                )
                            }),
                        CaptureReadyBlockOwner::Pci { index, .. } => pci_data_devices
                            .as_ref()
                            .and_then(|devices| devices.block.get(index))
                            .ok_or_else(|| {
                                HvfArm64BootStorageCaptureError::new(
                                    HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                                    false,
                                )
                            })
                            .and_then(|device| {
                                device
                                    .published
                                    .endpoint()
                                    .persist_block_snapshot_backing(config)
                                    .map_err(|_| {
                                        HvfArm64BootStorageCaptureError::new(
                                            HvfArm64BootStorageCaptureErrorKind::Persistence,
                                            false,
                                        )
                                    })
                            }),
                    };
                    if persisted.is_err() {
                        retain_storage_capture_error(
                            &mut primary,
                            HvfArm64BootStorageCaptureError::new(
                                HvfArm64BootStorageCaptureErrorKind::Persistence,
                                false,
                            ),
                        );
                        break;
                    }
                }
                if is_cancelled(HvfArm64BootStorageCaptureStage::Persist) {
                    retain_storage_capture_error(
                        &mut primary,
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::Cancelled,
                            false,
                        ),
                    );
                    break;
                }
            }
        }
        if mode == CaptureReadyStorageMode::SnapshotV2Storage
            && primary.is_none()
            && pmem_persistence_bindings.len() != configs.pmem().len()
        {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::ProfilePreflight,
                    false,
                ),
            );
        }
        if mode == CaptureReadyStorageMode::SnapshotV2Storage && primary.is_none() {
            for persistence in &pmem_persistence_bindings {
                if !persistence.is_read_only() && persistence.persist().is_err() {
                    retain_storage_capture_error(
                        &mut primary,
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::Persistence,
                            false,
                        ),
                    );
                    break;
                }
                if is_cancelled(HvfArm64BootStorageCaptureStage::Persist) {
                    retain_storage_capture_error(
                        &mut primary,
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::Cancelled,
                            false,
                        ),
                    );
                    break;
                }
            }
        }
    }

    for async_owner in async_owners.iter().copied() {
        let Some(config) = configs.drives().get(async_owner.config_index) else {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                    false,
                ),
            );
            continue;
        };
        match async_owner.owner {
            CaptureReadyBlockOwner::Mmio { interrupt_line, .. } => {
                let publication = runtime_resources.publish_capture_ready_mmio_block_completions(
                    memory,
                    &mut mmio_dispatcher_guard,
                    config.drive_id(),
                );
                let needs_queue_interrupt = match &publication {
                    Ok(dispatch) => dispatch.needs_queue_interrupt(),
                    Err(error) => error
                        .completed_block_dispatch()
                        .is_some_and(|dispatch| dispatch.needs_queue_interrupt()),
                };
                match &publication {
                    Ok(dispatch) => block_device_metrics
                        .record_queue_dispatch_for_drive(config.drive_id(), dispatch),
                    Err(error) => {
                        if let Some(dispatch) = error.completed_block_dispatch() {
                            block_device_metrics
                                .record_queue_dispatch_for_drive(config.drive_id(), dispatch);
                        }
                        block_device_metrics.record_event_failure_for_drive(config.drive_id());
                    }
                }
                if needs_queue_interrupt {
                    mmio_block_interrupts.push(CaptureReadyMmioBlockInterrupt {
                        config_index: async_owner.config_index,
                        interrupt_line,
                    });
                }
                if publication.is_err() {
                    retain_storage_capture_error(
                        &mut primary,
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::CompletionPublication,
                            true,
                        ),
                    );
                }
            }
            CaptureReadyBlockOwner::Pci { index, .. } => {
                let Some(device) = pci_data_devices
                    .as_mut()
                    .and_then(|devices| devices.block.get_mut(index))
                else {
                    retain_storage_capture_error(
                        &mut primary,
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                            false,
                        ),
                    );
                    continue;
                };
                let publication = device
                    .published
                    .endpoint()
                    .publish_quiesced_async_completions(memory);
                let mut delivered = false;
                match &publication {
                    Ok(dispatch) => {
                        block_device_metrics
                            .record_queue_dispatch_for_drive(config.drive_id(), dispatch);
                        delivered = dispatch.needs_queue_interrupt();
                    }
                    Err(error) => {
                        if let Some(dispatch) = error.completed_device_operation() {
                            block_device_metrics
                                .record_queue_dispatch_for_drive(config.drive_id(), dispatch);
                        } else if let Some(source) = error.device_error() {
                            let dispatch = source.completed_dispatch();
                            block_device_metrics
                                .record_queue_dispatch_for_drive(config.drive_id(), dispatch);
                            delivered = error.endpoint_error().is_none()
                                && dispatch.needs_queue_interrupt();
                        }
                        block_device_metrics.record_event_failure_for_drive(config.drive_id());
                    }
                }
                if delivered {
                    device.queue_deliveries = device.queue_deliveries.saturating_add(1);
                }
                if publication.is_err() {
                    retain_storage_capture_error(
                        &mut primary,
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::CompletionPublication,
                            true,
                        ),
                    );
                }
            }
        }
        if is_cancelled(HvfArm64BootStorageCaptureStage::PublishAsync) {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::Cancelled,
                    false,
                ),
            );
        }
    }

    // MMIO queue publication records the transport interrupt intent but, unlike
    // PCI MSI-X publication, cannot signal the physical GIC itself. Release the
    // dispatcher before delivery to preserve the ordinary dispatcher/GIC lock
    // order, then reacquire it for the detached state clone.
    let mut mmio_dispatcher_guard = Some(mmio_dispatcher_guard);
    if !mmio_block_interrupts.is_empty() {
        drop(mmio_dispatcher_guard.take());
        let signaler = HvfGicSpiSignaler::from_metadata(gic).ok();
        if signal_capture_ready_mmio_block_interrupts(
            &mmio_block_interrupts,
            configs,
            block_device_metrics,
            signaler
                .as_ref()
                .map(|signaler| signaler as &dyn InterruptSink),
        ) {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::CompletionPublication,
                    true,
                ),
            );
        }
        if is_cancelled(HvfArm64BootStorageCaptureStage::PublishAsync) {
            retain_storage_capture_error(
                &mut primary,
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::Cancelled,
                    false,
                ),
            );
        }
        mmio_dispatcher_guard = match lock_boot_mmio_dispatcher(mmio_dispatcher) {
            Ok(dispatcher) => Some(dispatcher),
            Err(HvfArm64BootMmioDispatcherError::Busy) => {
                retain_storage_capture_error(
                    &mut primary,
                    HvfArm64BootStorageCaptureError::new(
                        HvfArm64BootStorageCaptureErrorKind::MmioDispatcherBusy,
                        false,
                    ),
                );
                None
            }
            Err(HvfArm64BootMmioDispatcherError::Poisoned) => {
                retain_storage_capture_error(
                    &mut primary,
                    HvfArm64BootStorageCaptureError::new(
                        HvfArm64BootStorageCaptureErrorKind::MmioDispatcherPoisoned,
                        false,
                    ),
                );
                None
            }
        };
    }

    let mut captured = None;
    if primary.is_none() && is_cancelled(HvfArm64BootStorageCaptureStage::Capture) {
        retain_storage_capture_error(
            &mut primary,
            HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::Cancelled,
                false,
            ),
        );
    }
    if primary.is_none()
        && let Some(mmio_dispatcher) = mmio_dispatcher_guard.as_mut()
    {
        for (config, owner) in configs.drives().iter().zip(block_owners.iter().copied()) {
            let state = match owner {
                CaptureReadyBlockOwner::Mmio { retry, .. } => runtime_resources
                    .capture_ready_mmio_block_state_at(mmio_dispatcher, config, retry, now)
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::BlockCapture,
                            false,
                        )
                    }),
                CaptureReadyBlockOwner::Pci { index, retry } => {
                    capture_ready_pci_block_state(pci_data_devices, index, config, retry, now)
                }
            };
            match state {
                Ok(state) => block_states.push(state),
                Err(error) => {
                    retain_storage_capture_error(&mut primary, error);
                    break;
                }
            }
            if is_cancelled(HvfArm64BootStorageCaptureStage::Capture) {
                retain_storage_capture_error(
                    &mut primary,
                    HvfArm64BootStorageCaptureError::new(
                        HvfArm64BootStorageCaptureErrorKind::Cancelled,
                        false,
                    ),
                );
                break;
            }
        }
    }
    if primary.is_none()
        && let Some(mmio_dispatcher) = mmio_dispatcher_guard.as_mut()
    {
        for (config, owner) in configs.pmem().iter().zip(pmem_owners.iter().copied()) {
            let state = match owner {
                CaptureReadyPmemOwner::Mmio { retry } => runtime_resources
                    .capture_ready_mmio_pmem_state_at(mmio_dispatcher, config, retry, now)
                    .map_err(|_| {
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::PmemCapture,
                            false,
                        )
                    }),
                CaptureReadyPmemOwner::Pci { index, retry } => capture_ready_pci_pmem_state(
                    runtime_resources,
                    pci_data_devices,
                    index,
                    config,
                    retry,
                    now,
                ),
            };
            match state {
                Ok(state) => pmem_states.push(state),
                Err(error) => {
                    retain_storage_capture_error(&mut primary, error);
                    break;
                }
            }
            if is_cancelled(HvfArm64BootStorageCaptureStage::Capture) {
                retain_storage_capture_error(
                    &mut primary,
                    HvfArm64BootStorageCaptureError::new(
                        HvfArm64BootStorageCaptureErrorKind::Cancelled,
                        false,
                    ),
                );
                break;
            }
        }
    }
    if primary.is_none() {
        match mode {
            CaptureReadyStorageMode::Diagnostic => {
                captured = Some(CaptureReadyStorageResult::Diagnostic(
                    CaptureReadyStorageState::new(
                        block_states,
                        pmem_states,
                        shared_block_retry,
                        shared_pmem_retry,
                    ),
                ));
            }
            CaptureReadyStorageMode::SnapshotV2MultiBlock => {
                if is_cancelled(HvfArm64BootStorageCaptureStage::ComposeGraph) {
                    retain_storage_capture_error(
                        &mut primary,
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::Cancelled,
                            false,
                        ),
                    );
                }
                if primary.is_none() {
                    match SnapshotV2MultiBlockDeviceGraph::from_capture_ready_blocks(
                        NATIVE_V2_MULTI_BLOCK_DEVICE_GRAPH_COMPATIBILITY_VERSION,
                        &block_states,
                    ) {
                        Ok(graph) => {
                            if is_cancelled(HvfArm64BootStorageCaptureStage::ComposeGraph) {
                                retain_storage_capture_error(
                                    &mut primary,
                                    HvfArm64BootStorageCaptureError::new(
                                        HvfArm64BootStorageCaptureErrorKind::Cancelled,
                                        false,
                                    ),
                                );
                            } else {
                                captured =
                                    Some(CaptureReadyStorageResult::SnapshotV2MultiBlock(graph));
                            }
                        }
                        Err(_) => retain_storage_capture_error(
                            &mut primary,
                            HvfArm64BootStorageCaptureError::new(
                                HvfArm64BootStorageCaptureErrorKind::GraphComposition,
                                false,
                            ),
                        ),
                    }
                }
            }
            CaptureReadyStorageMode::SnapshotV2Storage => {
                if is_cancelled(HvfArm64BootStorageCaptureStage::ComposeGraph) {
                    retain_storage_capture_error(
                        &mut primary,
                        HvfArm64BootStorageCaptureError::new(
                            HvfArm64BootStorageCaptureErrorKind::Cancelled,
                            false,
                        ),
                    );
                }
                if primary.is_none() {
                    match SnapshotV2StorageDeviceGraph::from_capture_ready_storage(
                        NATIVE_V2_STORAGE_DEVICE_GRAPH_COMPATIBILITY_VERSION,
                        &block_states,
                        &pmem_states,
                    ) {
                        Ok(graph) => {
                            if is_cancelled(HvfArm64BootStorageCaptureStage::ComposeGraph) {
                                retain_storage_capture_error(
                                    &mut primary,
                                    HvfArm64BootStorageCaptureError::new(
                                        HvfArm64BootStorageCaptureErrorKind::Cancelled,
                                        false,
                                    ),
                                );
                            } else {
                                captured =
                                    Some(CaptureReadyStorageResult::SnapshotV2Storage(graph));
                            }
                        }
                        Err(_) => retain_storage_capture_error(
                            &mut primary,
                            HvfArm64BootStorageCaptureError::new(
                                HvfArm64BootStorageCaptureErrorKind::GraphComposition,
                                false,
                            ),
                        ),
                    }
                }
            }
        }
    }

    let mut cleanup_failed = false;
    for generation in generations.iter().rev().copied() {
        if runtime_resources
            .block_async_runtime
            .resume_quiesced_generation(generation)
            .is_err()
        {
            cleanup_failed = true;
        }
    }
    if cleanup_failed {
        return Err(primary
            .unwrap_or_else(|| {
                HvfArm64BootStorageCaptureError::new(
                    HvfArm64BootStorageCaptureErrorKind::AsyncResume,
                    true,
                )
            })
            .with_cleanup_failure());
    }
    if let Some(primary) = primary {
        return Err(primary);
    }
    captured.ok_or_else(|| {
        HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
            false,
        )
    })
}

fn retain_storage_capture_error(
    primary: &mut Option<HvfArm64BootStorageCaptureError>,
    error: HvfArm64BootStorageCaptureError,
) {
    if primary.is_none() {
        *primary = Some(error);
    }
}

fn capture_ready_pci_block_state(
    pci_data_devices: &Option<HvfArm64BootPciDataDevices>,
    index: usize,
    config: &DriveConfig,
    retry: StorageRetryState,
    now: Instant,
) -> Result<CaptureReadyBlockDeviceState, HvfArm64BootStorageCaptureError> {
    let device = pci_data_devices
        .as_ref()
        .and_then(|devices| devices.block.get(index))
        .filter(|device| {
            device.drive_id == config.drive_id() && device.is_root_device == config.is_root_device()
        })
        .ok_or_else(|| {
            HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                false,
            )
        })?;
    let (captured, transport) = device
        .published
        .endpoint()
        .capture_block_device_state_at(config, now)
        .map_err(|_| {
            HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::BlockCapture,
                false,
            )
        })?;
    let sbdf = device.published.sbdf().ok_or_else(|| {
        HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::PciPlacement,
            false,
        )
    })?;
    let bar_range = device.published.bar_range().ok_or_else(|| {
        HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::PciPlacement,
            false,
        )
    })?;
    Ok(CaptureReadyBlockDeviceState::new(
        config.clone(),
        StorageTransportState::Pci(StoragePciTransportState::new(
            device.origin,
            sbdf,
            bar_range,
            transport,
        )),
        retry,
        captured,
    ))
}

fn capture_ready_pci_pmem_state(
    runtime_resources: &Arm64BootRuntimeResources,
    pci_data_devices: &Option<HvfArm64BootPciDataDevices>,
    index: usize,
    config: &PmemConfig,
    retry: StorageRetryState,
    now: Instant,
) -> Result<CaptureReadyPmemDeviceState, HvfArm64BootStorageCaptureError> {
    let device = pci_data_devices
        .as_ref()
        .and_then(|devices| devices.pmem.get(index))
        .filter(|device| device.pmem_id == config.id())
        .ok_or_else(|| {
            HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
                false,
            )
        })?;
    let mut prepared_matches = runtime_resources
        .pmem_devices
        .iter()
        .filter(|prepared| prepared.id() == config.id());
    let prepared = prepared_matches.next().ok_or_else(|| {
        HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
            false,
        )
    })?;
    if prepared_matches.next().is_some()
        || prepared.guest_range() != device.guest_range
        || prepared.backing().len() != prepared.mapping().file_len()
        || prepared.mapping().mapped_len() != prepared.guest_range().size()
        || prepared.backing().is_read_only() != config.read_only()
        || prepared.mapping().is_read_only() != config.read_only()
    {
        return Err(HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::InventoryMismatch,
            false,
        ));
    }
    let (captured, transport) = device
        .published
        .endpoint()
        .capture_pmem_device_state_at(prepared.mapping().file_len(), config.rate_limiter(), now)
        .map_err(|_| {
            HvfArm64BootStorageCaptureError::new(
                HvfArm64BootStorageCaptureErrorKind::PmemCapture,
                false,
            )
        })?;
    let backing = prepared.backing().capture_identity().map_err(|_| {
        HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::PmemCapture,
            false,
        )
    })?;
    let mapping = prepared.mapping().capture_identity();
    let sbdf = device.published.sbdf().ok_or_else(|| {
        HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::PciPlacement,
            false,
        )
    })?;
    let bar_range = device.published.bar_range().ok_or_else(|| {
        HvfArm64BootStorageCaptureError::new(
            HvfArm64BootStorageCaptureErrorKind::PciPlacement,
            false,
        )
    })?;
    Ok(CaptureReadyPmemDeviceState::new(
        config.clone(),
        prepared.guest_range(),
        backing,
        mapping,
        StorageTransportState::Pci(StoragePciTransportState::new(
            device.origin,
            sbdf,
            bar_range,
            transport,
        )),
        retry,
        captured,
    ))
}

fn build_snapshot_v1_state(
    runtime_resources: &Arm64BootRuntimeResources,
    gic: HvfGicMetadata,
    primary_mpidr: u64,
    cache_manifest: crate::vcpu_config::HvfArm64VcpuCacheManifest,
    runner_capture: HvfArm64SnapshotV1Capture,
    device: SnapshotV1DeviceState,
) -> Result<HvfSnapshotV1State, HvfArm64BootSnapshotV1StateCaptureError> {
    let rtc = runtime_resources
        .rtc_device
        .as_ref()
        .ok_or(HvfArm64BootSnapshotV1StateCaptureError::MissingRtc)?;
    let rtc_mmio_layout = RtcMmioLayout::new(rtc.region.range().start(), rtc.region.id());
    let (identification, optional_identification, vcpu, interrupts) = runner_capture.into_parts();
    let compatibility = HvfSnapshotV1CompatibilityState::new(
        identification,
        optional_identification,
        cache_manifest,
        primary_mpidr,
        gic,
        rtc_mmio_layout,
    );
    let state = HvfSnapshotV1State::new(
        runtime_resources.machine_config,
        compatibility,
        vcpu,
        interrupts,
        device,
    );
    // Fail before streaming guest memory if any fixed component, nested device
    // value, or compatibility relationship cannot be encoded.
    encode_hvf_snapshot_v1_state(&state)
        .map_err(|source| HvfArm64BootSnapshotV1StateCaptureError::EncodePreflight { source })?;
    Ok(state)
}

struct HvfArm64BootSnapshotV2CaptureOwner<'a, 'vm> {
    runner: &'a mut HvfArm64BootVcpuSession<'vm>,
    backend: &'a HvfBackend,
    runtime_resources: &'a Arm64BootRuntimeResources,
    cpu_template_application: Option<&'a crate::cpu_template::HvfArm64CpuTemplateApplicationState>,
    cache_source: crate::vcpu_config::HvfArm64VcpuCacheFdtSource,
    gic: HvfGicMetadata,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum HvfArm64BootSnapshotV2PlatformProfile {
    Legacy,
    ProductProcess,
}

fn hvf_arm64_boot_snapshot_v2_platform_profile(
    version: SnapshotFormatVersion,
) -> Option<HvfArm64BootSnapshotV2PlatformProfile> {
    match version {
        NATIVE_V2_LEGACY_PLATFORM_VERSION => Some(HvfArm64BootSnapshotV2PlatformProfile::Legacy),
        NATIVE_V2_DEVICE_GRAPH_COMPATIBILITY_VERSION
        | NATIVE_V2_MULTI_BLOCK_DEVICE_GRAPH_COMPATIBILITY_VERSION
        | NATIVE_V2_STORAGE_DEVICE_GRAPH_COMPATIBILITY_VERSION
        | NATIVE_V2_SERIAL_STATE_COMPATIBILITY_VERSION
        | NATIVE_V2_ENTROPY_STATE_COMPATIBILITY_VERSION
        | NATIVE_V2_BALLOON_STATE_COMPATIBILITY_VERSION
        | NATIVE_V2_MEMORY_HOTPLUG_STATE_COMPATIBILITY_VERSION
        | NATIVE_V2_NETWORK_STATE_COMPATIBILITY_VERSION
        | NATIVE_V2_VSOCK_STATE_COMPATIBILITY_VERSION
        | NATIVE_V2_DIFF_STATE_COMPATIBILITY_VERSION => {
            Some(HvfArm64BootSnapshotV2PlatformProfile::ProductProcess)
        }
        _ => None,
    }
}

impl HvfArm64BootSnapshotV2CaptureOwner<'_, '_> {
    fn capture(
        self,
        input: HvfArm64BootSnapshotV2CaptureInput,
        memory_writer: &mut (impl std::io::Write + std::io::Seek),
    ) -> Result<HvfSnapshotV2PlatformState, HvfArm64BootSnapshotV2CaptureError> {
        self.capture_with_cancel(input, memory_writer, |_| false)
    }

    fn capture_with_cancel(
        self,
        input: HvfArm64BootSnapshotV2CaptureInput,
        memory_writer: &mut (impl std::io::Write + std::io::Seek),
        is_cancelled: impl FnMut(SnapshotV2MemoryIoStage) -> bool,
    ) -> Result<HvfSnapshotV2PlatformState, HvfArm64BootSnapshotV2CaptureError> {
        self.capture_with_compatibility_version_and_cancel(
            input,
            memory_writer,
            NATIVE_V2_LEGACY_PLATFORM_VERSION,
            is_cancelled,
        )
    }

    fn capture_with_compatibility_version_and_cancel(
        self,
        input: HvfArm64BootSnapshotV2CaptureInput,
        memory_writer: &mut (impl std::io::Write + std::io::Seek),
        version: SnapshotFormatVersion,
        is_cancelled: impl FnMut(SnapshotV2MemoryIoStage) -> bool,
    ) -> Result<HvfSnapshotV2PlatformState, HvfArm64BootSnapshotV2CaptureError> {
        self.capture_with_compatibility_version_and_cancel_using(
            input,
            memory_writer,
            version,
            is_cancelled,
            HvfSnapshotV2PlatformState::try_new,
        )
    }

    fn capture_with_compatibility_version_and_cancel_using<T>(
        self,
        input: HvfArm64BootSnapshotV2CaptureInput,
        memory_writer: &mut (impl std::io::Write + std::io::Seek),
        version: SnapshotFormatVersion,
        is_cancelled: impl FnMut(SnapshotV2MemoryIoStage) -> bool,
        finalize: impl FnOnce(
            SnapshotV2MemoryBinding,
            HvfSnapshotV2MachineState,
            HvfSnapshotV2GlobalState,
            HvfArm64StablePausedTopologyState,
            Vec<HvfSnapshotV2VcpuState>,
            HvfSnapshotV2TimeState,
        ) -> Result<T, HvfSnapshotV2BuildError>,
    ) -> Result<T, HvfArm64BootSnapshotV2CaptureError> {
        self.capture_with_compatibility_version_and_cancel_using_result(
            input,
            memory_writer,
            version,
            move |memory, memory_writer| {
                write_snapshot_v2_memory_image_with_compatibility_version_and_cancel(
                    memory,
                    memory_writer,
                    version,
                    is_cancelled,
                )
                .map_err(|source| HvfArm64BootSnapshotV2CaptureError::MemoryImage { source })
            },
            finalize,
        )
    }

    fn capture_with_compatibility_version_and_cancel_using_result<T, R, W>(
        self,
        input: HvfArm64BootSnapshotV2CaptureInput,
        memory_writer: &mut W,
        version: SnapshotFormatVersion,
        produce_result: impl FnOnce(
            &GuestMemory,
            &mut W,
        ) -> Result<R, HvfArm64BootSnapshotV2CaptureError>,
        finalize: impl FnOnce(
            R,
            HvfSnapshotV2MachineState,
            HvfSnapshotV2GlobalState,
            HvfArm64StablePausedTopologyState,
            Vec<HvfSnapshotV2VcpuState>,
            HvfSnapshotV2TimeState,
        ) -> Result<T, HvfSnapshotV2BuildError>,
    ) -> Result<T, HvfArm64BootSnapshotV2CaptureError>
    where
        W: std::io::Write + std::io::Seek,
    {
        let guest_logger = self.backend.guest_logger();
        let profile = hvf_arm64_boot_snapshot_v2_platform_profile(version);
        debug_assert!(profile.is_some());
        let topology_result = self.runner.capture_arm64_snapshot_v2_topology();
        observe_pvtime_topology_capture(&guest_logger, &topology_result);
        let (stable, captures, pvtime_capture) = topology_result
            .map_err(|source| HvfArm64BootSnapshotV2CaptureError::Topology { source })?;
        let memory = self
            .backend
            .mapped_guest_memory()
            .map_err(|source| HvfArm64BootSnapshotV2CaptureError::GuestMemory { source })?;
        let boot = input.into_boot();

        let fdt_write = self
            .runtime_resources
            .boot_origin
            .as_ref()
            .map(|origin| origin.fdt)
            .or(self.runtime_resources.retained_fdt)
            .ok_or(HvfArm64BootSnapshotV2CaptureError::MissingBootOrigin)?;
        let rtc = self
            .runtime_resources
            .rtc_device
            .as_ref()
            .ok_or(HvfArm64BootSnapshotV2CaptureError::MissingRtc)?;
        let mut fdt_bytes = Vec::new();
        fdt_bytes
            .try_reserve_exact(fdt_write.size)
            .map_err(|_| HvfArm64BootSnapshotV2CaptureError::FdtAllocation)?;
        fdt_bytes.resize(fdt_write.size, 0);
        memory
            .read_slice(&mut fdt_bytes, fdt_write.address)
            .map_err(|source| HvfArm64BootSnapshotV2CaptureError::FdtRead { source })?;
        let fdt_checksum = crc64(0, &fdt_bytes);
        let fdt = if profile == Some(HvfArm64BootSnapshotV2PlatformProfile::ProductProcess) {
            HvfSnapshotV2FdtState::try_new_product_process_profile(
                fdt_write.address,
                fdt_write.size,
                fdt_checksum,
            )
        } else {
            HvfSnapshotV2FdtState::try_new(fdt_write.address, fdt_write.size, fdt_checksum)
        }
        .map_err(|source| HvfArm64BootSnapshotV2CaptureError::Build {
            stage: HvfArm64BootSnapshotV2CaptureStage::Machine,
            source,
        })?;

        let primary = captures
            .first()
            .ok_or(HvfArm64BootSnapshotV2CaptureError::CompatibilityMismatch { index: 0 })?;
        let primary_member = stable
            .members()
            .first()
            .ok_or(HvfArm64BootSnapshotV2CaptureError::CompatibilityMismatch { index: 0 })?;
        let primary_identification = primary.identification();
        let primary_optional_identification = primary.optional_identification();
        if primary_identification.id_aa64mmfr2_el1() != self.cache_source.id_aa64mmfr2_el1() {
            return Err(HvfArm64BootSnapshotV2CaptureError::CompatibilityMismatch { index: 0 });
        }
        if captures.len() != stable.members().len() {
            return Err(HvfArm64BootSnapshotV2CaptureError::CompatibilityMismatch {
                index: captures.len(),
            });
        }
        for (capture, member) in captures.iter().zip(stable.members()) {
            if capture.identification().mpidr_el1() != member.mpidr()
                || !same_common_arm64_identification(
                    capture.identification(),
                    primary_identification,
                )
                || capture.optional_identification() != primary_optional_identification
            {
                return Err(HvfArm64BootSnapshotV2CaptureError::CompatibilityMismatch {
                    index: member.index(),
                });
            }
            if (member.index() == 0) != capture.gic_device().is_some() {
                return Err(HvfArm64BootSnapshotV2CaptureError::GlobalGicShape {
                    index: member.index(),
                });
            }
        }

        let mut vcpus = Vec::new();
        vcpus
            .try_reserve_exact(captures.len())
            .map_err(|_| HvfArm64BootSnapshotV2CaptureError::Allocation)?;
        let mut global_gic = None;
        for (capture, member) in captures.into_iter().zip(stable.members()) {
            let (
                _identification,
                _optional_identification,
                mandatory,
                timer,
                pending_interrupts,
                captured_global_gic,
                gic_icc,
                reviewed_optional,
            ) = capture.into_parts();
            if member.index() == 0 {
                global_gic = captured_global_gic;
            }
            let index = u32::try_from(member.index()).map_err(|_| {
                HvfArm64BootSnapshotV2CaptureError::CompatibilityMismatch {
                    index: member.index(),
                }
            })?;
            let vcpu = HvfSnapshotV2VcpuState::try_new(
                index,
                member.mpidr(),
                mandatory,
                timer,
                pending_interrupts,
                gic_icc,
                reviewed_optional,
            )
            .map_err(|source| HvfArm64BootSnapshotV2CaptureError::Build {
                stage: HvfArm64BootSnapshotV2CaptureStage::Vcpu {
                    index: member.index(),
                },
                source,
            })?;
            vcpus.push(vcpu);
        }
        let global_gic =
            global_gic.ok_or(HvfArm64BootSnapshotV2CaptureError::GlobalGicShape { index: 0 })?;

        let rtc_mmio_layout = RtcMmioLayout::new(rtc.region.range().start(), rtc.region.id());
        let time = capture_hvf_snapshot_v2_time_state(
            memory,
            rtc_mmio_layout,
            &self.runtime_resources.vmgenid_device,
            &self.runtime_resources.vmclock_device,
            self.runtime_resources.pvtime_state.layout(),
            &pvtime_capture,
        )
        .map_err(|source| HvfArm64BootSnapshotV2CaptureError::Time { source })?;
        let compatibility = HvfSnapshotV1CompatibilityState::new(
            primary_identification,
            primary_optional_identification,
            self.cache_source.manifest(),
            primary_member.mpidr(),
            self.gic,
            rtc_mmio_layout,
        );
        let machine = HvfSnapshotV2MachineState::try_new(
            self.runtime_resources.machine_config,
            boot,
            fdt,
            self.cpu_template_application.cloned(),
        )
        .map_err(|source| HvfArm64BootSnapshotV2CaptureError::Build {
            stage: HvfArm64BootSnapshotV2CaptureStage::Machine,
            source,
        })?;
        let global =
            HvfSnapshotV2GlobalState::try_new(compatibility, global_gic).map_err(|source| {
                HvfArm64BootSnapshotV2CaptureError::Build {
                    stage: HvfArm64BootSnapshotV2CaptureStage::GlobalGic,
                    source,
                }
            })?;
        let result = produce_result(memory, memory_writer)?;
        finalize(result, machine, global, stable, vcpus, time).map_err(|source| {
            HvfArm64BootSnapshotV2CaptureError::Build {
                stage: HvfArm64BootSnapshotV2CaptureStage::Platform,
                source,
            }
        })
    }
}

fn same_common_arm64_identification(
    left: HvfArm64VcpuIdentificationRegisterState,
    right: HvfArm64VcpuIdentificationRegisterState,
) -> bool {
    left.midr_el1() == right.midr_el1()
        && left.id_aa64pfr0_el1() == right.id_aa64pfr0_el1()
        && left.id_aa64pfr1_el1() == right.id_aa64pfr1_el1()
        && left.id_aa64dfr0_el1() == right.id_aa64dfr0_el1()
        && left.id_aa64dfr1_el1() == right.id_aa64dfr1_el1()
        && left.id_aa64isar0_el1() == right.id_aa64isar0_el1()
        && left.id_aa64isar1_el1() == right.id_aa64isar1_el1()
        && left.id_aa64mmfr0_el1() == right.id_aa64mmfr0_el1()
        && left.id_aa64mmfr1_el1() == right.id_aa64mmfr1_el1()
        && left.id_aa64mmfr2_el1() == right.id_aa64mmfr2_el1()
}

fn check_snapshot_v1_capture_cancelled(
    is_cancelled: &mut impl FnMut(HvfArm64BootSnapshotV1CaptureStage) -> bool,
    stage: HvfArm64BootSnapshotV1CaptureStage,
) -> Result<(), HvfArm64BootSnapshotV1StateCaptureError> {
    if is_cancelled(stage) {
        Err(HvfArm64BootSnapshotV1StateCaptureError::Cancelled { stage })
    } else {
        Ok(())
    }
}

fn retained_snapshot_cache_manifest(
    source: crate::vcpu_config::HvfArm64VcpuCacheFdtSource,
    runner_id_aa64mmfr2_el1: u64,
) -> Result<crate::vcpu_config::HvfArm64VcpuCacheManifest, HvfArm64BootSnapshotV1StateCaptureError>
{
    if runner_id_aa64mmfr2_el1 != source.id_aa64mmfr2_el1() {
        return Err(HvfArm64BootSnapshotV1StateCaptureError::CacheIdentityMismatch);
    }
    Ok(source.manifest())
}

/// Describes why a boot session could not quiesce its limiter retry wakeups.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HvfArm64BootLimiterRetryWakeupQuiescenceError {
    BlockAlreadyQuiesced,
    BlockStopped,
    PmemAlreadyQuiesced,
    PmemStopped,
    NetworkAlreadyQuiesced,
    NetworkStopped,
    EntropyAlreadyQuiesced,
    EntropyStopped,
}

impl fmt::Display for HvfArm64BootLimiterRetryWakeupQuiescenceError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::BlockAlreadyQuiesced => {
                f.write_str("block limiter retry wakeups are already quiesced")
            }
            Self::BlockStopped => f.write_str("block limiter retry wakeup scheduler is stopped"),
            Self::PmemAlreadyQuiesced => {
                f.write_str("pmem limiter retry wakeups are already quiesced")
            }
            Self::PmemStopped => f.write_str("pmem limiter retry wakeup scheduler is stopped"),
            Self::NetworkAlreadyQuiesced => {
                f.write_str("network limiter retry wakeups are already quiesced")
            }
            Self::NetworkStopped => {
                f.write_str("network limiter retry wakeup scheduler is stopped")
            }
            Self::EntropyAlreadyQuiesced => {
                f.write_str("entropy limiter retry wakeups are already quiesced")
            }
            Self::EntropyStopped => {
                f.write_str("entropy limiter retry wakeup scheduler is stopped")
            }
        }
    }
}

impl std::error::Error for HvfArm64BootLimiterRetryWakeupQuiescenceError {}

#[derive(Clone, Copy)]
struct HvfArm64BootLimiterRetryWakeupOwner<'a> {
    wakeup: &'a HvfArm64BootLimiterRetryWakeupToken,
    scheduler: &'a HvfArm64BootLimiterRetryWakeupScheduler,
}

impl<'a> HvfArm64BootLimiterRetryWakeupOwner<'a> {
    const fn new(
        wakeup: &'a HvfArm64BootLimiterRetryWakeupToken,
        scheduler: &'a HvfArm64BootLimiterRetryWakeupScheduler,
    ) -> Self {
        Self { wakeup, scheduler }
    }
}

fn quiesce_limiter_retry_wakeups(
    block: HvfArm64BootLimiterRetryWakeupOwner<'_>,
    pmem: HvfArm64BootLimiterRetryWakeupOwner<'_>,
    network: HvfArm64BootLimiterRetryWakeupOwner<'_>,
    entropy: HvfArm64BootLimiterRetryWakeupOwner<'_>,
) -> Result<
    HvfArm64BootLimiterRetryWakeupQuiescenceGuard,
    HvfArm64BootLimiterRetryWakeupQuiescenceError,
> {
    let block_guard = block.scheduler.quiesce().map_err(|err| match err {
        HvfArm64BootLimiterRetryWakeupSchedulerQuiescenceError::AlreadyQuiesced => {
            HvfArm64BootLimiterRetryWakeupQuiescenceError::BlockAlreadyQuiesced
        }
        HvfArm64BootLimiterRetryWakeupSchedulerQuiescenceError::Stopped => {
            HvfArm64BootLimiterRetryWakeupQuiescenceError::BlockStopped
        }
    })?;
    let pmem_guard = pmem.scheduler.quiesce().map_err(|err| match err {
        HvfArm64BootLimiterRetryWakeupSchedulerQuiescenceError::AlreadyQuiesced => {
            HvfArm64BootLimiterRetryWakeupQuiescenceError::PmemAlreadyQuiesced
        }
        HvfArm64BootLimiterRetryWakeupSchedulerQuiescenceError::Stopped => {
            HvfArm64BootLimiterRetryWakeupQuiescenceError::PmemStopped
        }
    })?;
    let network_guard = network.scheduler.quiesce().map_err(|err| match err {
        HvfArm64BootLimiterRetryWakeupSchedulerQuiescenceError::AlreadyQuiesced => {
            HvfArm64BootLimiterRetryWakeupQuiescenceError::NetworkAlreadyQuiesced
        }
        HvfArm64BootLimiterRetryWakeupSchedulerQuiescenceError::Stopped => {
            HvfArm64BootLimiterRetryWakeupQuiescenceError::NetworkStopped
        }
    })?;
    let entropy_guard = entropy.scheduler.quiesce().map_err(|err| match err {
        HvfArm64BootLimiterRetryWakeupSchedulerQuiescenceError::AlreadyQuiesced => {
            HvfArm64BootLimiterRetryWakeupQuiescenceError::EntropyAlreadyQuiesced
        }
        HvfArm64BootLimiterRetryWakeupSchedulerQuiescenceError::Stopped => {
            HvfArm64BootLimiterRetryWakeupQuiescenceError::EntropyStopped
        }
    })?;

    if block.wakeup.take_wakeup_request() {
        block_guard.defer_publication();
    }
    if pmem.wakeup.take_wakeup_request() {
        pmem_guard.defer_publication();
    }
    if network.wakeup.take_wakeup_request() {
        network_guard.defer_publication();
    }
    if entropy.wakeup.take_wakeup_request() {
        entropy_guard.defer_publication();
    }

    Ok(HvfArm64BootLimiterRetryWakeupQuiescenceGuard {
        block: block_guard,
        pmem: pmem_guard,
        network: network_guard,
        entropy: entropy_guard,
    })
}

#[derive(Debug)]
struct HvfArm64BootLimiterRetryWakeupPublicationGuard {
    shared: Arc<HvfArm64BootLimiterRetryWakeupSchedulerShared>,
}

impl Drop for HvfArm64BootLimiterRetryWakeupPublicationGuard {
    fn drop(&mut self) {
        let mut state = lock_limiter_retry_wakeup_state(&self.shared);
        state.publication_in_flight = false;
        self.shared.condvar.notify_all();
    }
}

fn limiter_retry_deadline_after(delay: Duration) -> Instant {
    let now = Instant::now();
    now.checked_add(delay).unwrap_or(now)
}

fn lock_limiter_retry_wakeup_state(
    shared: &HvfArm64BootLimiterRetryWakeupSchedulerShared,
) -> MutexGuard<'_, HvfArm64BootLimiterRetryWakeupSchedulerState> {
    match shared.state.lock() {
        Ok(state) => state,
        Err(poisoned) => poisoned.into_inner(),
    }
}

fn wait_limiter_retry_wakeup_state<'a>(
    shared: &'a HvfArm64BootLimiterRetryWakeupSchedulerShared,
    state: MutexGuard<'a, HvfArm64BootLimiterRetryWakeupSchedulerState>,
) -> MutexGuard<'a, HvfArm64BootLimiterRetryWakeupSchedulerState> {
    match shared.condvar.wait(state) {
        Ok(state) => state,
        Err(poisoned) => poisoned.into_inner(),
    }
}

fn wait_limiter_retry_wakeup_state_timeout<'a>(
    shared: &'a HvfArm64BootLimiterRetryWakeupSchedulerShared,
    state: MutexGuard<'a, HvfArm64BootLimiterRetryWakeupSchedulerState>,
    timeout: Duration,
) -> MutexGuard<'a, HvfArm64BootLimiterRetryWakeupSchedulerState> {
    match shared.condvar.wait_timeout(state, timeout) {
        Ok((state, _)) => state,
        Err(poisoned) => poisoned.into_inner().0,
    }
}

fn wait_to_publish_limiter_retry_wakeup(
    shared: Arc<HvfArm64BootLimiterRetryWakeupSchedulerShared>,
) -> bool {
    let mut state = lock_limiter_retry_wakeup_state(&shared);
    loop {
        match state.status {
            HvfArm64BootLimiterRetryWakeupSchedulerStatus::Running => {}
            HvfArm64BootLimiterRetryWakeupSchedulerStatus::Quiesced => {
                state = wait_limiter_retry_wakeup_state(&shared, state);
                continue;
            }
            HvfArm64BootLimiterRetryWakeupSchedulerStatus::Stopped => return false,
        }
        if state.construction_publication_blocked {
            state = wait_limiter_retry_wakeup_state(&shared, state);
            continue;
        }

        let now = Instant::now();
        if state.deferred_publication {
            state.deferred_publication = false;
            if state.deadline.is_some_and(|deadline| deadline <= now) {
                state.deadline = None;
            }
            state.publication_in_flight = true;
            return true;
        }

        let Some(deadline) = state.deadline else {
            state = wait_limiter_retry_wakeup_state(&shared, state);
            continue;
        };

        if deadline <= now {
            state.deadline = None;
            state.publication_in_flight = true;
            return true;
        }

        state = wait_limiter_retry_wakeup_state_timeout(
            &shared,
            state,
            deadline.saturating_duration_since(now),
        );
    }
}

fn run_limiter_retry_wakeup_scheduler<R>(
    shared: Arc<HvfArm64BootLimiterRetryWakeupSchedulerShared>,
    wakeup_token: HvfArm64BootLimiterRetryWakeupToken,
    cancel_vcpu_run: impl Fn() -> R,
) {
    while wait_to_publish_limiter_retry_wakeup(Arc::clone(&shared)) {
        let _publication = HvfArm64BootLimiterRetryWakeupPublicationGuard {
            shared: Arc::clone(&shared),
        };
        wakeup_token.request_wakeup();
        let _cancel_result = cancel_vcpu_run();
    }
}

#[derive(Debug, Clone, Default)]
struct HvfArm64BootRunLoopControlWakeupToken {
    wakeup_requested: Arc<AtomicBool>,
}

impl HvfArm64BootRunLoopControlWakeupToken {
    fn request_wakeup(&self) {
        self.wakeup_requested.store(true, Ordering::Relaxed);
    }

    fn take_wakeup_request(&self) -> bool {
        self.wakeup_requested.swap(false, Ordering::Relaxed)
    }
}

#[derive(Debug, Clone)]
pub struct HvfArm64BootRunLoopControl {
    stop_token: HvfArm64BootRunLoopStopToken,
    control_wakeup: HvfArm64BootRunLoopControlWakeupToken,
    vcpu_control: HvfVcpuRunControl,
}

impl HvfArm64BootRunLoopControl {
    fn new(
        vcpu_control: HvfVcpuRunControl,
        control_wakeup: HvfArm64BootRunLoopControlWakeupToken,
    ) -> Self {
        Self {
            stop_token: HvfArm64BootRunLoopStopToken::new(),
            control_wakeup,
            vcpu_control,
        }
    }

    pub fn stop_token(&self) -> HvfArm64BootRunLoopStopToken {
        self.stop_token.clone()
    }

    /// Request a sticky run-loop stop and interrupt the current topology run.
    ///
    /// If the topology can no longer accept a control barrier, the stop flag
    /// remains set so a run loop that regains control still observes the
    /// request. The returned error reports only the failed vCPU interruption.
    pub fn request_stop(&self) -> Result<(), HvfVcpuRunCoordinatorError> {
        self.stop_token.request_stop();
        self.vcpu_control.request_stop().map(|_| ())
    }

    /// Wake the boot run loop without requesting guest shutdown.
    ///
    /// This is runner-command plumbing for future runtime device updates. It
    /// lets the process worker regain control while keeping stop semantics
    /// separate from ordinary command dispatch. A failed vCPU interruption
    /// leaves the wakeup pending so a run loop that regains control does not
    /// lose the request.
    pub fn request_wakeup(&self) -> Result<(), HvfVcpuRunCoordinatorError> {
        self.control_wakeup.request_wakeup();
        self.vcpu_control.request_wakeup().map(|_| ())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HvfArm64BootRunLoopOutcome {
    StepLimitReached { steps: usize },
    Wakeup { steps: usize },
    Stopped { steps: usize },
    Canceled { steps: usize },
    GuestShutdown { steps: usize },
    GuestReset { steps: usize },
    Unknown { steps: usize, reason: u32 },
}

#[derive(Debug)]
pub enum HvfArm64BootRunLoopError {
    StartWakeupMonitor {
        steps_completed: usize,
        source: Box<HvfArm64BootRunLoopWakeupMonitorError>,
    },
    RunStep {
        steps_completed: usize,
        source: Box<HvfArm64BootVcpuError>,
    },
    StopWakeupMonitor {
        steps_completed: usize,
        source: Box<HvfArm64BootRunLoopWakeupMonitorError>,
    },
    DispatchSerialInput {
        steps_completed: usize,
        source: Box<HvfArm64BootSerialInputDispatchError>,
    },
    DispatchBlockNotifications {
        steps_completed: usize,
        source: Box<HvfArm64BootBlockNotificationDispatchError>,
    },
    DispatchPmemNotifications {
        steps_completed: usize,
        source: Box<HvfArm64BootPmemNotificationDispatchError>,
    },
    DispatchNetworkNotifications {
        steps_completed: usize,
        source: Box<HvfArm64BootNetworkNotificationDispatchError>,
    },
    DispatchVsockNotifications {
        steps_completed: usize,
        source: Box<HvfArm64BootVsockNotificationDispatchError>,
    },
    DispatchBalloonNotifications {
        steps_completed: usize,
        source: Box<HvfArm64BootBalloonNotificationDispatchError>,
    },
    DispatchMemoryHotplugNotifications {
        steps_completed: usize,
        source: Box<HvfArm64BootMemoryHotplugNotificationDispatchError>,
    },
    DispatchEntropyNotifications {
        steps_completed: usize,
        source: Box<HvfArm64BootEntropyNotificationDispatchError>,
    },
    HandleVirtualTimer {
        steps_completed: usize,
        source: Box<HvfArm64BootVcpuError>,
    },
}

impl fmt::Display for HvfArm64BootRunLoopError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::StartWakeupMonitor {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to start HVF boot-session wakeup monitor after {steps_completed} completed steps: {source}"
            ),
            Self::RunStep {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to run HVF boot-session vCPU step after {steps_completed} completed steps: {source}"
            ),
            Self::StopWakeupMonitor {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to stop HVF boot-session wakeup monitor after {steps_completed} completed steps: {source}"
            ),
            Self::DispatchSerialInput {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to dispatch HVF boot-session serial input after {steps_completed} completed steps: {source}"
            ),
            Self::DispatchBlockNotifications {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to dispatch HVF boot-session block notifications after {steps_completed} completed steps: {source}"
            ),
            Self::DispatchPmemNotifications {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to dispatch HVF boot-session pmem notifications after {steps_completed} completed steps: {source}"
            ),
            Self::DispatchNetworkNotifications {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to dispatch HVF boot-session network notifications after {steps_completed} completed steps: {source}"
            ),
            Self::DispatchVsockNotifications {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to dispatch HVF boot-session vsock notifications after {steps_completed} completed steps: {source}"
            ),
            Self::DispatchBalloonNotifications {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to dispatch HVF boot-session balloon notifications after {steps_completed} completed steps: {source}"
            ),
            Self::DispatchMemoryHotplugNotifications {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to dispatch HVF boot-session memory-hotplug notifications after {steps_completed} completed steps: {source}"
            ),
            Self::DispatchEntropyNotifications {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to dispatch HVF boot-session entropy notifications after {steps_completed} completed steps: {source}"
            ),
            Self::HandleVirtualTimer {
                steps_completed,
                source,
            } => write!(
                f,
                "failed to handle HVF boot-session virtual timer after {steps_completed} completed steps: {source}"
            ),
        }
    }
}

impl std::error::Error for HvfArm64BootRunLoopError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::StartWakeupMonitor { source, .. } => Some(source.as_ref()),
            Self::RunStep { source, .. } => Some(source.as_ref()),
            Self::StopWakeupMonitor { source, .. } => Some(source.as_ref()),
            Self::DispatchSerialInput { source, .. } => Some(source.as_ref()),
            Self::DispatchBlockNotifications { source, .. } => Some(source.as_ref()),
            Self::DispatchPmemNotifications { source, .. } => Some(source.as_ref()),
            Self::DispatchNetworkNotifications { source, .. } => Some(source.as_ref()),
            Self::DispatchVsockNotifications { source, .. } => Some(source.as_ref()),
            Self::DispatchBalloonNotifications { source, .. } => Some(source.as_ref()),
            Self::DispatchMemoryHotplugNotifications { source, .. } => Some(source.as_ref()),
            Self::DispatchEntropyNotifications { source, .. } => Some(source.as_ref()),
            Self::HandleVirtualTimer { source, .. } => Some(source.as_ref()),
        }
    }
}

#[derive(Debug)]
pub enum HvfArm64BootRunLoopWakeupMonitorError {
    MmioDispatcher {
        source: HvfArm64BootMmioDispatcherError,
    },
    CollectVsockWakeupFds {
        source: Arm64BootVsockWakeupFdsError,
    },
    CollectBlockWakeupFds {
        source: Arm64BootBlockWakeupFdsError,
    },
    PciVsockWakeup {
        message: String,
    },
    PciBlockWakeup {
        message: String,
    },
    PollFdAllocation {
        source: TryReserveError,
    },
    TooManyPollFds {
        count: usize,
    },
    CreateStopPipe {
        source: io::ErrorKind,
    },
    ThreadSpawn {
        source: io::Error,
    },
    StopSignal {
        source: io::ErrorKind,
    },
    ThreadPanicked,
}

impl fmt::Display for HvfArm64BootRunLoopWakeupMonitorError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MmioDispatcher { source } => {
                write!(
                    f,
                    "failed to lock HVF boot-session MMIO dispatcher: {source}"
                )
            }
            Self::CollectVsockWakeupFds { source } => {
                write!(f, "failed to collect boot vsock wakeup fds: {source}")
            }
            Self::CollectBlockWakeupFds { source } => {
                write!(f, "failed to collect boot block wakeup fds: {source}")
            }
            Self::PciVsockWakeup { message } => {
                write!(f, "failed to collect PCI vsock wakeup fds: {message}")
            }
            Self::PciBlockWakeup { message } => {
                write!(f, "failed to collect PCI block wakeup fds: {message}")
            }
            Self::PollFdAllocation { source } => {
                write!(
                    f,
                    "failed to allocate boot run-loop wakeup poll fd list: {source}"
                )
            }
            Self::TooManyPollFds { count } => {
                write!(f, "too many boot run-loop wakeup poll fds: {count}")
            }
            Self::CreateStopPipe { source } => {
                write!(
                    f,
                    "failed to create boot run-loop wakeup stop pipe: {source}"
                )
            }
            Self::ThreadSpawn { source } => {
                write!(f, "failed to spawn boot run-loop wakeup monitor: {source}")
            }
            Self::StopSignal { source } => {
                write!(
                    f,
                    "failed to signal boot run-loop wakeup monitor stop: {source}"
                )
            }
            Self::ThreadPanicked => f.write_str("boot run-loop wakeup monitor thread panicked"),
        }
    }
}

impl std::error::Error for HvfArm64BootRunLoopWakeupMonitorError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::CollectVsockWakeupFds { source } => Some(source),
            Self::CollectBlockWakeupFds { source } => Some(source),
            Self::PollFdAllocation { source } => Some(source),
            Self::ThreadSpawn { source } => Some(source),
            Self::MmioDispatcher { .. }
            | Self::PciVsockWakeup { .. }
            | Self::PciBlockWakeup { .. }
            | Self::TooManyPollFds { .. }
            | Self::CreateStopPipe { .. }
            | Self::StopSignal { .. }
            | Self::ThreadPanicked => None,
        }
    }
}

fn shutdown_block_async_before_guest_memory_teardown(
    backend: &mut HvfBackend,
    runtime_resources: &Arm64BootRuntimeResources,
) -> Result<(), HvfArm64BootSessionShutdownError> {
    if runtime_resources
        .shutdown_block_async_if_idle()
        .map_err(|source| HvfArm64BootSessionShutdownError::BlockAsync { source })?
    {
        return Ok(());
    }
    let memory = backend
        .mapped_guest_memory_mut()
        .map_err(|source| HvfArm64BootSessionShutdownError::BlockAsyncGuestMemory { source })?;
    runtime_resources
        .shutdown_block_async(memory)
        .map_err(|source| HvfArm64BootSessionShutdownError::BlockAsync { source })
}

