    #[allow(clippy::too_many_arguments)]
    fn restore_snapshot_v2_serial_entropy_pci_inner(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2RestoredSerialShell,
        serial_input: Option<SerialStdioInput>,
        endpoint_plan: HvfSnapshotV2EntropyPciEndpointPlan,
        entropy: SnapshotV2EntropyRestorePlan,
        inject_scheduler_failure: bool,
        source_factory: impl FnOnce() -> VirtioRngOsEntropySource,
    ) -> Result<RestoredHvfSnapshotV2EntropyPciOwners, HvfSnapshotV2EntropyPciRestoreError> {
        if !snapshot_v2_entropy_pci_plan_matches(&entropy, endpoint_plan) {
            return Err(HvfSnapshotV2EntropyPciRestoreError::preflight(
                HvfSnapshotV2EntropyPciRestoreStage::ResourcePlan,
                HvfSnapshotV2EntropyPciRestoreFailure::ResourcePlan,
            ));
        }
        let session = Self::restore_snapshot_v2_serial_only_inner(
            state,
            memory,
            HvfSnapshotV2SerialProcessShell::SerialOnly {
                shell: process_shell,
                process: HvfSnapshotV2SerialOnlyProcessConfig::with_exact_pci_msi_interrupt_count(
                    endpoint_plan.msi_interrupt_count(),
                ),
            },
            serial_input,
        )
        .map_err(HvfSnapshotV2EntropyPciRestoreError::serial_platform)?;
        Self::attach_snapshot_v2_entropy_pci(
            session,
            endpoint_plan,
            entropy,
            None,
            inject_scheduler_failure,
            source_factory,
            HvfSnapshotV2EntropyPciPrecedingEndpointCounts::new(0, 0),
        )
    }

    /// Reconstructs one exact-2.8 storage, serial, and PCI entropy
    /// destination without publishing it.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_serial_storage_entropy_pci(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2RestoredSerialShell,
        serial_input: Option<SerialStdioInput>,
        bundle: PreparedSnapshotV2StorageBundle,
        plan: HvfSnapshotV2StorageEntropyPciPlatformPlan,
        entropy: SnapshotV2EntropyRestorePlan,
    ) -> Result<RestoredHvfSnapshotV2EntropyPciOwners, HvfSnapshotV2EntropyPciRestoreError> {
        let (storage_plan, endpoint_plan) = plan.into_parts();
        if !snapshot_v2_entropy_pci_plan_matches(&entropy, endpoint_plan) {
            return Err(HvfSnapshotV2EntropyPciRestoreError::preflight(
                HvfSnapshotV2EntropyPciRestoreStage::ResourcePlan,
                HvfSnapshotV2EntropyPciRestoreFailure::ResourcePlan,
            ));
        }
        let restored = Self::restore_snapshot_v2_storage_pci_inner(
            state,
            memory,
            HvfSnapshotV2StorageProcessShell::Restored(process_shell),
            serial_input,
            bundle,
            storage_plan,
            HvfSnapshotV2StoragePciPublicationInput::empty(),
        )
        .map_err(HvfSnapshotV2EntropyPciRestoreError::storage_platform)?;
        let (session, storage_configs) = restored.into_parts();
        Self::attach_snapshot_v2_entropy_pci(
            session,
            endpoint_plan,
            entropy,
            Some(storage_configs),
            false,
            VirtioRngOsEntropySource::new,
            HvfSnapshotV2EntropyPciPrecedingEndpointCounts::new(0, 0),
        )
    }

    fn attach_snapshot_v2_entropy_pci(
        mut session: OwnedHvfArm64BootSession,
        endpoint_plan: HvfSnapshotV2EntropyPciEndpointPlan,
        mut entropy: SnapshotV2EntropyRestorePlan,
        storage_configs: Option<CaptureReadyStorageConfigs>,
        inject_scheduler_failure: bool,
        source_factory: impl FnOnce() -> VirtioRngOsEntropySource,
        preceding: HvfSnapshotV2EntropyPciPrecedingEndpointCounts,
    ) -> Result<RestoredHvfSnapshotV2EntropyPciOwners, HvfSnapshotV2EntropyPciRestoreError> {
        let preceding_endpoint_count = endpoint_plan.preceding_endpoint_count();
        let Some(preceding_storage_count) = preceding_endpoint_count
            .checked_sub(preceding.balloon)
            .and_then(|count| count.checked_sub(preceding.network))
            .and_then(|count| count.checked_sub(preceding.vsock))
        else {
            return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                session,
                HvfSnapshotV2EntropyPciRestoreStage::ResourcePlan,
                HvfSnapshotV2EntropyPciRestoreFailure::ResourcePlan,
            ));
        };
        let owner_is_vacant = session.runtime_resources.entropy_device.is_none()
            && session.runtime_resources.pci_entropy_device.is_none()
            && session.entropy_interrupt_line.is_none()
            && session.entropy_retry_wakeup_scheduler.thread.is_none()
            && session.pci_data_devices.as_ref().is_some_and(|manager| {
                manager.entropy.is_none()
                    && manager.network.len() == preceding.network
                    && manager.balloon.is_some() == (preceding.balloon == 1)
                    && preceding.balloon <= 1
                    && manager.vsock.is_some() == (preceding.vsock == 1)
                    && preceding.vsock <= 1
                    && manager.memory_hotplug.is_none()
                    && manager.endpoint_count() == preceding_endpoint_count
                    && manager.block.len().saturating_add(manager.pmem.len())
                        == preceding_storage_count
            });
        if !owner_is_vacant {
            return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                session,
                HvfSnapshotV2EntropyPciRestoreStage::ResourcePlan,
                HvfSnapshotV2EntropyPciRestoreFailure::ResourcePlan,
            ));
        }

        let entropy_device_metrics = SharedEntropyDeviceMetrics::default();
        entropy.attach_metrics(entropy_device_metrics.clone());

        let mut interrupts = match session.pci_data_devices.as_ref() {
            Some(manager) => match manager.shared_msi_registry() {
                Ok(interrupts) => interrupts,
                Err(source) => {
                    return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                        session,
                        HvfSnapshotV2EntropyPciRestoreStage::InterruptRoutes,
                        HvfSnapshotV2EntropyPciRestoreFailure::PciData(source),
                    ));
                }
            },
            None => {
                return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                    session,
                    HvfSnapshotV2EntropyPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2EntropyPciRestoreFailure::ResourcePlan,
                ));
            }
        };
        let entropy =
            match entropy.into_pci_endpoint(endpoint_plan.bar_region_id(), interrupts.registry()) {
                Ok(entropy) => entropy,
                Err(source) => {
                    let cleanup = interrupts.release().err();
                    return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                        session,
                        HvfSnapshotV2EntropyPciRestoreStage::Endpoint,
                        HvfSnapshotV2EntropyPciRestoreFailure::Endpoint { source, cleanup },
                    ));
                }
            };
        if entropy.endpoint().sbdf() != endpoint_plan.sbdf()
            || entropy.endpoint().bar_range() != endpoint_plan.bar_range()
            || entropy.endpoint().region_id() != endpoint_plan.bar_region_id()
        {
            drop(entropy);
            let cleanup = interrupts.release().err();
            return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                session,
                HvfSnapshotV2EntropyPciRestoreStage::ResourcePlan,
                HvfSnapshotV2EntropyPciRestoreFailure::ResourcePlanCleanup { cleanup },
            ));
        }
        let (config, _queue_ranges, _retry, retry_deadline, origin, endpoint) =
            entropy.into_parts();
        if origin != StorageDeviceOrigin::Startup {
            drop(endpoint);
            let cleanup = interrupts.release().err();
            return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                session,
                HvfSnapshotV2EntropyPciRestoreStage::ResourcePlan,
                HvfSnapshotV2EntropyPciRestoreFailure::ResourcePlanCleanup { cleanup },
            ));
        }

        let publication = {
            let manager = match session.pci_data_devices.as_mut() {
                Some(manager) => manager,
                None => {
                    drop(endpoint);
                    let cleanup = interrupts.release().err();
                    return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                        session,
                        HvfSnapshotV2EntropyPciRestoreStage::ResourcePlan,
                        HvfSnapshotV2EntropyPciRestoreFailure::ResourcePlanCleanup { cleanup },
                    ));
                }
            };
            let dispatcher_owner = Arc::clone(&manager.dispatcher);
            let segment = manager.validation.segment().clone();
            let mut dispatcher = match dispatcher_owner.lock() {
                Ok(dispatcher) => dispatcher,
                Err(_) => {
                    drop(endpoint);
                    let cleanup = interrupts.release().err();
                    return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                        session,
                        HvfSnapshotV2EntropyPciRestoreStage::Publication,
                        HvfSnapshotV2EntropyPciRestoreFailure::DispatcherUnavailable { cleanup },
                    ));
                }
            };
            match endpoint.publish(
                manager.validation.bar_allocator_mut(),
                segment,
                &mut dispatcher,
                interrupts,
            ) {
                Ok(published) => {
                    // This transfer is deliberately immediate and infallible:
                    // no published endpoint can exist outside the canonical
                    // manager owner, even when a later scheduler step fails.
                    manager.entropy = Some(HvfArm64BootPciEntropyDevice {
                        published,
                        queue_deliveries: 0,
                    });
                    Ok(())
                }
                Err(source) => Err(source),
            }
        };
        if let Err(source) = publication {
            return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                session,
                HvfSnapshotV2EntropyPciRestoreStage::Publication,
                HvfSnapshotV2EntropyPciRestoreFailure::Publication(source),
            ));
        }

        session.entropy_source = source_factory();
        session.entropy_device_metrics = entropy_device_metrics;
        session.entropy_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        if inject_scheduler_failure {
            return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                session,
                HvfSnapshotV2EntropyPciRestoreStage::RetryScheduler,
                HvfSnapshotV2EntropyPciRestoreFailure::InjectedRetryScheduler,
            ));
        }
        let vcpu_control = session.runner.control();
        session.entropy_retry_wakeup_scheduler =
            match HvfArm64BootLimiterRetryWakeupScheduler::start_with_cancellation(
                ENTROPY_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
                session.entropy_retry_wakeup.clone(),
                move || vcpu_control.request_wakeup(),
            ) {
                Ok(scheduler) => scheduler,
                Err(source) => {
                    return Err(HvfSnapshotV2EntropyPciRestoreError::after_platform(
                        session,
                        HvfSnapshotV2EntropyPciRestoreStage::RetryScheduler,
                        HvfSnapshotV2EntropyPciRestoreFailure::RetryScheduler(source.kind()),
                    ));
                }
            };

        // Deadline publication is intentionally the final graph operation.
        session
            .entropy_retry_wakeup_scheduler
            .schedule_deadline(retry_deadline);
        Ok(RestoredHvfSnapshotV2EntropyPciOwners {
            session,
            entropy_config: config,
            storage_configs,
        })
    }

    /// Reconstructs one exact native-v2 root-bearing destination and transfers
    /// it directly from the unpublished platform transaction into the complete
    /// product boot-session owner.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_root(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2DefaultProcessShell,
        root: PreparedSnapshotV2RootBlock,
        resources: HvfSnapshotV2RootResourcePlan,
    ) -> Result<Self, HvfSnapshotV2RootRestoreError> {
        let mut ranges = Vec::new();
        ranges
            .try_reserve_exact(memory.regions().len())
            .map_err(|_| {
                HvfSnapshotV2RootRestoreError::preflight(
                    HvfSnapshotV2RootRestoreStage::MemoryLayout,
                    HvfSnapshotV2RootRestoreFailure::Allocation,
                )
            })?;
        ranges.extend(memory.regions().iter().map(|region| region.range()));
        let layout = GuestMemoryLayout::new(ranges).map_err(|_| {
            HvfSnapshotV2RootRestoreError::preflight(
                HvfSnapshotV2RootRestoreStage::MemoryLayout,
                HvfSnapshotV2RootRestoreFailure::MemoryLayout,
            )
        })?;
        let source_fdt = state.machine().fdt();
        let retained_fdt = Arm64FdtGuestMemoryWrite {
            address: source_fdt.address(),
            size: usize::try_from(source_fdt.size()).map_err(|_| {
                HvfSnapshotV2RootRestoreError::preflight(
                    HvfSnapshotV2RootRestoreStage::MemoryLayout,
                    HvfSnapshotV2RootRestoreFailure::Allocation,
                )
            })?,
        };
        let transport = root.prepare_transport().map_err(|source| {
            HvfSnapshotV2RootRestoreError::preflight(
                HvfSnapshotV2RootRestoreStage::Transport,
                HvfSnapshotV2RootRestoreFailure::Transport(source),
            )
        })?;
        validate_snapshot_v2_root_resource_plan(&transport, resources)?;
        let (drive_id, retry_deadline) = snapshot_v2_root_identity_and_retry_deadline(&transport);
        let partuuid = match &transport {
            PreparedSnapshotV2RootTransport::Mmio(root) => root.partuuid(),
            PreparedSnapshotV2RootTransport::Pci(root) => root.partuuid(),
        }
        .map(str::to_owned);
        let metrics_capacity = match &transport {
            PreparedSnapshotV2RootTransport::Mmio(_) => 1,
            PreparedSnapshotV2RootTransport::Pci(_) => PCI_ENDPOINT_SLOT_COUNT,
        };
        let block_device_metrics = SharedBlockDeviceMetricsRegistry::from_drive_ids_with_capacity(
            [drive_id],
            metrics_capacity,
        )
        .map_err(|source| {
            HvfSnapshotV2RootRestoreError::preflight(
                HvfSnapshotV2RootRestoreStage::Metrics,
                HvfSnapshotV2RootRestoreFailure::Metrics(source),
            )
        })?;
        let mut block_devices = Vec::new();
        let mut block_interrupt_lines = Vec::new();
        if matches!(&transport, PreparedSnapshotV2RootTransport::Mmio(_)) {
            block_devices.try_reserve_exact(1).map_err(|_| {
                HvfSnapshotV2RootRestoreError::preflight(
                    HvfSnapshotV2RootRestoreStage::Transport,
                    HvfSnapshotV2RootRestoreFailure::Allocation,
                )
            })?;
            block_interrupt_lines.try_reserve_exact(1).map_err(|_| {
                HvfSnapshotV2RootRestoreError::preflight(
                    HvfSnapshotV2RootRestoreStage::Transport,
                    HvfSnapshotV2RootRestoreFailure::Allocation,
                )
            })?;
        }

        let platform = restore_hvf_snapshot_v2_root_process_platform(
            state,
            memory,
            process_shell,
            resources,
            partuuid,
        )
        .map_err(HvfSnapshotV2RootRestoreError::platform)?;
        let mut pci_data_devices = None;
        match transport {
            PreparedSnapshotV2RootTransport::Mmio(root) => {
                let interrupt_line = root.interrupt_line();
                let device = match install_snapshot_v2_mmio_root(&platform, root) {
                    Ok(device) => device,
                    Err(failure) => {
                        let stage = match &failure {
                            HvfSnapshotV2RootRestoreFailure::MmioRegion(_) => {
                                HvfSnapshotV2RootRestoreStage::MmioRegion
                            }
                            _ => HvfSnapshotV2RootRestoreStage::MmioHandler,
                        };
                        return Err(failed_snapshot_v2_root_after_platform(
                            platform,
                            stage,
                            failure,
                            &mut pci_data_devices,
                        ));
                    }
                };
                block_devices.push(device);
                block_interrupt_lines.push(interrupt_line);
            }
            PreparedSnapshotV2RootTransport::Pci(root) => {
                if let Err(failure) = prepare_snapshot_v2_pci_root_owner(
                    &platform,
                    root,
                    resources,
                    &layout,
                    &block_device_metrics,
                    retry_deadline,
                    &mut pci_data_devices,
                ) {
                    let stage = match &failure {
                        HvfSnapshotV2RootRestoreFailure::PciHost(_) => {
                            HvfSnapshotV2RootRestoreStage::PciHost
                        }
                        HvfSnapshotV2RootRestoreFailure::PciEndpoint(_)
                        | HvfSnapshotV2RootRestoreFailure::PciPublication(_) => {
                            HvfSnapshotV2RootRestoreStage::PciEndpoint
                        }
                        _ => HvfSnapshotV2RootRestoreStage::PciRoutes,
                    };
                    return Err(failed_snapshot_v2_root_after_platform(
                        platform,
                        stage,
                        failure,
                        &mut pci_data_devices,
                    ));
                }
            }
        }

        let block_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let vcpu_control = platform.control();
        let block_retry_wakeup_scheduler =
            match HvfArm64BootLimiterRetryWakeupScheduler::start_with_cancellation(
                BLOCK_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
                block_retry_wakeup.clone(),
                move || vcpu_control.request_wakeup(),
            ) {
                Ok(scheduler) => scheduler,
                Err(source) => {
                    return Err(failed_snapshot_v2_root_after_platform(
                        platform,
                        HvfSnapshotV2RootRestoreStage::RetryScheduler,
                        HvfSnapshotV2RootRestoreFailure::RetryScheduler(source.kind()),
                        &mut pci_data_devices,
                    ));
                }
            };
        block_retry_wakeup_scheduler.schedule_deadline(retry_deadline);

        let parts = platform.into_parts();
        let machine_config = parts.machine.machine();
        let cpu_template_application = parts.machine.cpu_template().cloned();
        let cache_source = crate::vcpu_config::HvfArm64VcpuCacheFdtSource::new(
            parts.compatibility.identification().id_aa64mmfr2_el1(),
            parts.compatibility.cache_manifest(),
        );
        let gic = parts.compatibility.gic_metadata();
        let serial_interrupt_line = parts
            .serial_device
            .as_ref()
            .map(|device| device.fdt_device.interrupt_line);
        let vmgenid_interrupt_line = parts.vmgenid_device.fdt_device.interrupt_line;
        let vmclock_interrupt_line = parts.vmclock_device.fdt_device.interrupt_line;
        let runtime_resources = Arm64BootRuntimeResources {
            machine_config,
            layout,
            boot_origin: None,
            retained_fdt: Some(retained_fdt),
            rtc_device: Some(parts.rtc_device),
            serial_device: parts.serial_device,
            vmgenid_device: parts.vmgenid_device,
            vmclock_device: parts.vmclock_device,
            pvtime_state: Arm64BootPvTimeState::restored(parts.pvtime_layout),
            block_devices,
            block_async_runtime: SharedBlockAsyncRuntime::new(),
            pci_block_devices: Vec::new(),
            pmem_devices: Vec::new(),
            pmem_mmio_devices: Vec::new(),
            network_devices: Vec::new(),
            pci_network_devices: Vec::new(),
            vsock_device: None,
            pci_vsock_device: None,
            balloon_device: None,
            pci_balloon_device: None,
            memory_hotplug_device: None,
            pci_memory_hotplug_device: None,
            entropy_device: None,
            pci_entropy_device: None,
            pci_validation: None,
        };
        let pmem_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let network_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let entropy_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let snapshot_lineage =
            restored_v2_snapshot_lineage(parts.memory_binding, &runtime_resources);

        Ok(Self {
            runner: parts.runner,
            backend: parts.backend,
            mmio_dispatcher: parts.mmio_dispatcher,
            runtime_resources,
            restored_snapshot_v2_mmio_registrations: None,
            restored_snapshot_v2_pci_pmem_ranges: None,
            snapshot_lineage,
            restored_snapshot_v2_machine: Some(parts.machine),
            cpu_template_application,
            pci_validation_endpoint: None,
            pci_data_devices,
            cache_source,
            cache_hierarchy: None,
            control_wakeup: HvfArm64BootRunLoopControlWakeupToken::default(),
            run_loop_wakeup: HvfArm64BootRunLoopWakeupToken::default(),
            block_retry_wakeup,
            block_retry_wakeup_scheduler,
            pmem_retry_wakeup,
            pmem_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            network_retry_wakeup,
            network_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_retry_wakeup,
            entropy_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_source: VirtioRngOsEntropySource::new(),
            block_device_metrics,
            pmem_device_metrics: SharedPmemDeviceMetricsRegistry::default(),
            balloon_device_metrics: SharedBalloonDeviceMetrics::default(),
            memory_hotplug_device_metrics: None,
            network_interface_metrics: SharedNetworkInterfaceMetricsRegistry::default(),
            vsock_device_metrics: SharedVsockDeviceMetrics::default(),
            entropy_device_metrics: SharedEntropyDeviceMetrics::default(),
            gic,
            block_interrupt_lines,
            pmem_interrupt_lines: Vec::new(),
            network_interrupt_lines: Vec::new(),
            vsock_interrupt_line: None,
            balloon_interrupt_line: None,
            entropy_interrupt_line: None,
            memory_hotplug_interrupt_line: None,
            serial_interrupt_line,
            serial_input: None,
            vmgenid_interrupt_line,
            vmclock_interrupt_line,
            boot_registers: None,
        })
    }

    /// Reconstructs one exact profile-2 MMIO vector without publishing a
    /// process session or controller.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_multi_block_mmio(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2DefaultProcessShell,
        bundle: PreparedSnapshotV2MultiBlockBundle,
        plan: HvfSnapshotV2MultiBlockPlatformPlan,
    ) -> Result<RestoredHvfSnapshotV2MultiBlockMmioOwners, HvfSnapshotV2MultiBlockMmioRestoreError>
    {
        let mut ranges = Vec::new();
        ranges
            .try_reserve_exact(memory.regions().len())
            .map_err(|_| {
                HvfSnapshotV2MultiBlockMmioRestoreError::preflight(
                    HvfSnapshotV2MultiBlockMmioRestoreStage::MemoryLayout,
                    HvfSnapshotV2MultiBlockMmioRestoreFailure::Allocation,
                )
            })?;
        ranges.extend(memory.regions().iter().map(|region| region.range()));
        let layout = GuestMemoryLayout::new(ranges).map_err(|_| {
            HvfSnapshotV2MultiBlockMmioRestoreError::preflight(
                HvfSnapshotV2MultiBlockMmioRestoreStage::MemoryLayout,
                HvfSnapshotV2MultiBlockMmioRestoreFailure::MemoryLayout,
            )
        })?;
        let source_fdt = state.machine().fdt();
        let retained_fdt = Arm64FdtGuestMemoryWrite {
            address: source_fdt.address(),
            size: usize::try_from(source_fdt.size()).map_err(|_| {
                HvfSnapshotV2MultiBlockMmioRestoreError::preflight(
                    HvfSnapshotV2MultiBlockMmioRestoreStage::MemoryLayout,
                    HvfSnapshotV2MultiBlockMmioRestoreFailure::Allocation,
                )
            })?,
        };
        let prepared = bundle.prepare_mmio_transport().map_err(|source| {
            HvfSnapshotV2MultiBlockMmioRestoreError::preflight(
                HvfSnapshotV2MultiBlockMmioRestoreStage::Transport,
                HvfSnapshotV2MultiBlockMmioRestoreFailure::Transport(source),
            )
        })?;
        let plan = plan.into_parts();
        if !validate_snapshot_v2_multi_block_mmio_resource_plan(&prepared, &plan) {
            return Err(
                HvfSnapshotV2MultiBlockMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockMmioRestoreFailure::ResourcePlan,
                    prepared,
                ),
            );
        }

        let HvfSnapshotV2MultiBlockPlatformPlanParts {
            root_key: _,
            command_line,
            metrics_ids,
            retries: _,
            earliest_retry_index: _,
            transport,
            serial_interrupt,
            vmgenid_interrupt,
            vmclock_interrupt,
        } = plan;
        let HvfSnapshotV2MultiBlockTransportPlan::Mmio(planned_records) = transport else {
            return Err(
                HvfSnapshotV2MultiBlockMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockMmioRestoreFailure::ResourcePlan,
                    prepared,
                ),
            );
        };
        let record_count = prepared.records().len();
        let earliest_retry_deadline = prepared
            .records()
            .iter()
            .filter_map(PreparedSnapshotV2MultiBlockMmioRecord::retry_deadline)
            .min();
        let block_device_metrics =
            match SharedBlockDeviceMetricsRegistry::from_owned_drive_ids_with_capacity(
                metrics_ids,
                record_count,
            ) {
                Ok(metrics) => metrics,
                Err(source) => {
                    return Err(
                        HvfSnapshotV2MultiBlockMmioRestoreError::with_prepared_bundle_abort(
                            HvfSnapshotV2MultiBlockMmioRestoreStage::Metrics,
                            HvfSnapshotV2MultiBlockMmioRestoreFailure::Metrics(source),
                            prepared,
                        ),
                    );
                }
            };
        let mut block_devices = Vec::new();
        if block_devices.try_reserve_exact(record_count).is_err() {
            return Err(
                HvfSnapshotV2MultiBlockMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockMmioRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        let mut block_interrupt_lines = Vec::new();
        if block_interrupt_lines
            .try_reserve_exact(record_count)
            .is_err()
        {
            return Err(
                HvfSnapshotV2MultiBlockMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockMmioRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        let mut registration_leases = Vec::new();
        if registration_leases.try_reserve_exact(record_count).is_err() {
            return Err(
                HvfSnapshotV2MultiBlockMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockMmioRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        let mut cleanup = Vec::new();
        if cleanup
            .try_reserve_exact(record_count.saturating_add(5))
            .is_err()
        {
            return Err(
                HvfSnapshotV2MultiBlockMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockMmioRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }

        let shell_plan = HvfSnapshotV2MultiBlockMmioShellPlan {
            command_line: &command_line,
            records: &planned_records,
            serial_interrupt,
            vmgenid_interrupt,
            vmclock_interrupt,
        };
        let platform = match restore_hvf_snapshot_v2_multi_block_mmio_process_platform(
            state,
            memory,
            process_shell,
            shell_plan,
        ) {
            Ok(platform) => platform,
            Err(source) => {
                return Err(HvfSnapshotV2MultiBlockMmioRestoreError::platform(
                    source, prepared,
                ));
            }
        };
        let (drive_configs, records, async_runtime, async_generations) = prepared.into_parts();
        debug_assert_eq!(
            async_generations.len(),
            records
                .iter()
                .filter(|record| record.async_generation().is_some())
                .count()
        );
        drop(async_generations);

        let registration_owner = MmioRegistrationOwner::new();
        let install_result = (|| {
            for (index, (record, planned)) in records.into_iter().zip(planned_records).enumerate() {
                let (
                    _key,
                    drive_id,
                    _is_root_device,
                    _retry,
                    _retry_deadline,
                    region,
                    interrupt_line,
                    _async_generation,
                    handler,
                ) = record.into_parts();
                let request = [MmioRegionRequest::new(
                    region.range().start(),
                    region.range().size(),
                )];
                let lease = {
                    let mut dispatcher = platform.mmio_dispatcher().lock().map_err(|_| {
                        (
                            HvfSnapshotV2MultiBlockMmioRestoreStage::Registration { index },
                            HvfSnapshotV2MultiBlockMmioRestoreFailure::DispatcherUnavailable,
                        )
                    })?;
                    dispatcher
                        .register_owned_handler(&registration_owner, region.id(), &request, handler)
                        .map_err(|source| {
                            (
                                HvfSnapshotV2MultiBlockMmioRestoreStage::Registration { index },
                                HvfSnapshotV2MultiBlockMmioRestoreFailure::Registration(source),
                            )
                        })?
                };
                registration_leases.push(lease);
                if registration_leases.last().is_none_or(|lease| {
                    lease.region_id() != region.id() || lease.regions() != [region]
                }) {
                    return Err((
                        HvfSnapshotV2MultiBlockMmioRestoreStage::Registration { index },
                        HvfSnapshotV2MultiBlockMmioRestoreFailure::ResourcePlan,
                    ));
                }
                block_devices.push(Arm64BootBlockDevice {
                    registration: BlockMmioDeviceRegistration::from_restored(
                        index, drive_id, region,
                    ),
                    fdt_device: planned.fdt_device(),
                });
                block_interrupt_lines.push(interrupt_line);
            }
            Ok(())
        })();
        let mut block_retry_wakeup_scheduler = None;
        if let Err((stage, failure)) = install_result {
            return Err(failed_snapshot_v2_multi_block_mmio_after_platform(
                platform,
                stage,
                failure,
                HvfSnapshotV2MultiBlockMmioCleanup {
                    scheduler: &mut block_retry_wakeup_scheduler,
                    async_runtime: async_runtime.as_ref(),
                    registration_owner: &registration_owner,
                    registration_leases: &registration_leases,
                    failures: cleanup,
                },
            ));
        }

        let block_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let vcpu_control = platform.control();
        block_retry_wakeup_scheduler =
            match HvfArm64BootLimiterRetryWakeupScheduler::start_with_cancellation(
                BLOCK_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
                block_retry_wakeup.clone(),
                move || vcpu_control.request_wakeup(),
            ) {
                Ok(scheduler) => Some(scheduler),
                Err(source) => {
                    return Err(failed_snapshot_v2_multi_block_mmio_after_platform(
                        platform,
                        HvfSnapshotV2MultiBlockMmioRestoreStage::RetryScheduler,
                        HvfSnapshotV2MultiBlockMmioRestoreFailure::RetryScheduler(source.kind()),
                        HvfSnapshotV2MultiBlockMmioCleanup {
                            scheduler: &mut block_retry_wakeup_scheduler,
                            async_runtime: async_runtime.as_ref(),
                            registration_owner: &registration_owner,
                            registration_leases: &registration_leases,
                            failures: cleanup,
                        },
                    ));
                }
            };
        let Some(block_retry_wakeup_scheduler) = block_retry_wakeup_scheduler.take() else {
            std::process::abort();
        };
        block_retry_wakeup_scheduler.schedule_deadline(earliest_retry_deadline);

        let parts = platform.into_parts();
        let machine_config = parts.machine.machine();
        let cpu_template_application = parts.machine.cpu_template().cloned();
        let cache_source = crate::vcpu_config::HvfArm64VcpuCacheFdtSource::new(
            parts.compatibility.identification().id_aa64mmfr2_el1(),
            parts.compatibility.cache_manifest(),
        );
        let gic = parts.compatibility.gic_metadata();
        let serial_interrupt_line = parts
            .serial_device
            .as_ref()
            .map(|device| device.fdt_device.interrupt_line);
        let vmgenid_interrupt_line = parts.vmgenid_device.fdt_device.interrupt_line;
        let vmclock_interrupt_line = parts.vmclock_device.fdt_device.interrupt_line;
        let runtime_resources = Arm64BootRuntimeResources {
            machine_config,
            layout,
            boot_origin: None,
            retained_fdt: Some(retained_fdt),
            rtc_device: Some(parts.rtc_device),
            serial_device: parts.serial_device,
            vmgenid_device: parts.vmgenid_device,
            vmclock_device: parts.vmclock_device,
            pvtime_state: Arm64BootPvTimeState::restored(parts.pvtime_layout),
            block_devices,
            block_async_runtime: async_runtime.unwrap_or_default(),
            pci_block_devices: Vec::new(),
            pmem_devices: Vec::new(),
            pmem_mmio_devices: Vec::new(),
            network_devices: Vec::new(),
            pci_network_devices: Vec::new(),
            vsock_device: None,
            pci_vsock_device: None,
            balloon_device: None,
            pci_balloon_device: None,
            memory_hotplug_device: None,
            pci_memory_hotplug_device: None,
            entropy_device: None,
            pci_entropy_device: None,
            pci_validation: None,
        };
        let pmem_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let network_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let entropy_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let snapshot_lineage =
            restored_v2_snapshot_lineage(parts.memory_binding, &runtime_resources);
        let session = Self {
            runner: parts.runner,
            backend: parts.backend,
            mmio_dispatcher: parts.mmio_dispatcher,
            runtime_resources,
            restored_snapshot_v2_mmio_registrations: Some(
                HvfSnapshotV2MultiBlockMmioRegistrations {
                    owner: registration_owner,
                    leases: registration_leases,
                    pmem_ranges: Vec::new(),
                },
            ),
            restored_snapshot_v2_pci_pmem_ranges: None,
            snapshot_lineage,
            restored_snapshot_v2_machine: Some(parts.machine),
            cpu_template_application,
            pci_validation_endpoint: None,
            pci_data_devices: None,
            cache_source,
            cache_hierarchy: None,
            control_wakeup: HvfArm64BootRunLoopControlWakeupToken::default(),
            run_loop_wakeup: HvfArm64BootRunLoopWakeupToken::default(),
            block_retry_wakeup,
            block_retry_wakeup_scheduler,
            pmem_retry_wakeup,
            pmem_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            network_retry_wakeup,
            network_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_retry_wakeup,
            entropy_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_source: VirtioRngOsEntropySource::new(),
            block_device_metrics,
            pmem_device_metrics: SharedPmemDeviceMetricsRegistry::default(),
            balloon_device_metrics: SharedBalloonDeviceMetrics::default(),
            memory_hotplug_device_metrics: None,
            network_interface_metrics: SharedNetworkInterfaceMetricsRegistry::default(),
            vsock_device_metrics: SharedVsockDeviceMetrics::default(),
            entropy_device_metrics: SharedEntropyDeviceMetrics::default(),
            gic,
            block_interrupt_lines,
            pmem_interrupt_lines: Vec::new(),
            network_interrupt_lines: Vec::new(),
            vsock_interrupt_line: None,
            balloon_interrupt_line: None,
            entropy_interrupt_line: None,
            memory_hotplug_interrupt_line: None,
            serial_interrupt_line,
            serial_input: None,
            vmgenid_interrupt_line,
            vmclock_interrupt_line,
            boot_registers: None,
        };
        Ok(RestoredHvfSnapshotV2MultiBlockMmioOwners {
            session,
            drive_configs,
        })
    }

    /// Reconstructs one exact-2.6 block-and-pmem MMIO vector without
    /// publishing a process session, controller, or public load path.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_storage_mmio(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2DefaultProcessShell,
        bundle: PreparedSnapshotV2StorageBundle,
        plan: HvfSnapshotV2StorageMmioPlatformPlan,
    ) -> Result<RestoredHvfSnapshotV2StorageMmioOwners, HvfSnapshotV2StorageMmioRestoreError> {
        Self::restore_snapshot_v2_storage_mmio_inner(
            state,
            memory,
            HvfSnapshotV2StorageProcessShell::Default(process_shell),
            None,
            bundle,
            plan,
            HvfSnapshotV2StorageMmioPublicationInput::empty(),
        )
    }

    /// Reconstructs one exact-2.7 serial plus profile-3 MMIO owner vector.
