    /// Deterministically fails after one pmem mapping is installed but before
    /// its handler becomes reachable. This exists only for signed rollback
    /// certification; normal reconstruction never selects the fault.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_storage_mmio_with_pmem_publication_fault(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2DefaultProcessShell,
        bundle: PreparedSnapshotV2StorageBundle,
        plan: HvfSnapshotV2StorageMmioPlatformPlan,
        pmem_index: usize,
    ) -> Result<RestoredHvfSnapshotV2StorageMmioOwners, HvfSnapshotV2StorageMmioRestoreError> {
        Self::restore_snapshot_v2_storage_mmio_inner(
            state,
            memory,
            HvfSnapshotV2StorageProcessShell::Default(process_shell),
            None,
            bundle,
            plan,
            HvfSnapshotV2StorageMmioPublicationInput::pmem_fault(pmem_index),
        )
    }

    fn restore_snapshot_v2_storage_mmio_inner(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2StorageProcessShell,
        serial_input: Option<SerialStdioInput>,
        bundle: PreparedSnapshotV2StorageBundle,
        plan: HvfSnapshotV2StorageMmioPlatformPlan,
        publication: HvfSnapshotV2StorageMmioPublicationInput,
    ) -> Result<RestoredHvfSnapshotV2StorageMmioOwners, HvfSnapshotV2StorageMmioRestoreError> {
        let HvfSnapshotV2StorageMmioPublicationInput {
            balloon,
            pmem_fault_index: publication_fault_pmem_index,
            balloon_fault: balloon_publication_fault,
            additional_registration_capacity,
        } = publication;
        let mut ranges = Vec::new();
        ranges
            .try_reserve_exact(memory.regions().len())
            .map_err(|_| {
                HvfSnapshotV2StorageMmioRestoreError::preflight(
                    HvfSnapshotV2StorageMmioRestoreStage::MemoryLayout,
                    HvfSnapshotV2StorageMmioRestoreFailure::Allocation,
                )
            })?;
        ranges.extend(memory.regions().iter().map(|region| region.range()));
        let layout = GuestMemoryLayout::new(ranges).map_err(|_| {
            HvfSnapshotV2StorageMmioRestoreError::preflight(
                HvfSnapshotV2StorageMmioRestoreStage::MemoryLayout,
                HvfSnapshotV2StorageMmioRestoreFailure::MemoryLayout,
            )
        })?;
        let source_fdt = state.machine().fdt();
        let retained_fdt = Arm64FdtGuestMemoryWrite {
            address: source_fdt.address(),
            size: usize::try_from(source_fdt.size()).map_err(|_| {
                HvfSnapshotV2StorageMmioRestoreError::preflight(
                    HvfSnapshotV2StorageMmioRestoreStage::MemoryLayout,
                    HvfSnapshotV2StorageMmioRestoreFailure::Allocation,
                )
            })?,
        };
        let prepared = bundle.prepare_mmio_transport().map_err(|source| {
            HvfSnapshotV2StorageMmioRestoreError::preflight(
                HvfSnapshotV2StorageMmioRestoreStage::Transport,
                HvfSnapshotV2StorageMmioRestoreFailure::Transport(source),
            )
        })?;
        let plan = plan.into_parts();
        if !validate_snapshot_v2_storage_mmio_resource_plan(&prepared, &plan) {
            return Err(
                HvfSnapshotV2StorageMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2StorageMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2StorageMmioRestoreFailure::ResourcePlan,
                    prepared,
                ),
            );
        }

        let HvfSnapshotV2StorageMmioPlatformPlanParts {
            root_key: _,
            command_line,
            block_metrics_ids,
            pmem_metrics_ids,
            block_retries,
            pmem_retries,
            block_records: planned_block_records,
            pmem_records: planned_pmem_records,
            serial_interrupt,
            vmgenid_interrupt,
            vmclock_interrupt,
        } = plan;
        let block_count = planned_block_records.len();
        let pmem_count = planned_pmem_records.len();
        let balloon_count = usize::from(balloon.is_some());
        let record_count = balloon_count
            .saturating_add(block_count)
            .saturating_add(pmem_count)
            .saturating_add(additional_registration_capacity);
        if publication_fault_pmem_index.is_some_and(|index| index >= pmem_count)
            || (balloon_publication_fault.is_some() && balloon.is_none())
        {
            return Err(
                HvfSnapshotV2StorageMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2StorageMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2StorageMmioRestoreFailure::ResourcePlan,
                    prepared,
                ),
            );
        }
        let earliest_block_retry_deadline = block_retries
            .iter()
            .filter_map(|retry| retry.retry_deadline())
            .min();
        let earliest_pmem_retry_deadline = pmem_retries
            .iter()
            .filter_map(|retry| retry.retry_deadline())
            .min();
        let block_device_metrics =
            match SharedBlockDeviceMetricsRegistry::from_owned_drive_ids_with_capacity(
                block_metrics_ids,
                block_count,
            ) {
                Ok(metrics) => metrics,
                Err(source) => {
                    return Err(
                        HvfSnapshotV2StorageMmioRestoreError::with_prepared_bundle_abort(
                            HvfSnapshotV2StorageMmioRestoreStage::BlockMetrics,
                            HvfSnapshotV2StorageMmioRestoreFailure::BlockMetrics(source),
                            prepared,
                        ),
                    );
                }
            };
        let pmem_device_metrics =
            match SharedPmemDeviceMetricsRegistry::from_owned_device_ids_with_capacity(
                pmem_metrics_ids,
                pmem_count,
            ) {
                Ok(metrics) => metrics,
                Err(source) => {
                    return Err(
                        HvfSnapshotV2StorageMmioRestoreError::with_prepared_bundle_abort(
                            HvfSnapshotV2StorageMmioRestoreStage::PmemMetrics,
                            HvfSnapshotV2StorageMmioRestoreFailure::PmemMetrics(source),
                            prepared,
                        ),
                    );
                }
            };

        let mut block_devices = Vec::new();
        let mut pmem_devices = Vec::new();
        let mut pmem_mmio_devices = Vec::new();
        let mut pmem_ranges = Vec::new();
        let mut block_interrupt_lines = Vec::new();
        let mut pmem_interrupt_lines = Vec::new();
        let mut registration_leases = Vec::new();
        let mut cleanup = Vec::new();
        let storage_capacity_ok = block_devices.try_reserve_exact(block_count).is_ok()
            && pmem_devices.try_reserve_exact(pmem_count).is_ok()
            && pmem_mmio_devices.try_reserve_exact(pmem_count).is_ok()
            && pmem_ranges.try_reserve_exact(pmem_count).is_ok()
            && block_interrupt_lines.try_reserve_exact(block_count).is_ok()
            && pmem_interrupt_lines.try_reserve_exact(pmem_count).is_ok()
            && registration_leases.try_reserve_exact(record_count).is_ok()
            && cleanup
                .try_reserve_exact(record_count.saturating_mul(2).saturating_add(8))
                .is_ok();
        if !storage_capacity_ok {
            return Err(
                HvfSnapshotV2StorageMmioRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2StorageMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2StorageMmioRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }

        let prepared_owner = PreparedHvfSnapshotV2StorageMmioOwners {
            layout,
            retained_fdt,
            bundle: prepared,
            command_line,
            planned_block_records,
            planned_pmem_records,
            serial_interrupt,
            vmgenid_interrupt,
            vmclock_interrupt,
            block_count,
            pmem_count,
            balloon_count,
            earliest_block_retry_deadline,
            earliest_pmem_retry_deadline,
            block_device_metrics,
            pmem_device_metrics,
            block_devices,
            pmem_devices,
            pmem_mmio_devices,
            pmem_ranges,
            block_interrupt_lines,
            pmem_interrupt_lines,
            registration_owner: MmioRegistrationOwner::new(),
            registration_leases,
            cleanup,
            balloon,
            publication_fault_pmem_index,
            balloon_publication_fault,
        };
        Self::publish_snapshot_v2_storage_mmio_owner(
            state,
            memory,
            process_shell,
            serial_input,
            prepared_owner,
        )
    }

    #[allow(clippy::too_many_lines)]
    fn publish_snapshot_v2_storage_mmio_owner(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2StorageProcessShell,
        serial_input: Option<SerialStdioInput>,
        prepared_owner: PreparedHvfSnapshotV2StorageMmioOwners,
    ) -> Result<RestoredHvfSnapshotV2StorageMmioOwners, HvfSnapshotV2StorageMmioRestoreError> {
        let shell_plan = HvfSnapshotV2StorageMmioShellPlan {
            command_line: &prepared_owner.command_line,
            block_records: &prepared_owner.planned_block_records,
            pmem_records: &prepared_owner.planned_pmem_records,
            serial_interrupt: prepared_owner.serial_interrupt,
            vmgenid_interrupt: prepared_owner.vmgenid_interrupt,
            vmclock_interrupt: prepared_owner.vmclock_interrupt,
        };
        let restored = match process_shell {
            HvfSnapshotV2StorageProcessShell::Default(shell) => {
                restore_hvf_snapshot_v2_storage_mmio_process_platform(
                    state, memory, shell, shell_plan,
                )
            }
            HvfSnapshotV2StorageProcessShell::Restored(shell) => {
                restore_hvf_snapshot_v2_serial_storage_mmio_process_platform(
                    state, memory, shell, shell_plan,
                )
            }
            HvfSnapshotV2StorageProcessShell::RestoredEntropyMmio {
                shell,
                interrupt_line,
            } => restore_hvf_snapshot_v2_serial_storage_entropy_mmio_process_platform(
                state,
                memory,
                shell,
                shell_plan,
                interrupt_line,
            ),
            HvfSnapshotV2StorageProcessShell::RestoredBalloonMmio { shell, interrupts } => {
                restore_hvf_snapshot_v2_serial_balloon_mmio_process_platform(
                    state,
                    memory,
                    shell,
                    HvfSnapshotV2BalloonMmioShellPlan {
                        balloon_interrupt: interrupts.balloon,
                        command_line: Some(&prepared_owner.command_line),
                        block_records: &prepared_owner.planned_block_records,
                        pmem_records: &prepared_owner.planned_pmem_records,
                        entropy_interrupt: interrupts.entropy,
                        serial_interrupt: interrupts.serial,
                        vmgenid_interrupt: interrupts.vmgenid,
                        vmclock_interrupt: interrupts.vmclock,
                    },
                )
            }
            HvfSnapshotV2StorageProcessShell::RestoredMemoryHotplugMmio {
                shell,
                interrupts,
                mapping,
            } => restore_hvf_snapshot_v2_serial_memory_hotplug_mmio_process_platform(
                state,
                memory,
                shell,
                HvfSnapshotV2MemoryHotplugMmioShellPlan {
                    balloon_interrupt: interrupts.balloon,
                    command_line: Some(&prepared_owner.command_line),
                    block_records: &prepared_owner.planned_block_records,
                    pmem_records: &prepared_owner.planned_pmem_records,
                    entropy_interrupt: interrupts.entropy,
                    memory_hotplug_interrupt: interrupts.memory_hotplug,
                    serial_interrupt: interrupts.serial,
                    vmgenid_interrupt: interrupts.vmgenid,
                    vmclock_interrupt: interrupts.vmclock,
                },
                &mapping,
            ),
            HvfSnapshotV2StorageProcessShell::RestoredNetworkMmio {
                shell,
                interrupts,
                mapping,
            } => restore_hvf_snapshot_v2_serial_network_mmio_process_platform(
                state,
                memory,
                shell,
                HvfSnapshotV2NetworkMmioShellPlan {
                    balloon_interrupt: interrupts.balloon,
                    command_line: Some(&prepared_owner.command_line),
                    block_records: &prepared_owner.planned_block_records,
                    network_interrupts: &interrupts.network,
                    pmem_records: &prepared_owner.planned_pmem_records,
                    following_interrupt: interrupts.following,
                    entropy_interrupt: interrupts.entropy,
                    memory_hotplug_interrupt: interrupts.memory_hotplug,
                    serial_interrupt: interrupts.serial,
                    vmgenid_interrupt: interrupts.vmgenid,
                    vmclock_interrupt: interrupts.vmclock,
                },
                mapping.as_ref(),
            ),
            HvfSnapshotV2StorageProcessShell::RestoredMemoryHotplugPci { .. }
            | HvfSnapshotV2StorageProcessShell::RestoredNetworkPci { .. } => {
                return Err(
                    HvfSnapshotV2StorageMmioRestoreError::with_prepared_bundle_abort(
                        HvfSnapshotV2StorageMmioRestoreStage::ResourcePlan,
                        HvfSnapshotV2StorageMmioRestoreFailure::ResourcePlan,
                        prepared_owner.bundle,
                    ),
                );
            }
        };
        let mut platform = match restored {
            Ok(platform) => platform,
            Err(source) => {
                return Err(HvfSnapshotV2StorageMmioRestoreError::platform(
                    source,
                    prepared_owner.bundle,
                ));
            }
        };
        let PreparedHvfSnapshotV2StorageMmioOwners {
            layout,
            retained_fdt,
            bundle: prepared,
            command_line: _,
            planned_block_records,
            planned_pmem_records,
            serial_interrupt: _,
            vmgenid_interrupt: _,
            vmclock_interrupt: _,
            block_count,
            pmem_count,
            balloon_count,
            earliest_block_retry_deadline,
            earliest_pmem_retry_deadline,
            block_device_metrics,
            pmem_device_metrics,
            mut block_devices,
            mut pmem_devices,
            mut pmem_mmio_devices,
            mut pmem_ranges,
            mut block_interrupt_lines,
            mut pmem_interrupt_lines,
            registration_owner,
            mut registration_leases,
            cleanup,
            balloon,
            publication_fault_pmem_index,
            balloon_publication_fault,
        } = prepared_owner;
        let (_root_key, block_bundle, pmem_configs, pmem_records) = prepared.into_parts();
        let mut drive_configs = DriveConfigs::new();
        let mut block_records = Vec::new();
        let mut async_runtime = None;
        if let Some(block_bundle) = block_bundle {
            let (configs, records, runtime, async_generations) = block_bundle.into_parts();
            debug_assert_eq!(
                async_generations.len(),
                records
                    .iter()
                    .filter(|record| record.async_generation().is_some())
                    .count()
            );
            drop(async_generations);
            drive_configs = configs;
            block_records = records;
            async_runtime = runtime;
        }

        let balloon_device_metrics = SharedBalloonDeviceMetrics::default();
        let mut balloon_device = None;
        let mut balloon_interrupt_line = None;
        let install_result = (|| {
            if let Some(mut balloon) = balloon {
                if balloon_publication_fault
                    == Some(HvfSnapshotV2BalloonMmioRestoreFault::Registration)
                {
                    return Err((
                        HvfSnapshotV2StorageMmioRestoreStage::Registration { index: 0 },
                        HvfSnapshotV2StorageMmioRestoreFailure::InjectedPublication,
                    ));
                }
                balloon.attach_metrics(balloon_device_metrics.clone());
                let (_config, _queue_ranges, region, interrupt_line, handler) =
                    balloon.into_parts();
                let request = [MmioRegionRequest::new(
                    region.range().start(),
                    region.range().size(),
                )];
                let lease = {
                    let mut dispatcher = platform.mmio_dispatcher().lock().map_err(|_| {
                        (
                            HvfSnapshotV2StorageMmioRestoreStage::Registration { index: 0 },
                            HvfSnapshotV2StorageMmioRestoreFailure::DispatcherUnavailable,
                        )
                    })?;
                    dispatcher
                        .register_owned_handler(&registration_owner, region.id(), &request, handler)
                        .map_err(|source| {
                            (
                                HvfSnapshotV2StorageMmioRestoreStage::Registration { index: 0 },
                                HvfSnapshotV2StorageMmioRestoreFailure::Registration(source),
                            )
                        })?
                };
                registration_leases.push(lease);
                if registration_leases.last().is_none_or(|lease| {
                    lease.region_id() != region.id() || lease.regions() != [region]
                }) {
                    return Err((
                        HvfSnapshotV2StorageMmioRestoreStage::Registration { index: 0 },
                        HvfSnapshotV2StorageMmioRestoreFailure::ResourcePlan,
                    ));
                }
                if balloon_publication_fault
                    == Some(HvfSnapshotV2BalloonMmioRestoreFault::BalloonInsertion)
                {
                    return Err((
                        HvfSnapshotV2StorageMmioRestoreStage::Registration { index: 0 },
                        HvfSnapshotV2StorageMmioRestoreFailure::InjectedPublication,
                    ));
                }
                balloon_device = Some(Arm64BootBalloonDevice {
                    registration: BalloonMmioDeviceRegistration::from_restored(region),
                    fdt_device: Arm64FdtVirtioMmioDevice {
                        region: Arm64FdtRegion {
                            base: region.range().start().raw_value(),
                            size: region.range().size(),
                        },
                        interrupt_line,
                    },
                });
                balloon_interrupt_line = Some(interrupt_line);
                if balloon_publication_fault
                    == Some(HvfSnapshotV2BalloonMmioRestoreFault::StoragePublication)
                {
                    return Err((
                        HvfSnapshotV2StorageMmioRestoreStage::Registration { index: 1 },
                        HvfSnapshotV2StorageMmioRestoreFailure::InjectedPublication,
                    ));
                }
            }

            for (index, (record, planned)) in block_records
                .into_iter()
                .zip(planned_block_records)
                .enumerate()
            {
                let registration_index = balloon_count.saturating_add(index);
                let (
                    _key,
                    drive_id,
                    _is_root_device,
                    _retry,
                    _retry_deadline,
                    region,
                    interrupt_line,
                    _async_generation,
                    handler,
                ) = record.into_parts();
                let request = [MmioRegionRequest::new(
                    region.range().start(),
                    region.range().size(),
                )];
                let lease = {
                    let mut dispatcher = platform.mmio_dispatcher().lock().map_err(|_| {
                        (
                            HvfSnapshotV2StorageMmioRestoreStage::Registration {
                                index: registration_index,
                            },
                            HvfSnapshotV2StorageMmioRestoreFailure::DispatcherUnavailable,
                        )
                    })?;
                    dispatcher
                        .register_owned_handler(&registration_owner, region.id(), &request, handler)
                        .map_err(|source| {
                            (
                                HvfSnapshotV2StorageMmioRestoreStage::Registration {
                                    index: registration_index,
                                },
                                HvfSnapshotV2StorageMmioRestoreFailure::Registration(source),
                            )
                        })?
                };
                registration_leases.push(lease);
                if registration_leases.last().is_none_or(|lease| {
                    lease.region_id() != region.id() || lease.regions() != [region]
                }) {
                    return Err((
                        HvfSnapshotV2StorageMmioRestoreStage::Registration {
                            index: registration_index,
                        },
                        HvfSnapshotV2StorageMmioRestoreFailure::ResourcePlan,
                    ));
                }
                block_devices.push(Arm64BootBlockDevice {
                    registration: BlockMmioDeviceRegistration::from_restored(
                        index, drive_id, region,
                    ),
                    fdt_device: planned.fdt_device(),
                });
                block_interrupt_lines.push(interrupt_line);
            }

            for (pmem_index, (mut record, planned)) in pmem_records
                .into_iter()
                .zip(planned_pmem_records)
                .enumerate()
            {
                let registration_index = balloon_count
                    .saturating_add(block_count)
                    .saturating_add(pmem_index);
                let device_metrics = pmem_device_metrics.per_device(record.pmem_id()).ok_or((
                    HvfSnapshotV2StorageMmioRestoreStage::ResourcePlan,
                    HvfSnapshotV2StorageMmioRestoreFailure::ResourcePlan,
                ))?;
                record.attach_metrics(device_metrics, pmem_device_metrics.aggregate());
                let (
                    _key,
                    _is_root_device,
                    _retry,
                    _retry_deadline,
                    region,
                    interrupt_line,
                    prepared_device,
                    handler,
                ) = record.into_parts();
                let mut pmem_id = String::new();
                pmem_id
                    .try_reserve_exact(prepared_device.id().len())
                    .map_err(|_| {
                        (
                            HvfSnapshotV2StorageMmioRestoreStage::ResourcePlan,
                            HvfSnapshotV2StorageMmioRestoreFailure::Allocation,
                        )
                    })?;
                pmem_id.push_str(prepared_device.id());
                let guest_range = prepared_device.guest_range();
                let file_len = prepared_device.mapping().file_len();
                let config_space = prepared_device.config_space();
                platform
                    .backend_mut()
                    .map_runtime_pmem_device(&prepared_device)
                    .map_err(|source| {
                        (
                            HvfSnapshotV2StorageMmioRestoreStage::Mapping { index: pmem_index },
                            HvfSnapshotV2StorageMmioRestoreFailure::Mapping(source),
                        )
                    })?;
                pmem_ranges.push(guest_range);
                pmem_devices.push(prepared_device);
                if publication_fault_pmem_index == Some(pmem_index) {
                    return Err((
                        HvfSnapshotV2StorageMmioRestoreStage::Registration {
                            index: registration_index,
                        },
                        HvfSnapshotV2StorageMmioRestoreFailure::InjectedPublication,
                    ));
                }

                let request = [MmioRegionRequest::new(
                    region.range().start(),
                    region.range().size(),
                )];
                let lease = {
                    let mut dispatcher = platform.mmio_dispatcher().lock().map_err(|_| {
                        (
                            HvfSnapshotV2StorageMmioRestoreStage::Registration {
                                index: registration_index,
                            },
                            HvfSnapshotV2StorageMmioRestoreFailure::DispatcherUnavailable,
                        )
                    })?;
                    dispatcher
                        .register_owned_handler(&registration_owner, region.id(), &request, handler)
                        .map_err(|source| {
                            (
                                HvfSnapshotV2StorageMmioRestoreStage::Registration {
                                    index: registration_index,
                                },
                                HvfSnapshotV2StorageMmioRestoreFailure::Registration(source),
                            )
                        })?
                };
                registration_leases.push(lease);
                if registration_leases.last().is_none_or(|lease| {
                    lease.region_id() != region.id() || lease.regions() != [region]
                }) {
                    return Err((
                        HvfSnapshotV2StorageMmioRestoreStage::Registration {
                            index: registration_index,
                        },
                        HvfSnapshotV2StorageMmioRestoreFailure::ResourcePlan,
                    ));
                }
                pmem_mmio_devices.push(Arm64BootPmemDevice {
                    registration: PmemMmioDeviceRegistration::from_restored(
                        pmem_index,
                        pmem_id,
                        region,
                        guest_range,
                        file_len,
                        config_space,
                    ),
                    fdt_device: planned.fdt_device(),
                });
                pmem_interrupt_lines.push(interrupt_line);
            }
            Ok(())
        })();
        let mut block_retry_wakeup_scheduler = None;
        let mut pmem_retry_wakeup_scheduler = None;
        if let Err((stage, failure)) = install_result {
            return Err(failed_snapshot_v2_storage_mmio_after_platform(
                platform,
                stage,
                failure,
                HvfSnapshotV2StorageMmioCleanup {
                    block_scheduler: &mut block_retry_wakeup_scheduler,
                    pmem_scheduler: &mut pmem_retry_wakeup_scheduler,
                    async_runtime: async_runtime.as_ref(),
                    registration_owner: &registration_owner,
                    registration_leases: &registration_leases,
                    pmem_devices: &mut pmem_devices,
                    failures: cleanup,
                },
            ));
        }

        let block_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        if block_count == 0 {
            block_retry_wakeup_scheduler =
                Some(HvfArm64BootLimiterRetryWakeupScheduler::inactive());
        } else {
            let vcpu_control = platform.control();
            block_retry_wakeup_scheduler =
                match HvfArm64BootLimiterRetryWakeupScheduler::start_with_cancellation(
                    BLOCK_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
                    block_retry_wakeup.clone(),
                    move || vcpu_control.request_wakeup(),
                ) {
                    Ok(scheduler) => Some(scheduler),
                    Err(source) => {
                        return Err(failed_snapshot_v2_storage_mmio_after_platform(
                            platform,
                            HvfSnapshotV2StorageMmioRestoreStage::BlockRetryScheduler,
                            HvfSnapshotV2StorageMmioRestoreFailure::RetryScheduler(source.kind()),
                            HvfSnapshotV2StorageMmioCleanup {
                                block_scheduler: &mut block_retry_wakeup_scheduler,
                                pmem_scheduler: &mut pmem_retry_wakeup_scheduler,
                                async_runtime: async_runtime.as_ref(),
                                registration_owner: &registration_owner,
                                registration_leases: &registration_leases,
                                pmem_devices: &mut pmem_devices,
                                failures: cleanup,
                            },
                        ));
                    }
                };
        }
        let pmem_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        if pmem_count == 0 {
            pmem_retry_wakeup_scheduler = Some(HvfArm64BootLimiterRetryWakeupScheduler::inactive());
        } else {
            let vcpu_control = platform.control();
            pmem_retry_wakeup_scheduler =
                match HvfArm64BootLimiterRetryWakeupScheduler::start_with_cancellation(
                    PMEM_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
                    pmem_retry_wakeup.clone(),
                    move || vcpu_control.request_wakeup(),
                ) {
                    Ok(scheduler) => Some(scheduler),
                    Err(source) => {
                        return Err(failed_snapshot_v2_storage_mmio_after_platform(
                            platform,
                            HvfSnapshotV2StorageMmioRestoreStage::PmemRetryScheduler,
                            HvfSnapshotV2StorageMmioRestoreFailure::RetryScheduler(source.kind()),
                            HvfSnapshotV2StorageMmioCleanup {
                                block_scheduler: &mut block_retry_wakeup_scheduler,
                                pmem_scheduler: &mut pmem_retry_wakeup_scheduler,
                                async_runtime: async_runtime.as_ref(),
                                registration_owner: &registration_owner,
                                registration_leases: &registration_leases,
                                pmem_devices: &mut pmem_devices,
                                failures: cleanup,
                            },
                        ));
                    }
                };
        }
        let Some(block_retry_wakeup_scheduler) = block_retry_wakeup_scheduler.take() else {
            std::process::abort();
        };
        let Some(pmem_retry_wakeup_scheduler) = pmem_retry_wakeup_scheduler.take() else {
            std::process::abort();
        };
        block_retry_wakeup_scheduler.schedule_deadline(earliest_block_retry_deadline);
        pmem_retry_wakeup_scheduler.schedule_deadline(earliest_pmem_retry_deadline);

        let parts = platform.into_parts();
        let machine_config = parts.machine.machine();
        let cpu_template_application = parts.machine.cpu_template().cloned();
        let cache_source = crate::vcpu_config::HvfArm64VcpuCacheFdtSource::new(
            parts.compatibility.identification().id_aa64mmfr2_el1(),
            parts.compatibility.cache_manifest(),
        );
        let gic = parts.compatibility.gic_metadata();
        let serial_interrupt_line = parts
            .serial_device
            .as_ref()
            .map(|device| device.fdt_device.interrupt_line);
        let vmgenid_interrupt_line = parts.vmgenid_device.fdt_device.interrupt_line;
        let vmclock_interrupt_line = parts.vmclock_device.fdt_device.interrupt_line;
        let runtime_resources = Arm64BootRuntimeResources {
            machine_config,
            layout,
            boot_origin: None,
            retained_fdt: Some(retained_fdt),
            rtc_device: Some(parts.rtc_device),
            serial_device: parts.serial_device,
            vmgenid_device: parts.vmgenid_device,
            vmclock_device: parts.vmclock_device,
            pvtime_state: Arm64BootPvTimeState::restored(parts.pvtime_layout),
            block_devices,
            block_async_runtime: async_runtime.unwrap_or_default(),
            pci_block_devices: Vec::new(),
            pmem_devices,
            pmem_mmio_devices,
            network_devices: Vec::new(),
            pci_network_devices: Vec::new(),
            vsock_device: None,
            pci_vsock_device: None,
            balloon_device,
            pci_balloon_device: None,
            memory_hotplug_device: None,
            pci_memory_hotplug_device: None,
            entropy_device: None,
            pci_entropy_device: None,
            pci_validation: None,
        };
        let network_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let entropy_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let snapshot_lineage =
            restored_v2_snapshot_lineage(parts.memory_binding, &runtime_resources);
        let session = Self {
            runner: parts.runner,
            backend: parts.backend,
            mmio_dispatcher: parts.mmio_dispatcher,
            runtime_resources,
            restored_snapshot_v2_mmio_registrations: Some(
                HvfSnapshotV2MultiBlockMmioRegistrations {
                    owner: registration_owner,
                    leases: registration_leases,
                    pmem_ranges,
                },
            ),
            restored_snapshot_v2_pci_pmem_ranges: None,
            snapshot_lineage,
            restored_snapshot_v2_machine: Some(parts.machine),
            cpu_template_application,
            pci_validation_endpoint: None,
            pci_data_devices: None,
            cache_source,
            cache_hierarchy: None,
            control_wakeup: HvfArm64BootRunLoopControlWakeupToken::default(),
            run_loop_wakeup: HvfArm64BootRunLoopWakeupToken::default(),
            block_retry_wakeup,
            block_retry_wakeup_scheduler,
            pmem_retry_wakeup,
            pmem_retry_wakeup_scheduler,
            network_retry_wakeup,
            network_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_retry_wakeup,
            entropy_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_source: VirtioRngOsEntropySource::new(),
            block_device_metrics,
            pmem_device_metrics,
            balloon_device_metrics,
            memory_hotplug_device_metrics: None,
            network_interface_metrics: SharedNetworkInterfaceMetricsRegistry::default(),
            vsock_device_metrics: SharedVsockDeviceMetrics::default(),
            entropy_device_metrics: SharedEntropyDeviceMetrics::default(),
            gic,
            block_interrupt_lines,
            pmem_interrupt_lines,
            network_interrupt_lines: Vec::new(),
            vsock_interrupt_line: None,
            balloon_interrupt_line,
            entropy_interrupt_line: None,
            memory_hotplug_interrupt_line: None,
            serial_interrupt_line,
            serial_input: serial_input.map(HvfArm64BootSerialInput::new),
            vmgenid_interrupt_line,
            vmclock_interrupt_line,
            boot_registers: None,
        };
        let configs =
            CaptureReadyStorageConfigs::new(drive_configs.into_vec(), pmem_configs.into_vec());
        Ok(RestoredHvfSnapshotV2StorageMmioOwners { session, configs })
    }

    /// Reconstructs one exact-2.6 heterogeneous PCI vector without publishing
    /// a process session, controller, or public load path.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_storage_pci(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2DefaultProcessShell,
        bundle: PreparedSnapshotV2StorageBundle,
        plan: HvfSnapshotV2StoragePciPlatformPlan,
    ) -> Result<RestoredHvfSnapshotV2StoragePciOwners, HvfSnapshotV2StoragePciRestoreError> {
        Self::restore_snapshot_v2_storage_pci_inner(
            state,
            memory,
            HvfSnapshotV2StorageProcessShell::Default(process_shell),
            None,
            bundle,
            plan,
            HvfSnapshotV2StoragePciPublicationInput::empty(),
        )
    }

    /// Reconstructs one exact-2.7 serial plus profile-3 PCI owner vector.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_serial_storage_pci(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2RestoredSerialShell,
        serial_input: Option<SerialStdioInput>,
        bundle: PreparedSnapshotV2StorageBundle,
        plan: HvfSnapshotV2StoragePciPlatformPlan,
    ) -> Result<RestoredHvfSnapshotV2StoragePciOwners, HvfSnapshotV2StoragePciRestoreError> {
        Self::restore_snapshot_v2_storage_pci_inner(
            state,
            memory,
            HvfSnapshotV2StorageProcessShell::Restored(process_shell),
            serial_input,
            bundle,
            plan,
            HvfSnapshotV2StoragePciPublicationInput::empty(),
        )
    }

    /// Deterministically fails after one pmem mapping is installed but before
    /// its PCI endpoint becomes reachable.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_storage_pci_with_pmem_publication_fault(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2DefaultProcessShell,
        bundle: PreparedSnapshotV2StorageBundle,
        plan: HvfSnapshotV2StoragePciPlatformPlan,
        pmem_index: usize,
    ) -> Result<RestoredHvfSnapshotV2StoragePciOwners, HvfSnapshotV2StoragePciRestoreError> {
        Self::restore_snapshot_v2_storage_pci_inner(
            state,
            memory,
            HvfSnapshotV2StorageProcessShell::Default(process_shell),
            None,
            bundle,
            plan,
            HvfSnapshotV2StoragePciPublicationInput::pmem_fault(pmem_index),
        )
    }

    #[allow(clippy::too_many_lines)]
    fn restore_snapshot_v2_storage_pci_inner(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2StorageProcessShell,
        serial_input: Option<SerialStdioInput>,
        bundle: PreparedSnapshotV2StorageBundle,
        plan: HvfSnapshotV2StoragePciPlatformPlan,
        publication: HvfSnapshotV2StoragePciPublicationInput<'_>,
    ) -> Result<RestoredHvfSnapshotV2StoragePciOwners, HvfSnapshotV2StoragePciRestoreError> {
        let HvfSnapshotV2StoragePciPublicationInput {
            balloon: balloon_publication,
            network: mut network_publication,
            vsock: mut vsock_publication,
            pmem_fault_index: publication_fault_pmem_index,
            balloon_fault,
        } = publication;
        let following_vsock_index = network_publication
            .as_ref()
            .map_or(0, |network| network.interfaces.len());
        if balloon_publication.is_none() && balloon_fault.is_some()
            || balloon_fault.is_some_and(|fault| {
                !matches!(
                    fault,
                    HvfSnapshotV2BalloonPciRestoreFault::RegistryCreation
                        | HvfSnapshotV2BalloonPciRestoreFault::RegistryRelease
                        | HvfSnapshotV2BalloonPciRestoreFault::EndpointPreparation
                        | HvfSnapshotV2BalloonPciRestoreFault::BalloonPublication
                        | HvfSnapshotV2BalloonPciRestoreFault::StoragePublication
                        | HvfSnapshotV2BalloonPciRestoreFault::ManagerInsertion
                )
            })
        {
            return Err(HvfSnapshotV2StoragePciRestoreError::preflight(
                HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan,
            ));
        }
        let mut ranges = Vec::new();
        ranges
            .try_reserve_exact(memory.regions().len())
            .map_err(|_| {
                HvfSnapshotV2StoragePciRestoreError::preflight(
                    HvfSnapshotV2StoragePciRestoreStage::MemoryLayout,
                    HvfSnapshotV2StoragePciRestoreFailure::Allocation,
                )
            })?;
        ranges.extend(memory.regions().iter().map(|region| region.range()));
        let layout = GuestMemoryLayout::new(ranges).map_err(|_| {
            HvfSnapshotV2StoragePciRestoreError::preflight(
                HvfSnapshotV2StoragePciRestoreStage::MemoryLayout,
                HvfSnapshotV2StoragePciRestoreFailure::MemoryLayout,
            )
        })?;
        let source_fdt = state.machine().fdt();
        let retained_fdt = Arm64FdtGuestMemoryWrite {
            address: source_fdt.address(),
            size: usize::try_from(source_fdt.size()).map_err(|_| {
                HvfSnapshotV2StoragePciRestoreError::preflight(
                    HvfSnapshotV2StoragePciRestoreStage::MemoryLayout,
                    HvfSnapshotV2StoragePciRestoreFailure::Allocation,
                )
            })?,
        };
        let prepared = bundle.prepare_pci_transport().map_err(|source| {
            HvfSnapshotV2StoragePciRestoreError::preflight(
                HvfSnapshotV2StoragePciRestoreStage::Transport,
                HvfSnapshotV2StoragePciRestoreFailure::Transport(source),
            )
        })?;
        let plan = plan.into_parts();
        if !validate_snapshot_v2_storage_pci_resource_plan(
            &prepared,
            &plan,
            state.machine().boot().boot_arguments(),
        ) {
            return Err(
                HvfSnapshotV2StoragePciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan,
                    prepared,
                ),
            );
        }

        let HvfSnapshotV2StoragePciPlatformPlanParts {
            root_key: _,
            command_line,
            block_metrics_ids,
            pmem_metrics_ids,
            block_retries,
            pmem_retries,
            pci: pci_plan,
            serial_interrupt,
            vmgenid_interrupt,
            vmclock_interrupt,
        } = plan;
        let block_count = pci_plan.block_records().len();
        let pmem_count = pci_plan.pmem_records().len();
        let record_count = block_count.saturating_add(pmem_count);
        if publication_fault_pmem_index.is_some_and(|index| index >= pmem_count)
            || balloon_publication
                .as_ref()
                .is_some_and(|(endpoint, balloon)| {
                    !snapshot_v2_balloon_pci_plan_matches(balloon, *endpoint)
                        || endpoint.msi_interrupt_count() != pci_plan.msi().interrupt_range.count
                })
        {
            return Err(
                HvfSnapshotV2StoragePciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan,
                    prepared,
                ),
            );
        }
        let earliest_block_retry_deadline = block_retries
            .iter()
            .filter_map(|retry| retry.retry_deadline())
            .min();
        let earliest_pmem_retry_deadline = pmem_retries
            .iter()
            .filter_map(|retry| retry.retry_deadline())
            .min();
        let block_device_metrics =
            match SharedBlockDeviceMetricsRegistry::from_owned_drive_ids_with_capacity(
                block_metrics_ids,
                PCI_ENDPOINT_SLOT_COUNT,
            ) {
                Ok(metrics) => metrics,
                Err(source) => {
                    return Err(
                        HvfSnapshotV2StoragePciRestoreError::with_prepared_bundle_abort(
                            HvfSnapshotV2StoragePciRestoreStage::BlockMetrics,
                            HvfSnapshotV2StoragePciRestoreFailure::BlockMetrics(source),
                            prepared,
                        ),
                    );
                }
            };
        let pmem_device_metrics =
            match SharedPmemDeviceMetricsRegistry::from_owned_device_ids_with_capacity(
                pmem_metrics_ids,
                PCI_ENDPOINT_SLOT_COUNT,
            ) {
                Ok(metrics) => metrics,
                Err(source) => {
                    return Err(
                        HvfSnapshotV2StoragePciRestoreError::with_prepared_bundle_abort(
                            HvfSnapshotV2StoragePciRestoreStage::PmemMetrics,
                            HvfSnapshotV2StoragePciRestoreFailure::PmemMetrics(source),
                            prepared,
                        ),
                    );
                }
            };

        let mut pmem_static_reserved_ranges = Vec::new();
        let mut block = Vec::new();
        let mut network = Vec::new();
        let mut pmem = Vec::new();
        let mut prepared_publications = Vec::new();
        let mut pmem_devices = Vec::new();
        let mut pmem_ranges = Vec::new();
        let route_count = match usize::try_from(pci_plan.msi().interrupt_range.count) {
            Ok(route_count) => route_count,
            Err(_) => {
                return Err(
                    HvfSnapshotV2StoragePciRestoreError::with_prepared_bundle_abort(
                        HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                        HvfSnapshotV2StoragePciRestoreFailure::Allocation,
                        prepared,
                    ),
                );
            }
        };
        let mut exact_intids = Vec::new();
        let mut cleanup = Vec::new();
        let capacity_ok = pmem_static_reserved_ranges
            .try_reserve_exact(layout.ranges().len())
            .is_ok()
            && block.try_reserve_exact(PCI_ENDPOINT_SLOT_COUNT).is_ok()
            && network.try_reserve_exact(PCI_ENDPOINT_SLOT_COUNT).is_ok()
            && pmem.try_reserve_exact(PCI_ENDPOINT_SLOT_COUNT).is_ok()
            && prepared_publications
                .try_reserve_exact(record_count)
                .is_ok()
            && pmem_devices.try_reserve_exact(pmem_count).is_ok()
            && pmem_ranges.try_reserve_exact(pmem_count).is_ok()
            && exact_intids.try_reserve_exact(route_count).is_ok()
            && cleanup
                .try_reserve_exact(record_count.saturating_mul(2).saturating_add(10))
                .is_ok();
        if !capacity_ok {
            return Err(
                HvfSnapshotV2StoragePciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                    HvfSnapshotV2StoragePciRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        pmem_static_reserved_ranges.extend(layout.ranges().iter().copied());
        for offset in 0..pci_plan.msi().interrupt_range.count {
            let Some(intid) = pci_plan.msi().interrupt_range.base.checked_add(offset) else {
                return Err(
                    HvfSnapshotV2StoragePciRestoreError::with_prepared_bundle_abort(
                        HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan,
                        prepared,
                    ),
                );
            };
            exact_intids.push(intid);
        }

        let shell_plan = HvfSnapshotV2StoragePciShellPlan {
            command_line: &command_line,
            pci: &pci_plan,
            serial_interrupt,
            vmgenid_interrupt,
            vmclock_interrupt,
        };
        let restored = match process_shell {
            HvfSnapshotV2StorageProcessShell::Default(shell) => {
                restore_hvf_snapshot_v2_storage_pci_process_platform(
                    state, memory, shell, shell_plan,
                )
            }
            HvfSnapshotV2StorageProcessShell::Restored(shell) => {
                restore_hvf_snapshot_v2_serial_storage_pci_process_platform(
                    state, memory, shell, shell_plan,
                )
            }
            HvfSnapshotV2StorageProcessShell::RestoredMemoryHotplugPci { shell, mapping } => {
                restore_hvf_snapshot_v2_serial_storage_memory_hotplug_pci_process_platform(
                    state, memory, shell, shell_plan, &mapping,
                )
            }
            HvfSnapshotV2StorageProcessShell::RestoredNetworkPci {
                shell,
                process,
                mapping,
            } => restore_hvf_snapshot_v2_serial_network_pci_process_platform(
                state,
                memory,
                shell,
                HvfSnapshotV2NetworkPciShellPlan {
                    storage: Some(shell_plan),
                    host: process.host,
                    msi: process.msi,
                    endpoint_count: process.endpoint_count,
                    route_demand: process.route_demand,
                    memory_hotplug: process.memory_hotplug,
                    serial_interrupt: process.serial,
                    vmgenid_interrupt: process.vmgenid,
                    vmclock_interrupt: process.vmclock,
                },
                mapping.as_ref(),
            ),
            HvfSnapshotV2StorageProcessShell::RestoredEntropyMmio { .. }
            | HvfSnapshotV2StorageProcessShell::RestoredBalloonMmio { .. }
            | HvfSnapshotV2StorageProcessShell::RestoredMemoryHotplugMmio { .. }
            | HvfSnapshotV2StorageProcessShell::RestoredNetworkMmio { .. } => {
                return Err(
                    HvfSnapshotV2StoragePciRestoreError::with_prepared_bundle_abort(
                        HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan,
                        prepared,
                    ),
                );
            }
        };
        let mut platform = match restored {
            Ok(platform) => platform,
            Err(source) => {
                return Err(HvfSnapshotV2StoragePciRestoreError::platform(
                    source, prepared,
                ));
            }
        };
        let (_root_key, block_bundle, pmem_configs, pmem_records) = prepared.into_parts();
        let mut drive_configs = DriveConfigs::new();
        let mut block_records = Vec::new();
        let mut async_runtime = None;
        if let Some(block_bundle) = block_bundle {
            let (configs, records, runtime, async_generations) = block_bundle.into_parts();
            debug_assert_eq!(
                async_generations.len(),
                records
                    .iter()
                    .filter(|record| record.async_generation().is_some())
                    .count()
            );
            drop(async_generations);
            drive_configs = configs;
            block_records = records;
            async_runtime = runtime;
        }

        let mut block_retry_wakeup_scheduler = None;
        let mut pmem_retry_wakeup_scheduler = None;
        let balloon_device_metrics = SharedBalloonDeviceMetrics::default();
        let mut pci_data_devices = None;
        let mut prepared_balloon_publication = None;
        let mut restored_network = None;
        let mut restored_network_metrics = None;
        macro_rules! fail_after_platform {
            ($stage:expr, $failure:expr) => {{
                release_unpublished_snapshot_v2_balloon_pci_publication(
                    &mut prepared_balloon_publication,
                    &mut cleanup,
                );
                release_unpublished_snapshot_v2_storage_pci_publications(
                    &mut prepared_publications,
                    &mut cleanup,
                );
                return Err(failed_snapshot_v2_storage_pci_after_platform(
                    platform,
                    $stage,
                    $failure,
                    HvfSnapshotV2StoragePciCleanup {
                        block_scheduler: &mut block_retry_wakeup_scheduler,
                        pmem_scheduler: &mut pmem_retry_wakeup_scheduler,
                        async_runtime: async_runtime.as_ref(),
                        pci_data_devices: &mut pci_data_devices,
                        pmem_devices: &mut pmem_devices,
                        failures: cleanup,
                    },
                ));
            }};
        }

        let validation = {
            let dispatcher_owner = Arc::clone(platform.mmio_dispatcher());
            let mut dispatcher = match dispatcher_owner.lock() {
                Ok(dispatcher) => dispatcher,
                Err(_) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciHost,
                    HvfSnapshotV2StoragePciRestoreFailure::DispatcherUnavailable
                ),
            };
            match prepare_restored_pci_validation(&mut dispatcher) {
                Ok(validation) => validation,
                Err(source) => {
                    drop(dispatcher);
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::PciHost,
                        HvfSnapshotV2StoragePciRestoreFailure::PciHost(source)
                    )
                }
            }
        };
        let available_slots = match validation
            .segment()
            .with_segment(|segment| segment.available_endpoint_slots())
        {
            Ok(available_slots) => available_slots,
            Err(source) => fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::PciHost,
                HvfSnapshotV2StoragePciRestoreFailure::PciData(HvfArm64BootPciDataError::new(
                    format!("failed to inspect restored PCI endpoint capacity: {source}")
                ))
            ),
        };
        if available_slots < PCI_ENDPOINT_SLOT_COUNT {
            fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::PciHost,
                HvfSnapshotV2StoragePciRestoreFailure::PciData(HvfArm64BootPciDataError::new(
                    "restored PCI segment cannot retain complete endpoint headroom"
                ))
            );
        }
        let available_bars = match pci_data_available_bar_count(validation.bar_allocator()) {
            Ok(available_bars) => available_bars,
            Err(source) => fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::PciHost,
                HvfSnapshotV2StoragePciRestoreFailure::PciData(source)
            ),
        };
        if available_bars < PCI_ENDPOINT_SLOT_COUNT {
            fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::PciHost,
                HvfSnapshotV2StoragePciRestoreFailure::PciData(HvfArm64BootPciDataError::new(
                    "restored PCI BAR allocator cannot retain complete endpoint headroom"
                ))
            );
        }
        let bar_plan = match pci_data_bar_plan(validation.bar_allocator(), PCI_ENDPOINT_SLOT_COUNT)
        {
            Ok(bar_plan) => bar_plan,
            Err(source) => fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::PciHost,
                HvfSnapshotV2StoragePciRestoreFailure::PciData(source)
            ),
        };
        {
            let dispatcher_owner = Arc::clone(platform.mmio_dispatcher());
            let dispatcher = match dispatcher_owner.lock() {
                Ok(dispatcher) => dispatcher,
                Err(_) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciHost,
                    HvfSnapshotV2StoragePciRestoreFailure::DispatcherUnavailable
                ),
            };
            if let Err(source) = preflight_pci_data_dispatcher(&dispatcher, &bar_plan) {
                drop(dispatcher);
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciHost,
                    HvfSnapshotV2StoragePciRestoreFailure::PciData(source)
                );
            }
        }
        let signaler = match platform.backend().gic_msi_signaler() {
            Some(signaler) => signaler,
            None => fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::PciRoutes,
                HvfSnapshotV2StoragePciRestoreFailure::PciData(HvfArm64BootPciDataError::new(
                    "restored PCI vector requires a GICv2m MSI signaler"
                ))
            ),
        };
        let msi_interrupts =
            match HvfGicMsiDeviceInterruptResources::allocate_exact(signaler, &exact_intids) {
                Ok(interrupts) => interrupts,
                Err(source) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciRoutes,
                    HvfSnapshotV2StoragePciRestoreFailure::PciRoutes(source)
                ),
            };
        pci_data_devices = Some(HvfArm64BootPciDataDevices {
            validation,
            dispatcher: Arc::clone(platform.mmio_dispatcher()),
            msi_interrupts: Some(msi_interrupts),
            balloon: None,
            block,
            network,
            pmem,
            vsock: None,
            entropy: None,
            memory_hotplug: None,
            pmem_static_reserved_ranges,
            runtime_hotplug: true,
        });

        if let Some((planned, balloon)) = balloon_publication {
            if balloon_fault == Some(HvfSnapshotV2BalloonPciRestoreFault::RegistryCreation) {
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciRoutes,
                    HvfSnapshotV2StoragePciRestoreFailure::InjectedPublication
                );
            }
            let manager = match pci_data_devices.as_ref() {
                Some(manager) => manager,
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciRoutes,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let mut interrupts = match manager.shared_msi_registry() {
                Ok(interrupts) => interrupts,
                Err(source) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciRoutes,
                    HvfSnapshotV2StoragePciRestoreFailure::PciData(source)
                ),
            };
            if matches!(
                balloon_fault,
                Some(
                    HvfSnapshotV2BalloonPciRestoreFault::RegistryRelease
                        | HvfSnapshotV2BalloonPciRestoreFault::EndpointPreparation
                )
            ) {
                release_unpublished_snapshot_v2_balloon_pci_interrupts(
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index: 0 },
                    HvfSnapshotV2StoragePciRestoreFailure::InjectedPublication
                );
            }
            let endpoint =
                match balloon.into_pci_endpoint(planned.bar_region_id(), interrupts.registry()) {
                    Ok(endpoint) => endpoint,
                    Err(_) => {
                        release_unpublished_snapshot_v2_balloon_pci_interrupts(
                            &mut interrupts,
                            &mut cleanup,
                        );
                        fail_after_platform!(
                            HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index: 0 },
                            HvfSnapshotV2StoragePciRestoreFailure::PciData(
                                HvfArm64BootPciDataError::new(
                                    "exact-2.9 balloon endpoint preparation failed",
                                ),
                            )
                        )
                    }
                };
            if let Err(source) = endpoint.attach_metrics(balloon_device_metrics.clone()) {
                drop(endpoint);
                release_unpublished_snapshot_v2_balloon_pci_interrupts(
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index: 0 },
                    HvfSnapshotV2StoragePciRestoreFailure::PciData(HvfArm64BootPciDataError::new(
                        format!("failed to bind restored balloon metrics: {source}")
                    ),)
                );
            }
            if endpoint.origin() != planned.origin()
                || endpoint.endpoint().sbdf() != planned.sbdf()
                || endpoint.endpoint().bar_range() != planned.bar_range()
                || endpoint.endpoint().region_id() != planned.bar_region_id()
            {
                drop(endpoint);
                release_unpublished_snapshot_v2_balloon_pci_interrupts(
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index: 0 },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                );
            }
            prepared_balloon_publication = Some(PreparedHvfSnapshotV2BalloonPciPublication {
                endpoint,
                interrupts,
            });
        }

        for (index, (record, planned)) in block_records
            .into_iter()
            .zip(pci_plan.block_records())
            .enumerate()
        {
            let manager = match pci_data_devices.as_mut() {
                Some(manager) => manager,
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciRoutes,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let mut interrupts = match manager.shared_msi_registry() {
                Ok(interrupts) => interrupts,
                Err(source) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index },
                    HvfSnapshotV2StoragePciRestoreFailure::PciData(source)
                ),
            };
            let endpoint =
                match record.prepare_endpoint(planned.bar_region_id(), interrupts.registry()) {
                    Ok(endpoint) => endpoint,
                    Err(source) => {
                        release_unpublished_snapshot_v2_storage_pci_interrupts(
                            index,
                            &mut interrupts,
                            &mut cleanup,
                        );
                        fail_after_platform!(
                            HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index },
                            HvfSnapshotV2StoragePciRestoreFailure::PciEndpoint(source)
                        )
                    }
                };
            let metrics_lease = match block_device_metrics.claim_drive_lease(endpoint.drive_id()) {
                Ok(lease) => lease,
                Err(source) => {
                    drop(endpoint);
                    release_unpublished_snapshot_v2_storage_pci_interrupts(
                        index,
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index },
                        HvfSnapshotV2StoragePciRestoreFailure::BlockMetrics(source)
                    )
                }
            };
            prepared_publications.push(Some(PreparedHvfSnapshotV2StoragePciPublication::Block {
                endpoint,
                interrupts,
                metrics_lease,
            }));
        }
        for (pmem_index, (mut record, planned)) in pmem_records
            .into_iter()
            .zip(pci_plan.pmem_records())
            .enumerate()
        {
            let index = block_count.saturating_add(pmem_index);
            let manager = match pci_data_devices.as_mut() {
                Some(manager) => manager,
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciRoutes,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let mut interrupts = match manager.shared_msi_registry() {
                Ok(interrupts) => interrupts,
                Err(source) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index },
                    HvfSnapshotV2StoragePciRestoreFailure::PciData(source)
                ),
            };
            let device_metrics = match pmem_device_metrics.per_device(record.pmem_id()) {
                Some(metrics) => metrics,
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            record.attach_metrics(device_metrics, pmem_device_metrics.aggregate());
            let endpoint =
                match record.prepare_endpoint(planned.bar_region_id(), interrupts.registry()) {
                    Ok(endpoint) => endpoint,
                    Err(source) => {
                        release_unpublished_snapshot_v2_storage_pci_interrupts(
                            index,
                            &mut interrupts,
                            &mut cleanup,
                        );
                        fail_after_platform!(
                            HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index },
                            HvfSnapshotV2StoragePciRestoreFailure::PciEndpoint(source)
                        )
                    }
                };
            let metrics_lease = match pmem_device_metrics.claim_device_lease(endpoint.pmem_id()) {
                Ok(lease) => lease,
                Err(source) => {
                    drop(endpoint);
                    release_unpublished_snapshot_v2_storage_pci_interrupts(
                        index,
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation { index },
                        HvfSnapshotV2StoragePciRestoreFailure::PmemMetrics(source)
                    )
                }
            };
            prepared_publications.push(Some(PreparedHvfSnapshotV2StoragePciPublication::Pmem {
                endpoint,
                interrupts,
                metrics_lease,
            }));
        }

        let block_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        if block_count == 0 {
            block_retry_wakeup_scheduler =
                Some(HvfArm64BootLimiterRetryWakeupScheduler::inactive());
        } else {
            let vcpu_control = platform.control();
            block_retry_wakeup_scheduler =
                match HvfArm64BootLimiterRetryWakeupScheduler::start_with_cancellation(
                    BLOCK_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
                    block_retry_wakeup.clone(),
                    move || vcpu_control.request_wakeup(),
                ) {
                    Ok(scheduler) => Some(scheduler),
                    Err(source) => {
                        release_unpublished_snapshot_v2_storage_pci_publications(
                            &mut prepared_publications,
                            &mut cleanup,
                        );
                        fail_after_platform!(
                            HvfSnapshotV2StoragePciRestoreStage::BlockRetryScheduler,
                            HvfSnapshotV2StoragePciRestoreFailure::RetryScheduler(source.kind())
                        )
                    }
                };
        }
        let pmem_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        if pmem_count == 0 {
            pmem_retry_wakeup_scheduler = Some(HvfArm64BootLimiterRetryWakeupScheduler::inactive());
        } else {
            let vcpu_control = platform.control();
            pmem_retry_wakeup_scheduler =
                match HvfArm64BootLimiterRetryWakeupScheduler::start_with_cancellation(
                    PMEM_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
                    pmem_retry_wakeup.clone(),
                    move || vcpu_control.request_wakeup(),
                ) {
                    Ok(scheduler) => Some(scheduler),
                    Err(source) => {
                        release_unpublished_snapshot_v2_storage_pci_publications(
                            &mut prepared_publications,
                            &mut cleanup,
                        );
                        fail_after_platform!(
                            HvfSnapshotV2StoragePciRestoreStage::PmemRetryScheduler,
                            HvfSnapshotV2StoragePciRestoreFailure::RetryScheduler(source.kind())
                        )
                    }
                };
        }

        if balloon_fault == Some(HvfSnapshotV2BalloonPciRestoreFault::BalloonPublication) {
            release_unpublished_snapshot_v2_balloon_pci_publication(
                &mut prepared_balloon_publication,
                &mut cleanup,
            );
            fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                HvfSnapshotV2StoragePciRestoreFailure::InjectedPublication
            );
        }
        if let Some(PreparedHvfSnapshotV2BalloonPciPublication {
            endpoint,
            interrupts,
        }) = prepared_balloon_publication.take()
        {
            let (_config, _queue_ranges, origin, endpoint) = endpoint.into_parts();
            if origin != StorageDeviceOrigin::Startup {
                drop(endpoint);
                let mut interrupts = interrupts;
                release_unpublished_snapshot_v2_balloon_pci_interrupts(
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                );
            }
            let (dispatcher_owner, segment) = match pci_data_devices.as_ref() {
                Some(manager)
                    if manager.balloon.is_none()
                        && manager.endpoint_count() == 0
                        && manager.block.is_empty()
                        && manager.pmem.is_empty()
                        && manager.entropy.is_none() =>
                {
                    (
                        Arc::clone(&manager.dispatcher),
                        manager.validation.segment().clone(),
                    )
                }
                _ => {
                    drop(endpoint);
                    let mut interrupts = interrupts;
                    release_unpublished_snapshot_v2_balloon_pci_interrupts(
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    )
                }
            };
            let mut dispatcher = match dispatcher_owner.lock() {
                Ok(dispatcher) => dispatcher,
                Err(_) => {
                    drop(endpoint);
                    let mut interrupts = interrupts;
                    release_unpublished_snapshot_v2_balloon_pci_interrupts(
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                        HvfSnapshotV2StoragePciRestoreFailure::DispatcherUnavailable
                    )
                }
            };
            let publication = match pci_data_devices.as_mut() {
                Some(manager) => endpoint.publish(
                    manager.validation.bar_allocator_mut(),
                    segment,
                    &mut dispatcher,
                    interrupts,
                ),
                None => {
                    drop(dispatcher);
                    drop(endpoint);
                    let mut interrupts = interrupts;
                    release_unpublished_snapshot_v2_balloon_pci_interrupts(
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    )
                }
            };
            drop(dispatcher);
            let published = match publication {
                Ok(published) => published,
                Err(source) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                    HvfSnapshotV2StoragePciRestoreFailure::PciPublication(source)
                ),
            };
            let Some(manager) = pci_data_devices.as_mut() else {
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                );
            };
            manager.balloon = Some(HvfArm64BootPciBalloonDevice {
                published,
                queue_deliveries: 0,
            });
            if balloon_fault == Some(HvfSnapshotV2BalloonPciRestoreFault::ManagerInsertion) {
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                    HvfSnapshotV2StoragePciRestoreFailure::InjectedPublication
                );
            }
        }
        if balloon_fault == Some(HvfSnapshotV2BalloonPciRestoreFault::StoragePublication) {
            fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::Publication { index: 0 },
                HvfSnapshotV2StoragePciRestoreFailure::InjectedPublication
            );
        }

        for index in 0..block_count {
            let planned = match pci_plan.block_records().get(index) {
                Some(planned) => planned,
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let publication = match prepared_publications.get_mut(index).and_then(Option::take) {
                Some(PreparedHvfSnapshotV2StoragePciPublication::Block {
                    endpoint,
                    interrupts,
                    metrics_lease,
                }) => (endpoint, interrupts, metrics_lease),
                Some(other) => {
                    release_unpublished_snapshot_v2_storage_pci_publication(
                        index,
                        other,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    )
                }
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let (endpoint, mut interrupts, metrics_lease) = publication;
            if endpoint.key() != planned.key() {
                drop(endpoint);
                drop(metrics_lease);
                release_unpublished_snapshot_v2_storage_pci_interrupts(
                    index,
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                );
            }
            let (
                _key,
                drive_id,
                is_root_device,
                _retry,
                retry_deadline,
                origin,
                _async_generation,
                endpoint,
            ) = endpoint.into_parts();
            let (dispatcher_owner, segment) = match pci_data_devices.as_ref() {
                Some(manager) if manager.block.len() == index => (
                    Arc::clone(&manager.dispatcher),
                    manager.validation.segment().clone(),
                ),
                _ => {
                    drop(endpoint);
                    drop(metrics_lease);
                    release_unpublished_snapshot_v2_storage_pci_interrupts(
                        index,
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    )
                }
            };
            let mut dispatcher = match dispatcher_owner.lock() {
                Ok(dispatcher) => dispatcher,
                Err(_) => {
                    drop(endpoint);
                    drop(metrics_lease);
                    release_unpublished_snapshot_v2_storage_pci_interrupts(
                        index,
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                        HvfSnapshotV2StoragePciRestoreFailure::DispatcherUnavailable
                    )
                }
            };
            let publication = match pci_data_devices.as_mut() {
                Some(manager) => endpoint.publish(
                    manager.validation.bar_allocator_mut(),
                    segment,
                    &mut dispatcher,
                    interrupts,
                ),
                None => {
                    drop(dispatcher);
                    drop(endpoint);
                    drop(metrics_lease);
                    release_unpublished_snapshot_v2_storage_pci_interrupts(
                        index,
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    )
                }
            };
            drop(dispatcher);
            let published = match publication {
                Ok(published) => published,
                Err(source) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::PciPublication(source)
                ),
            };
            let Some(manager) = pci_data_devices.as_mut() else {
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                );
            };
            manager.block.push(HvfArm64BootPciBlockDevice {
                drive_id,
                is_root_device,
                origin,
                published,
                queue_deliveries: 0,
                retry_deadline,
                _metrics_lease: Some(metrics_lease),
            });
        }

        if let Some(network) = network_publication.take() {
            let memory = match platform.guest_memory() {
                Ok(memory) => memory,
                Err(_) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let manager = match pci_data_devices.as_mut() {
                Some(manager) => manager,
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciHost,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            match publish_snapshot_v2_network_pci_batch(manager, memory, network) {
                Ok((network, metrics)) => {
                    restored_network = Some(network);
                    restored_network_metrics = Some(metrics);
                }
                Err(failure) => {
                    if failure.cleanup_failed {
                        cleanup.push(HvfSnapshotV2StoragePciRestoreCleanupFailure::Pci(
                            HvfArm64BootPciDataError::new(
                                "exact-2.11 PCI network prefix cleanup was incomplete",
                            ),
                        ));
                    }
                    let stage = match failure.kind {
                        HvfSnapshotV2NetworkPciBatchFailureKind::Preparation => {
                            HvfSnapshotV2StoragePciRestoreStage::EndpointPreparation {
                                index: block_count.saturating_add(failure.index),
                            }
                        }
                        HvfSnapshotV2NetworkPciBatchFailureKind::Publication => {
                            HvfSnapshotV2StoragePciRestoreStage::Publication {
                                index: block_count.saturating_add(failure.index),
                            }
                        }
                    };
                    fail_after_platform!(
                        stage,
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    );
                }
            }
        }

        for pmem_index in 0..pmem_count {
            let index = block_count.saturating_add(pmem_index);
            let planned = match pci_plan.pmem_records().get(pmem_index) {
                Some(planned) => planned,
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let publication = match prepared_publications.get_mut(index).and_then(Option::take) {
                Some(PreparedHvfSnapshotV2StoragePciPublication::Pmem {
                    endpoint,
                    interrupts,
                    metrics_lease,
                }) => (endpoint, interrupts, metrics_lease),
                Some(other) => {
                    release_unpublished_snapshot_v2_storage_pci_publication(
                        index,
                        other,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    )
                }
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let (endpoint, mut interrupts, metrics_lease) = publication;
            if endpoint.key() != planned.key() {
                drop(endpoint);
                drop(metrics_lease);
                release_unpublished_snapshot_v2_storage_pci_interrupts(
                    index,
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                );
            }
            let (_key, _is_root_device, _retry, retry_deadline, origin, prepared_device, endpoint) =
                endpoint.into_parts();
            let mut pmem_id = String::new();
            if pmem_id
                .try_reserve_exact(prepared_device.id().len())
                .is_err()
            {
                drop(endpoint);
                drop(metrics_lease);
                release_unpublished_snapshot_v2_storage_pci_interrupts(
                    index,
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::Allocation
                );
            }
            pmem_id.push_str(prepared_device.id());
            let guest_range = prepared_device.guest_range();
            if let Err(source) = platform
                .backend_mut()
                .map_runtime_pmem_device(&prepared_device)
            {
                drop(endpoint);
                drop(metrics_lease);
                release_unpublished_snapshot_v2_storage_pci_interrupts(
                    index,
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Mapping { index: pmem_index },
                    HvfSnapshotV2StoragePciRestoreFailure::Mapping(source)
                );
            }
            pmem_ranges.push(guest_range);
            pmem_devices.push(prepared_device);
            if publication_fault_pmem_index == Some(pmem_index) {
                drop(endpoint);
                drop(metrics_lease);
                release_unpublished_snapshot_v2_storage_pci_interrupts(
                    index,
                    &mut interrupts,
                    &mut cleanup,
                );
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::InjectedPublication
                );
            }
            let (dispatcher_owner, segment) = match pci_data_devices.as_ref() {
                Some(manager) if manager.pmem.len() == pmem_index => (
                    Arc::clone(&manager.dispatcher),
                    manager.validation.segment().clone(),
                ),
                _ => {
                    drop(endpoint);
                    drop(metrics_lease);
                    release_unpublished_snapshot_v2_storage_pci_interrupts(
                        index,
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    )
                }
            };
            let mut dispatcher = match dispatcher_owner.lock() {
                Ok(dispatcher) => dispatcher,
                Err(_) => {
                    drop(endpoint);
                    drop(metrics_lease);
                    release_unpublished_snapshot_v2_storage_pci_interrupts(
                        index,
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                        HvfSnapshotV2StoragePciRestoreFailure::DispatcherUnavailable
                    )
                }
            };
            let publication = match pci_data_devices.as_mut() {
                Some(manager) => endpoint.publish(
                    manager.validation.bar_allocator_mut(),
                    segment,
                    &mut dispatcher,
                    interrupts,
                ),
                None => {
                    drop(dispatcher);
                    drop(endpoint);
                    drop(metrics_lease);
                    release_unpublished_snapshot_v2_storage_pci_interrupts(
                        index,
                        &mut interrupts,
                        &mut cleanup,
                    );
                    fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    )
                }
            };
            drop(dispatcher);
            let published = match publication {
                Ok(published) => published,
                Err(source) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::PciPublication(source)
                ),
            };
            let Some(manager) = pci_data_devices.as_mut() else {
                fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::Publication { index },
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                );
            };
            manager.pmem.push(HvfArm64BootPciPmemDevice {
                pmem_id,
                guest_range,
                origin,
                published,
                queue_deliveries: 0,
                retry_deadline,
                _metrics_lease: Some(metrics_lease),
            });
        }

        if let Some(vsock) = vsock_publication.take() {
            let guest_logger = platform.backend().guest_logger();
            let memory = match platform.guest_memory() {
                Ok(memory) => memory,
                Err(_) => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            let manager = match pci_data_devices.as_mut() {
                Some(manager) => manager,
                None => fail_after_platform!(
                    HvfSnapshotV2StoragePciRestoreStage::PciHost,
                    HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                ),
            };
            match publish_snapshot_v2_vsock_pci(
                manager,
                memory,
                vsock,
                following_vsock_index,
                &guest_logger,
            ) {
                Ok(vsock) => match restored_network.as_mut() {
                    Some(network) if network.vsock.is_none() => network.vsock = Some(vsock),
                    _ => fail_after_platform!(
                        HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    ),
                },
                Err(failure) => {
                    if failure.cleanup_failed {
                        cleanup.push(HvfSnapshotV2StoragePciRestoreCleanupFailure::Pci(
                            HvfArm64BootPciDataError::new(
                                "exact-2.12 PCI vsock cleanup was incomplete",
                            ),
                        ));
                    }
                    let stage = match failure.kind {
                        HvfSnapshotV2NetworkPciBatchFailureKind::Preparation => {
                            HvfSnapshotV2StoragePciRestoreStage::FollowingEndpointPreparation
                        }
                        HvfSnapshotV2NetworkPciBatchFailureKind::Publication => {
                            HvfSnapshotV2StoragePciRestoreStage::FollowingEndpointPublication
                        }
                    };
                    fail_after_platform!(
                        stage,
                        HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
                    );
                }
            }
        }

        release_unpublished_snapshot_v2_balloon_pci_publication(
            &mut prepared_balloon_publication,
            &mut cleanup,
        );
        release_unpublished_snapshot_v2_storage_pci_publications(
            &mut prepared_publications,
            &mut cleanup,
        );
        if !cleanup.is_empty() {
            fail_after_platform!(
                HvfSnapshotV2StoragePciRestoreStage::ResourcePlan,
                HvfSnapshotV2StoragePciRestoreFailure::ResourcePlan
            );
        }

        let Some(block_retry_wakeup_scheduler) = block_retry_wakeup_scheduler.take() else {
            std::process::abort();
        };
        let Some(pmem_retry_wakeup_scheduler) = pmem_retry_wakeup_scheduler.take() else {
            std::process::abort();
        };
        block_retry_wakeup_scheduler.schedule_deadline(earliest_block_retry_deadline);
        pmem_retry_wakeup_scheduler.schedule_deadline(earliest_pmem_retry_deadline);

        let parts = platform.into_parts();
        let machine_config = parts.machine.machine();
        let cpu_template_application = parts.machine.cpu_template().cloned();
        let cache_source = crate::vcpu_config::HvfArm64VcpuCacheFdtSource::new(
            parts.compatibility.identification().id_aa64mmfr2_el1(),
            parts.compatibility.cache_manifest(),
        );
        let gic = parts.compatibility.gic_metadata();
        let serial_interrupt_line = parts
            .serial_device
            .as_ref()
            .map(|device| device.fdt_device.interrupt_line);
        let vmgenid_interrupt_line = parts.vmgenid_device.fdt_device.interrupt_line;
        let vmclock_interrupt_line = parts.vmclock_device.fdt_device.interrupt_line;
        let runtime_resources = Arm64BootRuntimeResources {
            machine_config,
            layout,
            boot_origin: None,
            retained_fdt: Some(retained_fdt),
            rtc_device: Some(parts.rtc_device),
            serial_device: parts.serial_device,
            vmgenid_device: parts.vmgenid_device,
            vmclock_device: parts.vmclock_device,
            pvtime_state: Arm64BootPvTimeState::restored(parts.pvtime_layout),
            block_devices: Vec::new(),
            block_async_runtime: async_runtime.unwrap_or_default(),
            pci_block_devices: Vec::new(),
            pmem_devices,
            pmem_mmio_devices: Vec::new(),
            network_devices: Vec::new(),
            pci_network_devices: Vec::new(),
            vsock_device: None,
            pci_vsock_device: None,
            balloon_device: None,
            pci_balloon_device: None,
            memory_hotplug_device: None,
            pci_memory_hotplug_device: None,
            entropy_device: None,
            pci_entropy_device: None,
            pci_validation: None,
        };
        let network_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let entropy_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let vsock_device_metrics = restored_network
            .as_ref()
            .and_then(|network| network.vsock.as_ref())
            .map_or_else(SharedVsockDeviceMetrics::default, |vsock| {
                vsock.metrics.clone()
            });
        let snapshot_lineage =
            restored_v2_snapshot_lineage(parts.memory_binding, &runtime_resources);
        let session = Self {
            runner: parts.runner,
            backend: parts.backend,
            mmio_dispatcher: parts.mmio_dispatcher,
            runtime_resources,
            restored_snapshot_v2_mmio_registrations: None,
            restored_snapshot_v2_pci_pmem_ranges: Some(pmem_ranges),
            snapshot_lineage,
            restored_snapshot_v2_machine: Some(parts.machine),
            cpu_template_application,
            pci_validation_endpoint: None,
            pci_data_devices,
            cache_source,
            cache_hierarchy: None,
            control_wakeup: HvfArm64BootRunLoopControlWakeupToken::default(),
            run_loop_wakeup: HvfArm64BootRunLoopWakeupToken::default(),
            block_retry_wakeup,
            block_retry_wakeup_scheduler,
            pmem_retry_wakeup,
            pmem_retry_wakeup_scheduler,
            network_retry_wakeup,
            network_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_retry_wakeup,
            entropy_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_source: VirtioRngOsEntropySource::new(),
            block_device_metrics,
            pmem_device_metrics,
            balloon_device_metrics,
            memory_hotplug_device_metrics: None,
            network_interface_metrics: restored_network_metrics.unwrap_or_default(),
            vsock_device_metrics,
            entropy_device_metrics: SharedEntropyDeviceMetrics::default(),
            gic,
            block_interrupt_lines: Vec::new(),
            pmem_interrupt_lines: Vec::new(),
            network_interrupt_lines: Vec::new(),
            vsock_interrupt_line: None,
            balloon_interrupt_line: None,
            entropy_interrupt_line: None,
            memory_hotplug_interrupt_line: None,
            serial_interrupt_line,
            serial_input: serial_input.map(HvfArm64BootSerialInput::new),
            vmgenid_interrupt_line,
            vmclock_interrupt_line,
            boot_registers: None,
        };
        let configs =
            CaptureReadyStorageConfigs::new(drive_configs.into_vec(), pmem_configs.into_vec());
        Ok(RestoredHvfSnapshotV2StoragePciOwners {
            session,
            configs,
            network: restored_network,
        })
    }

    /// Reconstructs one exact profile-2 PCI vector inside a private canonical
    /// manager without publishing a process session or controller.
    #[doc(hidden)]
    pub fn restore_snapshot_v2_multi_block_pci(
        state: HvfSnapshotV2PlatformState,
        memory: GuestMemory,
        process_shell: HvfSnapshotV2DefaultProcessShell,
        bundle: PreparedSnapshotV2MultiBlockBundle,
        plan: HvfSnapshotV2MultiBlockPlatformPlan,
    ) -> Result<RestoredHvfSnapshotV2MultiBlockPciOwners, HvfSnapshotV2MultiBlockPciRestoreError>
    {
        let mut ranges = Vec::new();
        ranges
            .try_reserve_exact(memory.regions().len())
            .map_err(|_| {
                HvfSnapshotV2MultiBlockPciRestoreError::preflight(
                    HvfSnapshotV2MultiBlockPciRestoreStage::MemoryLayout,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                )
            })?;
        ranges.extend(memory.regions().iter().map(|region| region.range()));
        let layout = GuestMemoryLayout::new(ranges).map_err(|_| {
            HvfSnapshotV2MultiBlockPciRestoreError::preflight(
                HvfSnapshotV2MultiBlockPciRestoreStage::MemoryLayout,
                HvfSnapshotV2MultiBlockPciRestoreFailure::MemoryLayout,
            )
        })?;
        let source_fdt = state.machine().fdt();
        let retained_fdt = Arm64FdtGuestMemoryWrite {
            address: source_fdt.address(),
            size: usize::try_from(source_fdt.size()).map_err(|_| {
                HvfSnapshotV2MultiBlockPciRestoreError::preflight(
                    HvfSnapshotV2MultiBlockPciRestoreStage::MemoryLayout,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                )
            })?,
        };
        let prepared = bundle.prepare_pci_transport().map_err(|source| {
            HvfSnapshotV2MultiBlockPciRestoreError::preflight(
                HvfSnapshotV2MultiBlockPciRestoreStage::Transport,
                HvfSnapshotV2MultiBlockPciRestoreFailure::Transport(source),
            )
        })?;
        let plan = plan.into_parts();
        if !validate_snapshot_v2_multi_block_pci_resource_plan(
            &prepared,
            &plan,
            state.machine().boot().boot_arguments(),
        ) {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
                    prepared,
                ),
            );
        }

        let HvfSnapshotV2MultiBlockPlatformPlanParts {
            root_key: _,
            command_line,
            metrics_ids,
            retries: _,
            earliest_retry_index: _,
            transport,
            serial_interrupt,
            vmgenid_interrupt,
            vmclock_interrupt,
        } = plan;
        let HvfSnapshotV2MultiBlockTransportPlan::Pci(pci_plan) = transport else {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
                    prepared,
                ),
            );
        };
        let record_count = prepared.records().len();
        let earliest_retry_deadline = prepared
            .records()
            .iter()
            .filter_map(PreparedSnapshotV2MultiBlockPciRecord::retry_deadline)
            .min();
        let block_device_metrics =
            match SharedBlockDeviceMetricsRegistry::from_owned_drive_ids_with_capacity(
                metrics_ids,
                PCI_ENDPOINT_SLOT_COUNT,
            ) {
                Ok(metrics) => metrics,
                Err(source) => {
                    return Err(
                        HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                            HvfSnapshotV2MultiBlockPciRestoreStage::Metrics,
                            HvfSnapshotV2MultiBlockPciRestoreFailure::Metrics(source),
                            prepared,
                        ),
                    );
                }
            };

        let mut pmem_static_reserved_ranges = Vec::new();
        if pmem_static_reserved_ranges
            .try_reserve_exact(layout.ranges().len())
            .is_err()
        {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        pmem_static_reserved_ranges.extend(layout.ranges().iter().copied());
        let mut block = Vec::new();
        if block.try_reserve_exact(PCI_ENDPOINT_SLOT_COUNT).is_err() {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        let mut network = Vec::new();
        if network.try_reserve_exact(PCI_ENDPOINT_SLOT_COUNT).is_err() {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        let mut pmem = Vec::new();
        if pmem.try_reserve_exact(PCI_ENDPOINT_SLOT_COUNT).is_err() {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        let mut prepared_publications = Vec::new();
        if prepared_publications
            .try_reserve_exact(record_count)
            .is_err()
        {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        let route_count = match usize::try_from(pci_plan.msi().interrupt_range.count) {
            Ok(route_count) => route_count,
            Err(_) => {
                return Err(
                    HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                        HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                        HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                        prepared,
                    ),
                );
            }
        };
        let mut exact_intids = Vec::new();
        if exact_intids.try_reserve_exact(route_count).is_err() {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }
        for offset in 0..pci_plan.msi().interrupt_range.count {
            let Some(intid) = pci_plan.msi().interrupt_range.base.checked_add(offset) else {
                return Err(
                    HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                        HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                        HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
                        prepared,
                    ),
                );
            };
            exact_intids.push(intid);
        }
        let mut cleanup = Vec::new();
        if cleanup
            .try_reserve_exact(record_count.saturating_add(6))
            .is_err()
        {
            return Err(
                HvfSnapshotV2MultiBlockPciRestoreError::with_prepared_bundle_abort(
                    HvfSnapshotV2MultiBlockPciRestoreStage::ResourcePlan,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::Allocation,
                    prepared,
                ),
            );
        }

        let shell_plan = HvfSnapshotV2MultiBlockPciShellPlan {
            command_line: &command_line,
            pci: &pci_plan,
            serial_interrupt,
            vmgenid_interrupt,
            vmclock_interrupt,
        };
        let platform = match restore_hvf_snapshot_v2_multi_block_pci_process_platform(
            state,
            memory,
            process_shell,
            shell_plan,
        ) {
            Ok(platform) => platform,
            Err(source) => {
                return Err(HvfSnapshotV2MultiBlockPciRestoreError::platform(
                    source, prepared,
                ));
            }
        };
        let (drive_configs, records, async_runtime, async_generations) = prepared.into_parts();
        debug_assert_eq!(
            async_generations.len(),
            records
                .iter()
                .filter(|record| record.async_generation().is_some())
                .count()
        );
        drop(async_generations);

        let mut block_retry_wakeup_scheduler = None;
        let mut pci_data_devices = None;
        let validation = {
            let dispatcher_owner = Arc::clone(platform.mmio_dispatcher());
            let mut dispatcher = match dispatcher_owner.lock() {
                Ok(dispatcher) => dispatcher,
                Err(_) => {
                    return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                        platform,
                        HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                        HvfSnapshotV2MultiBlockPciRestoreFailure::DispatcherUnavailable,
                        &mut block_retry_wakeup_scheduler,
                        async_runtime.as_ref(),
                        &mut pci_data_devices,
                        cleanup,
                    ));
                }
            };
            match prepare_restored_pci_validation(&mut dispatcher) {
                Ok(validation) => validation,
                Err(source) => {
                    drop(dispatcher);
                    return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                        platform,
                        HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                        HvfSnapshotV2MultiBlockPciRestoreFailure::PciHost(source),
                        &mut block_retry_wakeup_scheduler,
                        async_runtime.as_ref(),
                        &mut pci_data_devices,
                        cleanup,
                    ));
                }
            }
        };
        let available_slots = match validation
            .segment()
            .with_segment(|segment| segment.available_endpoint_slots())
        {
            Ok(available_slots) => available_slots,
            Err(source) => {
                return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                    platform,
                    HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::PciData(
                        HvfArm64BootPciDataError::new(format!(
                            "failed to inspect restored PCI endpoint capacity: {source}"
                        )),
                    ),
                    &mut block_retry_wakeup_scheduler,
                    async_runtime.as_ref(),
                    &mut pci_data_devices,
                    cleanup,
                ));
            }
        };
        if available_slots < PCI_ENDPOINT_SLOT_COUNT {
            return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                platform,
                HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                HvfSnapshotV2MultiBlockPciRestoreFailure::PciData(HvfArm64BootPciDataError::new(
                    "restored PCI segment cannot retain complete endpoint headroom",
                )),
                &mut block_retry_wakeup_scheduler,
                async_runtime.as_ref(),
                &mut pci_data_devices,
                cleanup,
            ));
        }
        let available_bars = match pci_data_available_bar_count(validation.bar_allocator()) {
            Ok(available_bars) => available_bars,
            Err(source) => {
                return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                    platform,
                    HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::PciData(source),
                    &mut block_retry_wakeup_scheduler,
                    async_runtime.as_ref(),
                    &mut pci_data_devices,
                    cleanup,
                ));
            }
        };
        if available_bars < PCI_ENDPOINT_SLOT_COUNT {
            return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                platform,
                HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                HvfSnapshotV2MultiBlockPciRestoreFailure::PciData(HvfArm64BootPciDataError::new(
                    "restored PCI BAR allocator cannot retain complete endpoint headroom",
                )),
                &mut block_retry_wakeup_scheduler,
                async_runtime.as_ref(),
                &mut pci_data_devices,
                cleanup,
            ));
        }
        let bar_plan = match pci_data_bar_plan(validation.bar_allocator(), PCI_ENDPOINT_SLOT_COUNT)
        {
            Ok(bar_plan) => bar_plan,
            Err(source) => {
                return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                    platform,
                    HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::PciData(source),
                    &mut block_retry_wakeup_scheduler,
                    async_runtime.as_ref(),
                    &mut pci_data_devices,
                    cleanup,
                ));
            }
        };
        {
            let dispatcher_owner = Arc::clone(platform.mmio_dispatcher());
            let dispatcher = match dispatcher_owner.lock() {
                Ok(dispatcher) => dispatcher,
                Err(_) => {
                    return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                        platform,
                        HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                        HvfSnapshotV2MultiBlockPciRestoreFailure::DispatcherUnavailable,
                        &mut block_retry_wakeup_scheduler,
                        async_runtime.as_ref(),
                        &mut pci_data_devices,
                        cleanup,
                    ));
                }
            };
            if let Err(source) = preflight_pci_data_dispatcher(&dispatcher, &bar_plan) {
                drop(dispatcher);
                return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                    platform,
                    HvfSnapshotV2MultiBlockPciRestoreStage::PciHost,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::PciData(source),
                    &mut block_retry_wakeup_scheduler,
                    async_runtime.as_ref(),
                    &mut pci_data_devices,
                    cleanup,
                ));
            }
        }
        let signaler = match platform.backend().gic_msi_signaler() {
            Some(signaler) => signaler,
            None => {
                return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                    platform,
                    HvfSnapshotV2MultiBlockPciRestoreStage::PciRoutes,
                    HvfSnapshotV2MultiBlockPciRestoreFailure::PciData(
                        HvfArm64BootPciDataError::new(
                            "restored PCI vector requires a GICv2m MSI signaler",
                        ),
                    ),
                    &mut block_retry_wakeup_scheduler,
                    async_runtime.as_ref(),
                    &mut pci_data_devices,
                    cleanup,
                ));
            }
        };
        let msi_interrupts =
            match HvfGicMsiDeviceInterruptResources::allocate_exact(signaler, &exact_intids) {
                Ok(interrupts) => interrupts,
                Err(source) => {
                    return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                        platform,
                        HvfSnapshotV2MultiBlockPciRestoreStage::PciRoutes,
                        HvfSnapshotV2MultiBlockPciRestoreFailure::PciRoutes(source),
                        &mut block_retry_wakeup_scheduler,
                        async_runtime.as_ref(),
                        &mut pci_data_devices,
                        cleanup,
                    ));
                }
            };
        pci_data_devices = Some(HvfArm64BootPciDataDevices {
            validation,
            dispatcher: Arc::clone(platform.mmio_dispatcher()),
            msi_interrupts: Some(msi_interrupts),
            balloon: None,
            block,
            network,
            pmem,
            vsock: None,
            entropy: None,
            memory_hotplug: None,
            pmem_static_reserved_ranges,
            runtime_hotplug: true,
        });

        let preparation_result = (|| {
            let manager = pci_data_devices.as_mut().ok_or((
                HvfSnapshotV2MultiBlockPciRestoreStage::PciRoutes,
                HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
            ))?;
            for (index, (record, planned)) in
                records.into_iter().zip(pci_plan.records()).enumerate()
            {
                let mut interrupts = manager.shared_msi_registry().map_err(|source| {
                    (
                        HvfSnapshotV2MultiBlockPciRestoreStage::EndpointPreparation { index },
                        HvfSnapshotV2MultiBlockPciRestoreFailure::PciData(source),
                    )
                })?;
                let endpoint = match record
                    .prepare_endpoint(planned.bar_region_id(), interrupts.registry())
                {
                    Ok(endpoint) => endpoint,
                    Err(source) => {
                        release_unpublished_snapshot_v2_multi_block_pci_interrupts(
                            index,
                            &mut interrupts,
                            &mut cleanup,
                        );
                        return Err((
                            HvfSnapshotV2MultiBlockPciRestoreStage::EndpointPreparation { index },
                            HvfSnapshotV2MultiBlockPciRestoreFailure::PciEndpoint(source),
                        ));
                    }
                };
                let metrics_lease = match block_device_metrics
                    .claim_drive_lease(endpoint.drive_id())
                {
                    Ok(metrics_lease) => metrics_lease,
                    Err(source) => {
                        drop(endpoint);
                        release_unpublished_snapshot_v2_multi_block_pci_interrupts(
                            index,
                            &mut interrupts,
                            &mut cleanup,
                        );
                        return Err((
                            HvfSnapshotV2MultiBlockPciRestoreStage::EndpointPreparation { index },
                            HvfSnapshotV2MultiBlockPciRestoreFailure::Metrics(source),
                        ));
                    }
                };
                prepared_publications.push(Some(PreparedHvfSnapshotV2MultiBlockPciPublication {
                    endpoint,
                    interrupts,
                    metrics_lease,
                }));
            }
            Ok(())
        })();
        if let Err((stage, failure)) = preparation_result {
            release_unpublished_snapshot_v2_multi_block_pci_publications(
                &mut prepared_publications,
                &mut cleanup,
            );
            return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                platform,
                stage,
                failure,
                &mut block_retry_wakeup_scheduler,
                async_runtime.as_ref(),
                &mut pci_data_devices,
                cleanup,
            ));
        }

        let block_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let vcpu_control = platform.control();
        block_retry_wakeup_scheduler =
            match HvfArm64BootLimiterRetryWakeupScheduler::start_with_cancellation(
                BLOCK_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
                block_retry_wakeup.clone(),
                move || vcpu_control.request_wakeup(),
            ) {
                Ok(scheduler) => Some(scheduler),
                Err(source) => {
                    release_unpublished_snapshot_v2_multi_block_pci_publications(
                        &mut prepared_publications,
                        &mut cleanup,
                    );
                    return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                        platform,
                        HvfSnapshotV2MultiBlockPciRestoreStage::RetryScheduler,
                        HvfSnapshotV2MultiBlockPciRestoreFailure::RetryScheduler(source.kind()),
                        &mut block_retry_wakeup_scheduler,
                        async_runtime.as_ref(),
                        &mut pci_data_devices,
                        cleanup,
                    ));
                }
            };

        let publication_result = (|| {
            let manager = pci_data_devices.as_mut().ok_or((
                HvfSnapshotV2MultiBlockPciRestoreStage::PciRoutes,
                HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
            ))?;
            for index in 0..record_count {
                let planned = pci_plan.records().get(index).ok_or((
                    HvfSnapshotV2MultiBlockPciRestoreStage::Publication { index },
                    HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
                ))?;
                let prepared = prepared_publications
                    .get(index)
                    .and_then(Option::as_ref)
                    .ok_or((
                        HvfSnapshotV2MultiBlockPciRestoreStage::Publication { index },
                        HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
                    ))?;
                if prepared.endpoint.key() != planned.key() || manager.block.len() != index {
                    return Err((
                        HvfSnapshotV2MultiBlockPciRestoreStage::Publication { index },
                        HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
                    ));
                }
                let prepared = prepared_publications
                    .get_mut(index)
                    .and_then(Option::take)
                    .ok_or((
                        HvfSnapshotV2MultiBlockPciRestoreStage::Publication { index },
                        HvfSnapshotV2MultiBlockPciRestoreFailure::ResourcePlan,
                    ))?;
                let PreparedHvfSnapshotV2MultiBlockPciPublication {
                    endpoint,
                    mut interrupts,
                    metrics_lease,
                } = prepared;
                let (
                    _key,
                    drive_id,
                    is_root_device,
                    _retry,
                    retry_deadline,
                    origin,
                    _async_generation,
                    endpoint,
                ) = endpoint.into_parts();
                let segment = manager.validation.segment().clone();
                let published = {
                    let mut dispatcher = match manager.dispatcher.lock() {
                        Ok(dispatcher) => dispatcher,
                        Err(_) => {
                            drop(endpoint);
                            drop(metrics_lease);
                            release_unpublished_snapshot_v2_multi_block_pci_interrupts(
                                index,
                                &mut interrupts,
                                &mut cleanup,
                            );
                            return Err((
                                HvfSnapshotV2MultiBlockPciRestoreStage::Publication { index },
                                HvfSnapshotV2MultiBlockPciRestoreFailure::DispatcherUnavailable,
                            ));
                        }
                    };
                    endpoint
                        .publish(
                            manager.validation.bar_allocator_mut(),
                            segment,
                            &mut dispatcher,
                            interrupts,
                        )
                        .map_err(|source| {
                            (
                                HvfSnapshotV2MultiBlockPciRestoreStage::Publication { index },
                                HvfSnapshotV2MultiBlockPciRestoreFailure::PciPublication(source),
                            )
                        })?
                };
                manager.block.push(HvfArm64BootPciBlockDevice {
                    drive_id,
                    is_root_device,
                    origin,
                    published,
                    queue_deliveries: 0,
                    retry_deadline,
                    _metrics_lease: Some(metrics_lease),
                });
            }
            Ok(())
        })();
        if let Err((stage, failure)) = publication_result {
            release_unpublished_snapshot_v2_multi_block_pci_publications(
                &mut prepared_publications,
                &mut cleanup,
            );
            return Err(failed_snapshot_v2_multi_block_pci_after_platform(
                platform,
                stage,
                failure,
                &mut block_retry_wakeup_scheduler,
                async_runtime.as_ref(),
                &mut pci_data_devices,
                cleanup,
            ));
        }

        let Some(block_retry_wakeup_scheduler) = block_retry_wakeup_scheduler.take() else {
            std::process::abort();
        };
        block_retry_wakeup_scheduler.schedule_deadline(earliest_retry_deadline);

        let parts = platform.into_parts();
        let machine_config = parts.machine.machine();
        let cpu_template_application = parts.machine.cpu_template().cloned();
        let cache_source = crate::vcpu_config::HvfArm64VcpuCacheFdtSource::new(
            parts.compatibility.identification().id_aa64mmfr2_el1(),
            parts.compatibility.cache_manifest(),
        );
        let gic = parts.compatibility.gic_metadata();
        let serial_interrupt_line = parts
            .serial_device
            .as_ref()
            .map(|device| device.fdt_device.interrupt_line);
        let vmgenid_interrupt_line = parts.vmgenid_device.fdt_device.interrupt_line;
        let vmclock_interrupt_line = parts.vmclock_device.fdt_device.interrupt_line;
        let runtime_resources = Arm64BootRuntimeResources {
            machine_config,
            layout,
            boot_origin: None,
            retained_fdt: Some(retained_fdt),
            rtc_device: Some(parts.rtc_device),
            serial_device: parts.serial_device,
            vmgenid_device: parts.vmgenid_device,
            vmclock_device: parts.vmclock_device,
            pvtime_state: Arm64BootPvTimeState::restored(parts.pvtime_layout),
            block_devices: Vec::new(),
            block_async_runtime: async_runtime.unwrap_or_default(),
            pci_block_devices: Vec::new(),
            pmem_devices: Vec::new(),
            pmem_mmio_devices: Vec::new(),
            network_devices: Vec::new(),
            pci_network_devices: Vec::new(),
            vsock_device: None,
            pci_vsock_device: None,
            balloon_device: None,
            pci_balloon_device: None,
            memory_hotplug_device: None,
            pci_memory_hotplug_device: None,
            entropy_device: None,
            pci_entropy_device: None,
            pci_validation: None,
        };
        let pmem_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let network_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let entropy_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let snapshot_lineage =
            restored_v2_snapshot_lineage(parts.memory_binding, &runtime_resources);
        let session = Self {
            runner: parts.runner,
            backend: parts.backend,
            mmio_dispatcher: parts.mmio_dispatcher,
            runtime_resources,
            restored_snapshot_v2_mmio_registrations: None,
            restored_snapshot_v2_pci_pmem_ranges: None,
            snapshot_lineage,
            restored_snapshot_v2_machine: Some(parts.machine),
            cpu_template_application,
            pci_validation_endpoint: None,
            pci_data_devices,
            cache_source,
            cache_hierarchy: None,
            control_wakeup: HvfArm64BootRunLoopControlWakeupToken::default(),
            run_loop_wakeup: HvfArm64BootRunLoopWakeupToken::default(),
            block_retry_wakeup,
            block_retry_wakeup_scheduler,
            pmem_retry_wakeup,
            pmem_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            network_retry_wakeup,
            network_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_retry_wakeup,
            entropy_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_source: VirtioRngOsEntropySource::new(),
            block_device_metrics,
            pmem_device_metrics: SharedPmemDeviceMetricsRegistry::default(),
            balloon_device_metrics: SharedBalloonDeviceMetrics::default(),
            memory_hotplug_device_metrics: None,
            network_interface_metrics: SharedNetworkInterfaceMetricsRegistry::default(),
            vsock_device_metrics: SharedVsockDeviceMetrics::default(),
            entropy_device_metrics: SharedEntropyDeviceMetrics::default(),
            gic,
            block_interrupt_lines: Vec::new(),
            pmem_interrupt_lines: Vec::new(),
            network_interrupt_lines: Vec::new(),
            vsock_interrupt_line: None,
            balloon_interrupt_line: None,
            entropy_interrupt_line: None,
            memory_hotplug_interrupt_line: None,
            serial_interrupt_line,
            serial_input: None,
            vmgenid_interrupt_line,
            vmclock_interrupt_line,
            boot_registers: None,
        };
        Ok(RestoredHvfSnapshotV2MultiBlockPciOwners {
            session,
            drive_configs,
        })
    }

    /// Construct and completely restore one never-run native-v1 destination.
    pub fn restore_snapshot_v1(
        prepared: PreparedHvfSnapshotV1Load,
        track_dirty_pages: bool,
    ) -> Result<RestoredHvfArm64BootSession, HvfSnapshotV1RestoreError> {
        let (state, memory, installed) = prepared.into_parts();
        let (_machine, compatibility, vcpu_state, interrupt_state, _device_state) =
            state.into_parts();
        let expected_gic = compatibility.gic_metadata();
        let primary_mpidr = compatibility.primary_mpidr();
        let cache_source = crate::vcpu_config::HvfArm64VcpuCacheFdtSource::new(
            compatibility.identification().id_aa64mmfr2_el1(),
            compatibility.cache_manifest(),
        );
        let restore_state = HvfArm64SnapshotV1Restore::new(
            compatibility.identification(),
            compatibility.optional_sve_sme_identification(),
            primary_mpidr,
            vcpu_state,
            interrupt_state,
        );

        let InstalledSnapshotV1RuntimeParts {
            mmio_dispatcher,
            mut runtime_resources,
            drive_config,
            block_retry,
            serial_output,
            serial_output_buffer,
        } = installed;
        runtime_resources.machine_config = runtime_resources
            .machine_config
            .with_track_dirty_pages(track_dirty_pages);
        let block_interrupt_lines = runtime_resources
            .block_devices
            .iter()
            .map(|device| device.fdt_device.interrupt_line)
            .collect::<Vec<_>>();
        let serial_interrupt_line = runtime_resources
            .serial_device
            .as_ref()
            .map(|device| device.fdt_device.interrupt_line);
        let vmgenid_interrupt_line = runtime_resources.vmgenid_device.fdt_device.interrupt_line;
        let vmclock_interrupt_line = runtime_resources.vmclock_device.fdt_device.interrupt_line;
        let block_device_metrics = SharedBlockDeviceMetricsRegistry::from_drive_ids(
            runtime_resources
                .block_devices
                .iter()
                .map(|device| device.registration.drive_id()),
        );

        let mut backend = HvfBackend::new();
        let mut runner: Option<HvfVcpuRunner<'static>> = None;
        let mut block_retry_wakeup_scheduler = None;

        if track_dirty_pages && matches!(&memory, PreparedHvfSnapshotV1RuntimeMemory::Lazy(_)) {
            return Err(failed_snapshot_v1_restore(
                HvfSnapshotV1RestoreStage::EnableDirtyTracking,
                HvfSnapshotV1RestoreFailure::DirtyTracking,
                &mut block_retry_wakeup_scheduler,
                &mut runner,
                &mut backend,
            ));
        }
        if let Err(source) = <HvfBackend as VmBackend>::create_vm(&mut backend) {
            return Err(failed_snapshot_v1_restore(
                HvfSnapshotV1RestoreStage::CreateVm,
                HvfSnapshotV1RestoreFailure::Backend(source),
                &mut block_retry_wakeup_scheduler,
                &mut runner,
                &mut backend,
            ));
        }
        let gic = match backend.create_gic() {
            Ok(gic) => *gic,
            Err(source) => {
                return Err(failed_snapshot_v1_restore(
                    HvfSnapshotV1RestoreStage::CreateGic,
                    HvfSnapshotV1RestoreFailure::Gic(source),
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        };
        if gic != expected_gic {
            return Err(failed_snapshot_v1_restore(
                HvfSnapshotV1RestoreStage::ValidateGic,
                HvfSnapshotV1RestoreFailure::GicMetadataMismatch,
                &mut block_retry_wakeup_scheduler,
                &mut runner,
                &mut backend,
            ));
        }
        let memory_mapping = match memory {
            PreparedHvfSnapshotV1RuntimeMemory::Eager(mut memory) => {
                if track_dirty_pages && memory.enable_dirty_tracking().is_err() {
                    return Err(failed_snapshot_v1_restore(
                        HvfSnapshotV1RestoreStage::EnableDirtyTracking,
                        HvfSnapshotV1RestoreFailure::DirtyTracking,
                        &mut block_retry_wakeup_scheduler,
                        &mut runner,
                        &mut backend,
                    ));
                }
                backend.map_guest_memory(memory, HvfMemoryPermissions::GUEST_RAM)
            }
            PreparedHvfSnapshotV1RuntimeMemory::Lazy(consumer) => backend
                .map_lazy_guest_memory_with_consumer(consumer, HvfMemoryPermissions::GUEST_RAM),
        };
        if memory_mapping.is_err() {
            return Err(failed_snapshot_v1_restore(
                HvfSnapshotV1RestoreStage::MapMemory,
                HvfSnapshotV1RestoreFailure::MemoryMapping,
                &mut block_retry_wakeup_scheduler,
                &mut runner,
                &mut backend,
            ));
        }
        if track_dirty_pages && backend.start_dirty_write_tracking().is_err() {
            return Err(failed_snapshot_v1_restore(
                HvfSnapshotV1RestoreStage::EnableDirtyTracking,
                HvfSnapshotV1RestoreFailure::DirtyTracking,
                &mut block_retry_wakeup_scheduler,
                &mut runner,
                &mut backend,
            ));
        }
        match backend.start_session_vcpu_runner() {
            Ok(created) => runner = Some(created),
            Err(source) => {
                return Err(failed_snapshot_v1_restore(
                    HvfSnapshotV1RestoreStage::StartRunner,
                    HvfSnapshotV1RestoreFailure::Runner(Box::new(source)),
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        }

        let block_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let run_cancel_handle = match runner.as_ref() {
            Some(runner) => runner.run_cancel_handle(),
            None => {
                return Err(failed_snapshot_v1_restore(
                    HvfSnapshotV1RestoreStage::AssembleSession,
                    HvfSnapshotV1RestoreFailure::InvalidRuntime,
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        };
        let created_scheduler = HvfArm64BootLimiterRetryWakeupScheduler::start(
            BLOCK_RETRY_WAKEUP_SCHEDULER_THREAD_NAME,
            run_cancel_handle,
            block_retry_wakeup.clone(),
        );
        match created_scheduler {
            Ok(scheduler) => block_retry_wakeup_scheduler = Some(scheduler),
            Err(source) => {
                return Err(failed_snapshot_v1_restore(
                    HvfSnapshotV1RestoreStage::StartBlockRetryScheduler,
                    HvfSnapshotV1RestoreFailure::Scheduler(source.kind()),
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        }

        let restore_result = match runner.as_ref() {
            Some(runner) => runner.restore_arm64_snapshot_v1_state(restore_state),
            None => {
                return Err(failed_snapshot_v1_restore(
                    HvfSnapshotV1RestoreStage::AssembleSession,
                    HvfSnapshotV1RestoreFailure::InvalidRuntime,
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        };
        if let Err(source) = restore_result {
            return Err(failed_snapshot_v1_restore(
                HvfSnapshotV1RestoreStage::RestoreRunnerState,
                HvfSnapshotV1RestoreFailure::Runner(Box::new(source)),
                &mut block_retry_wakeup_scheduler,
                &mut runner,
                &mut backend,
            ));
        }
        let time_identity_result = match runner.as_ref() {
            Some(runner) => restore_time_identity_for_snapshot(
                runner,
                &mut backend,
                &mut runtime_resources,
                gic,
                vmgenid_interrupt_line,
                vmclock_interrupt_line,
            ),
            None => {
                return Err(failed_snapshot_v1_restore(
                    HvfSnapshotV1RestoreStage::AssembleSession,
                    HvfSnapshotV1RestoreFailure::InvalidRuntime,
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        };
        if let Err(source) = time_identity_result {
            return Err(failed_snapshot_v1_restore(
                HvfSnapshotV1RestoreStage::RestoreTimeIdentity,
                HvfSnapshotV1RestoreFailure::TimeIdentity(Box::new(source)),
                &mut block_retry_wakeup_scheduler,
                &mut runner,
                &mut backend,
            ));
        }

        let retry_after = match block_retry {
            SnapshotV1BlockRetryState::None => None,
            SnapshotV1BlockRetryState::Immediate => Some(Duration::ZERO),
            SnapshotV1BlockRetryState::After { remaining_nanos } => {
                Some(Duration::from_nanos(remaining_nanos))
            }
        };
        match block_retry_wakeup_scheduler.as_ref() {
            Some(scheduler) => scheduler.schedule_after(retry_after),
            None => {
                return Err(failed_snapshot_v1_restore_after_destination_commit(
                    HvfSnapshotV1RestoreStage::AssembleSession,
                    HvfSnapshotV1RestoreFailure::InvalidRuntime,
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        }

        let runner = match runner.take() {
            Some(runner) => runner,
            None => {
                return Err(failed_snapshot_v1_restore_after_destination_commit(
                    HvfSnapshotV1RestoreStage::AssembleSession,
                    HvfSnapshotV1RestoreFailure::InvalidRuntime,
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        };
        let mut block_retry_wakeup_scheduler = match block_retry_wakeup_scheduler.take() {
            Some(scheduler) => scheduler,
            None => {
                let mut runner = Some(runner);
                return Err(failed_snapshot_v1_restore_after_destination_commit(
                    HvfSnapshotV1RestoreStage::AssembleSession,
                    HvfSnapshotV1RestoreFailure::InvalidRuntime,
                    &mut block_retry_wakeup_scheduler,
                    &mut runner,
                    &mut backend,
                ));
            }
        };

        let mmio_dispatcher = Arc::new(Mutex::new(mmio_dispatcher));
        let runner = match HvfArm64BootVcpuSession::from_restored_runner(
            runner,
            primary_mpidr,
            Arc::clone(&mmio_dispatcher),
            gic.timer_interrupts.el1_virtual_timer_intid,
        ) {
            Ok(runner) => runner,
            Err(source) => {
                let scheduler_failed = block_retry_wakeup_scheduler.stop_with_result().is_err();
                let backend_error = <HvfBackend as VmBackend>::destroy_vm(&mut backend).err();
                return Err(HvfSnapshotV1RestoreError::new_after_destination_commit(
                    HvfSnapshotV1RestoreStage::AssembleSession,
                    HvfSnapshotV1RestoreFailure::Coordinator(Box::new(source)),
                    HvfSnapshotV1RestoreCleanup::new(scheduler_failed, None, backend_error),
                ));
            }
        };
        let entropy_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let pmem_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let network_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        let snapshot_lineage = restored_v1_snapshot_lineage(&runtime_resources);
        let session = Self {
            runner,
            backend,
            mmio_dispatcher,
            runtime_resources,
            restored_snapshot_v2_mmio_registrations: None,
            restored_snapshot_v2_pci_pmem_ranges: None,
            snapshot_lineage,
            restored_snapshot_v2_machine: None,
            cpu_template_application: None,
            pci_validation_endpoint: None,
            pci_data_devices: None,
            cache_source,
            cache_hierarchy: None,
            control_wakeup: HvfArm64BootRunLoopControlWakeupToken::default(),
            run_loop_wakeup: HvfArm64BootRunLoopWakeupToken::default(),
            block_retry_wakeup,
            block_retry_wakeup_scheduler,
            pmem_retry_wakeup,
            pmem_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            network_retry_wakeup,
            network_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_retry_wakeup,
            entropy_retry_wakeup_scheduler: HvfArm64BootLimiterRetryWakeupScheduler::inactive(),
            entropy_source: VirtioRngOsEntropySource::new(),
            block_device_metrics,
            pmem_device_metrics: SharedPmemDeviceMetricsRegistry::default(),
            balloon_device_metrics: SharedBalloonDeviceMetrics::default(),
            memory_hotplug_device_metrics: None,
            network_interface_metrics: SharedNetworkInterfaceMetricsRegistry::default(),
            vsock_device_metrics: SharedVsockDeviceMetrics::default(),
            entropy_device_metrics: SharedEntropyDeviceMetrics::default(),
            gic,
            block_interrupt_lines,
            pmem_interrupt_lines: Vec::new(),
            network_interrupt_lines: Vec::new(),
            vsock_interrupt_line: None,
            balloon_interrupt_line: None,
            entropy_interrupt_line: None,
            memory_hotplug_interrupt_line: None,
            serial_interrupt_line,
            serial_input: None,
            vmgenid_interrupt_line,
            vmclock_interrupt_line,
            boot_registers: None,
        };

        Ok(RestoredHvfArm64BootSession {
            session,
            drive_config,
            serial_output,
            serial_output_buffer,
        })
    }

    /// Quiesce block, pmem, network, and entropy limiter retry wakeup publication.
    pub fn quiesce_limiter_retry_wakeups(
        &self,
    ) -> Result<
        HvfArm64BootLimiterRetryWakeupQuiescenceGuard,
        HvfArm64BootLimiterRetryWakeupQuiescenceError,
    > {
        quiesce_limiter_retry_wakeups(
            HvfArm64BootLimiterRetryWakeupOwner::new(
                &self.block_retry_wakeup,
                &self.block_retry_wakeup_scheduler,
            ),
            HvfArm64BootLimiterRetryWakeupOwner::new(
                &self.pmem_retry_wakeup,
                &self.pmem_retry_wakeup_scheduler,
            ),
            HvfArm64BootLimiterRetryWakeupOwner::new(
                &self.network_retry_wakeup,
                &self.network_retry_wakeup_scheduler,
            ),
            HvfArm64BootLimiterRetryWakeupOwner::new(
                &self.entropy_retry_wakeup,
                &self.entropy_retry_wakeup_scheduler,
            ),
        )
    }

