    /// Capture and preflight every non-memory native-v1 component while the
    /// caller retains the supervisor and auxiliary quiescence guards.
    pub fn capture_snapshot_v1_state_at(
        &self,
        drive_config: &DriveConfig,
        serial_config: &SerialConfig,
        guard: &HvfArm64BootLimiterRetryWakeupQuiescenceGuard,
        now: Instant,
    ) -> Result<HvfSnapshotV1State, HvfArm64BootSnapshotV1StateCaptureError> {
        self.capture_snapshot_v1_state_at_with_cancel(
            drive_config,
            serial_config,
            guard,
            now,
            |_| false,
        )
    }

    pub fn capture_snapshot_v1_state_at_with_cancel(
        &self,
        drive_config: &DriveConfig,
        serial_config: &SerialConfig,
        guard: &HvfArm64BootLimiterRetryWakeupQuiescenceGuard,
        now: Instant,
        mut is_cancelled: impl FnMut(HvfArm64BootSnapshotV1CaptureStage) -> bool,
    ) -> Result<HvfSnapshotV1State, HvfArm64BootSnapshotV1StateCaptureError> {
        if self.runner.member_count() != 1 {
            return Err(
                HvfArm64BootSnapshotV1StateCaptureError::UnsupportedVcpuCount {
                    vcpu_count: self.runner.member_count(),
                },
            );
        }
        check_snapshot_v1_capture_cancelled(
            &mut is_cancelled,
            HvfArm64BootSnapshotV1CaptureStage::CacheManifest,
        )?;
        check_snapshot_v1_capture_cancelled(
            &mut is_cancelled,
            HvfArm64BootSnapshotV1CaptureStage::Runner,
        )?;
        let runner_capture = self
            .runner
            .capture_arm64_snapshot_v1_state()
            .map_err(|source| HvfArm64BootSnapshotV1StateCaptureError::Runner { source })?;
        let cache_manifest = retained_snapshot_cache_manifest(
            self.cache_source,
            runner_capture.identification().id_aa64mmfr2_el1(),
        )?;
        check_snapshot_v1_capture_cancelled(
            &mut is_cancelled,
            HvfArm64BootSnapshotV1CaptureStage::Device,
        )?;
        let device = self
            .capture_snapshot_v1_device_state_at(drive_config, serial_config, guard, now)
            .map_err(|source| HvfArm64BootSnapshotV1StateCaptureError::Device { source })?;
        check_snapshot_v1_capture_cancelled(
            &mut is_cancelled,
            HvfArm64BootSnapshotV1CaptureStage::EncodePreflight,
        )?;
        build_snapshot_v1_state(
            &self.runtime_resources,
            self.gic,
            self.primary_mpidr(),
            cache_manifest,
            runner_capture,
            device,
        )
    }

    /// Requests an immediate run-loop retry after a live pmem limiter update
    /// unblocks work that was already pending on a virtqueue.
    pub fn schedule_pmem_retry_wakeup_after_live_update(&mut self, has_pending_work: bool) {
        if has_pending_work {
            self.pmem_retry_wakeup_scheduler
                .schedule_after(Some(Duration::ZERO));
        }
    }

    fn teardown_restored_snapshot_v2_mmio(
        &mut self,
    ) -> Result<(), HvfSnapshotV2StorageMmioRestoreCleanupFailure> {
        let had_balloon = self.runtime_resources.balloon_device.is_some();
        let had_entropy = self.runtime_resources.entropy_device.is_some();
        let had_memory_hotplug = self.runtime_resources.memory_hotplug_device.is_some();
        let had_network = !self.runtime_resources.network_devices.is_empty();
        let had_vsock = self.runtime_resources.vsock_device.is_some();
        let Some(registrations) = self.restored_snapshot_v2_mmio_registrations.as_mut() else {
            return Ok(());
        };

        if !registrations.leases.is_empty() {
            let mut dispatcher = self.mmio_dispatcher.lock().map_err(|_| {
                HvfSnapshotV2StorageMmioRestoreCleanupFailure::DispatcherUnavailable
            })?;
            while let Some(lease) = registrations.leases.last() {
                let index = registrations.leases.len() - 1;
                dispatcher
                    .release_owned_handler(&registrations.owner, lease)
                    .map_err(|source| {
                        HvfSnapshotV2StorageMmioRestoreCleanupFailure::Registration {
                            index,
                            source,
                        }
                    })?;
                registrations.leases.pop();
            }
        }

        while let Some(range) = registrations.pmem_ranges.last().copied() {
            let index = registrations.pmem_ranges.len() - 1;
            self.backend
                .take_runtime_pmem_mapping(range, false)
                .map_err(
                    |source| HvfSnapshotV2StorageMmioRestoreCleanupFailure::Mapping {
                        index,
                        source,
                    },
                )?;
            registrations.pmem_ranges.pop();
        }

        self.runtime_resources.block_devices.clear();
        self.runtime_resources.pmem_mmio_devices.clear();
        self.runtime_resources.pmem_devices.clear();
        self.runtime_resources.network_devices.clear();
        self.network_interrupt_lines.clear();
        self.runtime_resources.vsock_device = None;
        self.vsock_interrupt_line = None;
        self.runtime_resources.balloon_device = None;
        self.balloon_interrupt_line = None;
        self.runtime_resources.entropy_device = None;
        self.entropy_interrupt_line = None;
        self.runtime_resources.memory_hotplug_device = None;
        self.memory_hotplug_interrupt_line = None;
        self.entropy_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        self.network_retry_wakeup = HvfArm64BootLimiterRetryWakeupToken::default();
        self.entropy_source = VirtioRngOsEntropySource::new();
        if had_entropy {
            self.entropy_device_metrics = SharedEntropyDeviceMetrics::default();
        }
        if had_balloon {
            self.balloon_device_metrics = SharedBalloonDeviceMetrics::default();
        }
        if had_memory_hotplug {
            self.memory_hotplug_device_metrics = None;
        }
        if had_network {
            self.network_interface_metrics = SharedNetworkInterfaceMetricsRegistry::default();
        }
        if had_vsock {
            self.vsock_device_metrics = SharedVsockDeviceMetrics::default();
        }
        self.restored_snapshot_v2_mmio_registrations = None;
        Ok(())
    }

    fn teardown_restored_snapshot_v2_pci_pmem(
        &mut self,
    ) -> Result<(), HvfSnapshotV2StoragePciRestoreCleanupFailure> {
        let Some(ranges) = self.restored_snapshot_v2_pci_pmem_ranges.as_mut() else {
            return Ok(());
        };
        while let Some(range) = ranges.last().copied() {
            let index = ranges.len() - 1;
            self.backend
                .take_runtime_pmem_mapping(range, false)
                .map_err(
                    |source| HvfSnapshotV2StoragePciRestoreCleanupFailure::Mapping {
                        index,
                        source,
                    },
                )?;
            ranges.pop();
        }
        self.runtime_resources.pmem_devices.clear();
        self.restored_snapshot_v2_pci_pmem_ranges = None;
        Ok(())
    }

    pub fn shutdown(&mut self) -> Result<(), HvfArm64BootSessionShutdownError> {
        self.block_retry_wakeup_scheduler.stop();
        self.pmem_retry_wakeup_scheduler.stop();
        self.network_retry_wakeup_scheduler.stop();
        self.entropy_retry_wakeup_scheduler.stop();
        let runner_result = self.runner.shutdown();
        let had_restored_snapshot_v2_mmio = self.restored_snapshot_v2_mmio_registrations.is_some();
        let had_restored_snapshot_v2_pci_pmem = self.restored_snapshot_v2_pci_pmem_ranges.is_some();
        let restored_snapshot_v2_mmio_result = if runner_result.is_ok() {
            self.teardown_restored_snapshot_v2_mmio()
        } else {
            Ok(())
        };
        let block_async_result =
            if runner_result.is_ok() && restored_snapshot_v2_mmio_result.is_ok() {
                shutdown_block_async_before_guest_memory_teardown(
                    &mut self.backend,
                    &self.runtime_resources,
                )
            } else {
                Ok(())
            };
        if had_restored_snapshot_v2_mmio
            && restored_snapshot_v2_mmio_result.is_ok()
            && block_async_result.is_ok()
        {
            self.block_device_metrics = SharedBlockDeviceMetricsRegistry::default();
            self.pmem_device_metrics = SharedPmemDeviceMetricsRegistry::default();
        }
        let pci_data_result = self.teardown_pci_data_devices();
        let restored_snapshot_v2_pci_pmem_result = if runner_result.is_ok()
            && restored_snapshot_v2_mmio_result.is_ok()
            && block_async_result.is_ok()
            && pci_data_result.is_ok()
        {
            self.teardown_restored_snapshot_v2_pci_pmem()
        } else {
            Ok(())
        };
        if had_restored_snapshot_v2_pci_pmem
            && block_async_result.is_ok()
            && pci_data_result.is_ok()
            && restored_snapshot_v2_pci_pmem_result.is_ok()
        {
            self.block_device_metrics = SharedBlockDeviceMetricsRegistry::default();
            self.pmem_device_metrics = SharedPmemDeviceMetricsRegistry::default();
        }
        let pci_result = self.teardown_pci_validation_endpoint();
        let result = if let Err(source) = runner_result {
            Err(HvfArm64BootSessionShutdownError::Vcpu { source })
        } else if let Err(source) = restored_snapshot_v2_mmio_result {
            Err(HvfArm64BootSessionShutdownError::RestoredSnapshotV2Mmio { source })
        } else if let Err(source) = block_async_result {
            Err(source)
        } else if let Err(source) = pci_data_result {
            Err(HvfArm64BootSessionShutdownError::PciData { source })
        } else if let Err(source) = restored_snapshot_v2_pci_pmem_result {
            Err(HvfArm64BootSessionShutdownError::RestoredSnapshotV2PciPmem { source })
        } else if let Err(source) = pci_result {
            Err(HvfArm64BootSessionShutdownError::PciValidation { source })
        } else {
            <HvfBackend as VmBackend>::destroy_vm(&mut self.backend)
                .map_err(|source| HvfArm64BootSessionShutdownError::DestroyVm { source })
        };
        record_memory_hotplug_teardown_metrics(
            &mut self.memory_hotplug_device_metrics,
            result.is_ok(),
        );
        result
    }

    /// Explicit cleanup evidence for an uncommitted restored destination.
    pub fn teardown_snapshot_v1(&mut self) -> HvfSnapshotV1RestoreCleanup {
        let scheduler_failed = self
            .block_retry_wakeup_scheduler
            .stop_with_result()
            .is_err()
            | self.pmem_retry_wakeup_scheduler.stop_with_result().is_err()
            | self
                .network_retry_wakeup_scheduler
                .stop_with_result()
                .is_err()
            | self
                .entropy_retry_wakeup_scheduler
                .stop_with_result()
                .is_err();
        let coordinator = self.runner.shutdown().err();
        let backend = <HvfBackend as VmBackend>::destroy_vm(&mut self.backend).err();
        HvfSnapshotV1RestoreCleanup::with_coordinator(scheduler_failed, coordinator, backend)
    }

