fn run_boot_session_loop_with_observer(
    session: &mut impl BootSessionRunLoopSession,
    stop_token: &HvfArm64BootRunLoopStopToken,
    max_steps: NonZeroUsize,
    mut observe_step: impl FnMut(&HvfVcpuRunStepOutcome),
) -> Result<HvfArm64BootRunLoopOutcome, HvfArm64BootRunLoopError> {
    let mut virtual_timer_activated = false;
    let mut terminal_step_outcome = None;
    let result =
        run_boot_session_loop_with_observer_inner(session, stop_token, max_steps, |outcome| {
            match backend_outcome_for_run_step_outcome(outcome) {
                Some(LoggerBackendOutcome::VirtualTimerActivated) => {
                    virtual_timer_activated = true;
                }
                Some(outcome) => terminal_step_outcome = Some(outcome),
                None => {}
            }
            observe_step(outcome);
        });
    let error_outcome = result
        .as_ref()
        .err()
        .and_then(backend_outcome_for_run_loop_error);
    let time_identity_error_outcome = result
        .as_ref()
        .err()
        .and_then(time_identity_outcome_for_run_loop_error);
    if virtual_timer_activated
        || terminal_step_outcome.is_some()
        || error_outcome.is_some()
        || time_identity_error_outcome.is_some()
    {
        let guest_logger = session.guest_logger();
        if virtual_timer_activated {
            guest_logger.log_backend(LoggerBackendOutcome::VirtualTimerActivated);
        }
        if let Some(outcome) = terminal_step_outcome {
            guest_logger.log_backend(outcome);
        }
        if let Some(outcome) = error_outcome {
            guest_logger.log_backend(outcome);
        }
        if let Some(outcome) = time_identity_error_outcome {
            guest_logger.log_time_identity(outcome);
        }
    }
    if !matches!(
        &result,
        Ok(HvfArm64BootRunLoopOutcome::StepLimitReached { .. })
            | Ok(HvfArm64BootRunLoopOutcome::Wakeup { .. })
    ) {
        session.cancel_run_loop_pmem_retry_wakeup();
        session.cancel_run_loop_network_retry_wakeup();
    }

    result
}

pub(crate) fn backend_outcome_for_run_step_outcome(
    outcome: &HvfVcpuRunStepOutcome,
) -> Option<LoggerBackendOutcome> {
    match outcome {
        HvfVcpuRunStepOutcome::GuestShutdown { .. } => {
            Some(LoggerBackendOutcome::VcpuExitGuestShutdown)
        }
        HvfVcpuRunStepOutcome::GuestReset { .. } => Some(LoggerBackendOutcome::VcpuExitGuestReset),
        HvfVcpuRunStepOutcome::Unknown { .. } => Some(LoggerBackendOutcome::VcpuExitUnsupported),
        HvfVcpuRunStepOutcome::VtimerActivated => Some(LoggerBackendOutcome::VirtualTimerActivated),
        HvfVcpuRunStepOutcome::Canceled
        | HvfVcpuRunStepOutcome::Hvc { .. }
        | HvfVcpuRunStepOutcome::CpuOff { .. }
        | HvfVcpuRunStepOutcome::CpuSuspend { .. }
        | HvfVcpuRunStepOutcome::Sys64 { .. }
        | HvfVcpuRunStepOutcome::Mmio { .. }
        | HvfVcpuRunStepOutcome::DirtyWrite { .. }
        | HvfVcpuRunStepOutcome::LazyPage { .. } => None,
    }
}

pub(crate) fn backend_outcome_for_run_step_error(
    error: &HvfArm64BootVcpuError,
) -> Option<LoggerBackendOutcome> {
    match error {
        HvfArm64BootVcpuError::Member { source, .. }
            if matches!(
                source.as_ref(),
                HvfVcpuRunnerError::MmioDispatch(
                    crate::mmio::HvfMmioDispatchError::Dispatch { .. }
                )
            ) =>
        {
            // The attached runtime dispatcher owns this exact failure. Keep
            // the HVF layer silent so one transition produces one record.
            None
        }
        HvfArm64BootVcpuError::Member { source, .. }
            if matches!(source.as_ref(), HvfVcpuRunnerError::MmioDispatch(_)) =>
        {
            Some(LoggerBackendOutcome::MmioDispatchFailed)
        }
        HvfArm64BootVcpuError::Member { source, .. }
            if matches!(source.as_ref(), HvfVcpuRunnerError::Gic(_)) =>
        {
            Some(LoggerBackendOutcome::InterruptDeliveryFailed)
        }
        HvfArm64BootVcpuError::GuestMemory { .. }
        | HvfArm64BootVcpuError::Member { .. }
        | HvfArm64BootVcpuError::Power { .. }
        | HvfArm64BootVcpuError::Coordinator { .. } => Some(LoggerBackendOutcome::VcpuRunFailed),
    }
}

fn backend_outcome_for_run_loop_error(
    error: &HvfArm64BootRunLoopError,
) -> Option<LoggerBackendOutcome> {
    match error {
        HvfArm64BootRunLoopError::HandleVirtualTimer { .. } => {
            Some(LoggerBackendOutcome::VirtualTimerFailed)
        }
        HvfArm64BootRunLoopError::RunStep { source, .. } => {
            backend_outcome_for_run_step_error(source)
        }
        HvfArm64BootRunLoopError::StartWakeupMonitor { .. }
        | HvfArm64BootRunLoopError::StopWakeupMonitor { .. }
        | HvfArm64BootRunLoopError::DispatchSerialInput { .. }
        | HvfArm64BootRunLoopError::DispatchBlockNotifications { .. }
        | HvfArm64BootRunLoopError::DispatchPmemNotifications { .. }
        | HvfArm64BootRunLoopError::DispatchNetworkNotifications { .. }
        | HvfArm64BootRunLoopError::DispatchVsockNotifications { .. }
        | HvfArm64BootRunLoopError::DispatchBalloonNotifications { .. }
        | HvfArm64BootRunLoopError::DispatchMemoryHotplugNotifications { .. }
        | HvfArm64BootRunLoopError::DispatchEntropyNotifications { .. } => {
            Some(LoggerBackendOutcome::VcpuRunFailed)
        }
    }
}

fn time_identity_outcome_for_run_loop_error(
    error: &HvfArm64BootRunLoopError,
) -> Option<LoggerTimeIdentityOutcome> {
    let HvfArm64BootRunLoopError::RunStep { source, .. } = error else {
        return None;
    };
    let HvfArm64BootVcpuError::Member { source, .. } = source.as_ref() else {
        return None;
    };
    matches!(
        source.as_ref(),
        HvfVcpuRunnerError::PvTimeMeasurement(_)
            | HvfVcpuRunnerError::PvTimeSampling { .. }
            | HvfVcpuRunnerError::PvTimeAccounting { .. }
    )
    .then_some(LoggerTimeIdentityOutcome::PvTimeAccountingFailed)
}

fn run_boot_session_loop_with_observer_inner(
    session: &mut impl BootSessionRunLoopSession,
    stop_token: &HvfArm64BootRunLoopStopToken,
    max_steps: NonZeroUsize,
    mut observe_step: impl FnMut(&HvfVcpuRunStepOutcome),
) -> Result<HvfArm64BootRunLoopOutcome, HvfArm64BootRunLoopError> {
    let max_steps = max_steps.get();
    let mut steps = 0usize;

    loop {
        if stop_token.is_stop_requested() {
            return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
        }
        let _ = dispatch_run_loop_pmem_retry_notifications_for_step(session, steps)?;
        if stop_token.is_stop_requested() {
            return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
        }
        let _ = dispatch_run_loop_network_retry_notifications_for_step(session, steps)?;
        if stop_token.is_stop_requested() {
            return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
        }
        if session.take_run_loop_network_packet_readiness() {
            dispatch_run_loop_network_notifications_for_step(session, steps)?;
            if stop_token.is_stop_requested() {
                return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
            }
        }

        let monitor = session.start_run_loop_wakeup_monitor().map_err(|source| {
            HvfArm64BootRunLoopError::StartWakeupMonitor {
                steps_completed: steps,
                source: Box::new(source),
            }
        })?;
        let monitor_has_block_wakeup_fds = monitor.has_block_wakeup_fds();
        let monitor_has_serial_input_fd = monitor.has_serial_input_fd();
        let outcome_result = session.run_loop_vcpu_step();
        let finish_result = monitor.finish();
        let monitor_observation = match &outcome_result {
            Ok(_) => {
                finish_result.map_err(|source| HvfArm64BootRunLoopError::StopWakeupMonitor {
                    steps_completed: steps.saturating_add(1),
                    source: Box::new(source),
                })?
            }
            Err(_) => {
                finish_result.map_err(|source| HvfArm64BootRunLoopError::StopWakeupMonitor {
                    steps_completed: steps,
                    source: Box::new(source),
                })?
            }
        };
        let outcome = outcome_result.map_err(|source| HvfArm64BootRunLoopError::RunStep {
            steps_completed: steps,
            source: Box::new(source),
        })?;
        observe_step(&outcome);
        steps += 1;
        session.observe_run_loop_vsock_readiness(&monitor_observation.vsock);
        let monitor_wakeup_requested = monitor_observation.wakeup_requested;

        match outcome {
            HvfVcpuRunStepOutcome::Canceled => {
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let control_wakeup_requested = session.take_run_loop_control_wakeup_request();
                let wakeup_requested =
                    session.take_run_loop_wakeup_request() || monitor_wakeup_requested;
                let block_retry_wakeup_requested =
                    session.take_run_loop_block_retry_wakeup_request();
                let pmem_retry_wakeup_requested = session.take_run_loop_pmem_retry_wakeup_request();
                let network_retry_wakeup_requested =
                    session.take_run_loop_network_retry_wakeup_request();
                let entropy_retry_wakeup_requested =
                    session.take_run_loop_entropy_retry_wakeup_request();
                if !control_wakeup_requested {
                    dispatch_run_loop_serial_input_for_step(
                        session,
                        steps,
                        monitor_wakeup_requested && monitor_has_serial_input_fd,
                    )?;
                    if stop_token.is_stop_requested() {
                        return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                    }
                }
                if block_retry_wakeup_requested {
                    dispatch_run_loop_block_notifications_for_step(session, steps)?;
                    if stop_token.is_stop_requested() {
                        return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                    }
                }
                if pmem_retry_wakeup_requested {
                    dispatch_run_loop_pmem_notifications_for_step(session, steps)?;
                    if stop_token.is_stop_requested() {
                        return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                    }
                }
                if network_retry_wakeup_requested {
                    dispatch_run_loop_network_notifications_for_step(session, steps)?;
                    if stop_token.is_stop_requested() {
                        return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                    }
                }
                if entropy_retry_wakeup_requested {
                    dispatch_run_loop_entropy_notifications_for_step(session, steps)?;
                    if stop_token.is_stop_requested() {
                        return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                    }
                }
                if monitor_wakeup_requested
                    && monitor_has_block_wakeup_fds
                    && !block_retry_wakeup_requested
                {
                    dispatch_run_loop_block_notifications_for_step(session, steps)?;
                    if stop_token.is_stop_requested() {
                        return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                    }
                }
                if wakeup_requested {
                    dispatch_run_loop_vsock_notifications_for_step(session, steps)?;
                    if stop_token.is_stop_requested() {
                        return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                    }
                }
                if control_wakeup_requested {
                    return Ok(HvfArm64BootRunLoopOutcome::Wakeup { steps });
                }
                if wakeup_requested
                    || block_retry_wakeup_requested
                    || pmem_retry_wakeup_requested
                    || network_retry_wakeup_requested
                    || entropy_retry_wakeup_requested
                {
                    if steps == max_steps {
                        return Ok(HvfArm64BootRunLoopOutcome::StepLimitReached { steps });
                    }
                    continue;
                }
                if steps == max_steps {
                    return Ok(HvfArm64BootRunLoopOutcome::StepLimitReached { steps });
                }
                continue;
            }
            HvfVcpuRunStepOutcome::VtimerActivated => {
                session.handle_run_loop_virtual_timer().map_err(|source| {
                    HvfArm64BootRunLoopError::HandleVirtualTimer {
                        steps_completed: steps,
                        source: Box::new(source),
                    }
                })?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let _ = dispatch_run_loop_block_retry_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let _ = dispatch_run_loop_pmem_retry_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let _ = dispatch_run_loop_network_retry_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let _ = dispatch_run_loop_entropy_retry_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                dispatch_run_loop_vsock_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                if steps == max_steps {
                    return Ok(HvfArm64BootRunLoopOutcome::StepLimitReached { steps });
                }
            }
            HvfVcpuRunStepOutcome::Unknown { reason } => {
                return Ok(HvfArm64BootRunLoopOutcome::Unknown { steps, reason });
            }
            HvfVcpuRunStepOutcome::GuestShutdown { .. } => {
                return Ok(HvfArm64BootRunLoopOutcome::GuestShutdown { steps });
            }
            HvfVcpuRunStepOutcome::GuestReset { .. } => {
                return Ok(HvfArm64BootRunLoopOutcome::GuestReset { steps });
            }
            HvfVcpuRunStepOutcome::Hvc { .. }
            | HvfVcpuRunStepOutcome::CpuOff { .. }
            | HvfVcpuRunStepOutcome::CpuSuspend { .. }
            | HvfVcpuRunStepOutcome::Sys64 { .. }
            | HvfVcpuRunStepOutcome::LazyPage { .. }
            | HvfVcpuRunStepOutcome::DirtyWrite { .. } => {
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let _ = dispatch_run_loop_block_retry_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let _ = dispatch_run_loop_pmem_retry_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let _ = dispatch_run_loop_network_retry_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                let _ = dispatch_run_loop_entropy_retry_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                dispatch_run_loop_vsock_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                if steps == max_steps {
                    return Ok(HvfArm64BootRunLoopOutcome::StepLimitReached { steps });
                }
            }
            HvfVcpuRunStepOutcome::Mmio { .. } => {
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                dispatch_run_loop_serial_input_for_step(session, steps, false)?;
                let _ = session.take_run_loop_block_retry_wakeup_request();
                let _ = session.take_run_loop_pmem_retry_wakeup_request();
                let _ = session.take_run_loop_network_retry_wakeup_request();
                let _ = session.take_run_loop_entropy_retry_wakeup_request();
                dispatch_run_loop_block_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                dispatch_run_loop_pmem_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                dispatch_run_loop_network_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                dispatch_run_loop_vsock_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                session
                    .dispatch_run_loop_balloon_notifications()
                    .map_err(
                        |source| HvfArm64BootRunLoopError::DispatchBalloonNotifications {
                            steps_completed: steps,
                            source: Box::new(source),
                        },
                    )?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                session
                    .dispatch_run_loop_memory_hotplug_notifications()
                    .map_err(|source| {
                        HvfArm64BootRunLoopError::DispatchMemoryHotplugNotifications {
                            steps_completed: steps,
                            source: Box::new(source),
                        }
                    })?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                dispatch_run_loop_entropy_notifications_for_step(session, steps)?;
                if stop_token.is_stop_requested() {
                    return Ok(HvfArm64BootRunLoopOutcome::Stopped { steps });
                }
                if steps == max_steps {
                    return Ok(HvfArm64BootRunLoopOutcome::StepLimitReached { steps });
                }
            }
        }
    }
}

#[derive(Debug, Default)]
struct HvfArm64BootVsockReadinessObservation {
    events: Vec<VsockHostReadiness>,
    poll_failed: bool,
}

impl HvfArm64BootVsockReadinessObservation {
    fn is_empty(&self) -> bool {
        self.events.is_empty() && !self.poll_failed
    }
}

#[derive(Debug, Default)]
struct HvfArm64BootRunLoopWakeupObservation {
    wakeup_requested: bool,
    vsock: HvfArm64BootVsockReadinessObservation,
}

struct HvfArm64BootRunLoopWakeupMonitor {
    stop_writer: Option<UnixStream>,
    thread: Option<JoinHandle<HvfArm64BootRunLoopWakeupObservation>>,
    completed_wakeup: bool,
    has_block_wakeup_fds: bool,
    has_serial_input_fd: bool,
}

struct HvfArm64BootRunLoopWakeupInputs {
    host_read_fds: Vec<RawFd>,
    host_write_fds: Vec<RawFd>,
    vsock_read_fds: Vec<RawFd>,
    vsock_write_fds: Vec<RawFd>,
    deadline: Option<Instant>,
    has_block_wakeup_fds: bool,
    has_serial_input_fd: bool,
}

impl HvfArm64BootRunLoopWakeupMonitor {
    const fn inactive() -> Self {
        Self {
            stop_writer: None,
            thread: None,
            completed_wakeup: false,
            has_block_wakeup_fds: false,
            has_serial_input_fd: false,
        }
    }

    #[cfg(test)]
    const fn completed_for_test(completed_wakeup: bool) -> Self {
        Self {
            stop_writer: None,
            thread: None,
            completed_wakeup,
            has_block_wakeup_fds: false,
            has_serial_input_fd: false,
        }
    }

    #[cfg(test)]
    const fn completed_block_for_test(completed_wakeup: bool) -> Self {
        Self {
            stop_writer: None,
            thread: None,
            completed_wakeup,
            has_block_wakeup_fds: true,
            has_serial_input_fd: false,
        }
    }

    #[cfg(test)]
    const fn completed_serial_for_test(completed_wakeup: bool) -> Self {
        Self {
            stop_writer: None,
            thread: None,
            completed_wakeup,
            has_block_wakeup_fds: false,
            has_serial_input_fd: true,
        }
    }

    fn start(
        inputs: HvfArm64BootRunLoopWakeupInputs,
        vcpu_control: HvfVcpuRunControl,
        wakeup_token: HvfArm64BootRunLoopWakeupToken,
    ) -> Result<Self, HvfArm64BootRunLoopWakeupMonitorError> {
        let HvfArm64BootRunLoopWakeupInputs {
            host_read_fds,
            host_write_fds,
            mut vsock_read_fds,
            mut vsock_write_fds,
            deadline,
            has_block_wakeup_fds,
            has_serial_input_fd,
        } = inputs;
        if host_read_fds.is_empty() && host_write_fds.is_empty() && deadline.is_none() {
            return Ok(Self::inactive());
        }

        let (stop_reader, stop_writer) =
            UnixStream::pair().map_err(|source| Self::create_stop_pipe_error(source.kind()))?;
        vsock_read_fds.sort_unstable();
        vsock_read_fds.dedup();
        vsock_write_fds.sort_unstable();
        vsock_write_fds.dedup();
        let mut vsock_fds = vsock_read_fds;
        vsock_fds
            .try_reserve_exact(vsock_write_fds.len())
            .map_err(|source| HvfArm64BootRunLoopWakeupMonitorError::PollFdAllocation { source })?;
        vsock_fds.extend(vsock_write_fds);
        vsock_fds.sort_unstable();
        vsock_fds.dedup();
        let mut pollfds =
            run_loop_wakeup_pollfds(host_read_fds, host_write_fds, stop_reader.as_raw_fd())?;
        let pollfd_count = libc::nfds_t::try_from(pollfds.len()).map_err(|_| {
            HvfArm64BootRunLoopWakeupMonitorError::TooManyPollFds {
                count: pollfds.len(),
            }
        })?;
        let thread = thread::Builder::new()
            .name(RUN_LOOP_WAKEUP_MONITOR_THREAD_NAME.to_owned())
            .spawn(move || {
                run_loop_wakeup_monitor(
                    &mut pollfds,
                    pollfd_count,
                    stop_reader,
                    deadline,
                    &vsock_fds,
                    vcpu_control,
                    wakeup_token,
                )
            })
            .map_err(|source| HvfArm64BootRunLoopWakeupMonitorError::ThreadSpawn { source })?;

        Ok(Self {
            stop_writer: Some(stop_writer),
            thread: Some(thread),
            completed_wakeup: false,
            has_block_wakeup_fds,
            has_serial_input_fd,
        })
    }

    const fn has_block_wakeup_fds(&self) -> bool {
        self.has_block_wakeup_fds
    }

    const fn has_serial_input_fd(&self) -> bool {
        self.has_serial_input_fd
    }

    fn finish(
        mut self,
    ) -> Result<HvfArm64BootRunLoopWakeupObservation, HvfArm64BootRunLoopWakeupMonitorError> {
        let mut stop_signal_error = None;
        if let Some(mut stop_writer) = self.stop_writer.take() {
            match stop_writer.write_all(&RUN_LOOP_WAKEUP_MONITOR_STOP_BYTE) {
                Ok(()) => {}
                Err(source)
                    if matches!(
                        source.kind(),
                        io::ErrorKind::BrokenPipe | io::ErrorKind::NotConnected
                    ) => {}
                Err(source) => {
                    stop_signal_error = Some(source.kind());
                }
            }
        }

        let observation = if let Some(thread) = self.thread.take() {
            thread
                .join()
                .map_err(|_| HvfArm64BootRunLoopWakeupMonitorError::ThreadPanicked)?
        } else {
            HvfArm64BootRunLoopWakeupObservation {
                wakeup_requested: self.completed_wakeup,
                vsock: HvfArm64BootVsockReadinessObservation::default(),
            }
        };

        if let Some(source) = stop_signal_error {
            return Err(HvfArm64BootRunLoopWakeupMonitorError::StopSignal { source });
        }

        Ok(observation)
    }

    const fn create_stop_pipe_error(
        source: io::ErrorKind,
    ) -> HvfArm64BootRunLoopWakeupMonitorError {
        HvfArm64BootRunLoopWakeupMonitorError::CreateStopPipe { source }
    }
}

fn run_loop_wakeup_pollfds(
    mut host_read_fds: Vec<RawFd>,
    mut host_write_fds: Vec<RawFd>,
    stop_fd: RawFd,
) -> Result<Vec<libc::pollfd>, HvfArm64BootRunLoopWakeupMonitorError> {
    host_read_fds.sort_unstable();
    host_read_fds.dedup();
    host_write_fds.sort_unstable();
    host_write_fds.dedup();
    let mut pollfds = Vec::new();
    pollfds
        .try_reserve_exact(
            host_read_fds
                .len()
                .saturating_add(host_write_fds.len())
                .saturating_add(1),
        )
        .map_err(|source| HvfArm64BootRunLoopWakeupMonitorError::PollFdAllocation { source })?;
    pollfds.push(libc::pollfd {
        fd: stop_fd,
        events: libc::POLLIN,
        revents: 0,
    });
    let mut read_index = 0;
    let mut write_index = 0;
    while read_index < host_read_fds.len() || write_index < host_write_fds.len() {
        let read_fd = host_read_fds.get(read_index).copied();
        let write_fd = host_write_fds.get(write_index).copied();
        let (fd, events) = match (read_fd, write_fd) {
            (Some(read_fd), Some(write_fd)) if read_fd == write_fd => {
                read_index += 1;
                write_index += 1;
                (read_fd, libc::POLLIN | libc::POLLOUT)
            }
            (Some(read_fd), Some(write_fd)) if read_fd < write_fd => {
                read_index += 1;
                (read_fd, libc::POLLIN)
            }
            (Some(_), Some(write_fd)) => {
                write_index += 1;
                (write_fd, libc::POLLOUT)
            }
            (Some(read_fd), None) => {
                read_index += 1;
                (read_fd, libc::POLLIN)
            }
            (None, Some(write_fd)) => {
                write_index += 1;
                (write_fd, libc::POLLOUT)
            }
            (None, None) => break,
        };
        pollfds.push(libc::pollfd {
            fd,
            events,
            revents: 0,
        });
    }

    Ok(pollfds)
}

fn run_loop_wakeup_monitor(
    pollfds: &mut [libc::pollfd],
    pollfd_count: libc::nfds_t,
    _stop_reader: UnixStream,
    deadline: Option<Instant>,
    vsock_fds: &[RawFd],
    vcpu_control: HvfVcpuRunControl,
    wakeup_token: HvfArm64BootRunLoopWakeupToken,
) -> HvfArm64BootRunLoopWakeupObservation {
    run_loop_wakeup_monitor_with(
        pollfds,
        pollfd_count,
        deadline,
        vsock_fds,
        Instant::now,
        |pollfds, pollfd_count, timeout| {
            // SAFETY: `pollfds` is a valid mutable slice for `pollfd_count`
            // entries and remains alive for the duration of this `poll` call.
            let result = unsafe { libc::poll(pollfds.as_mut_ptr(), pollfd_count, timeout) };
            if result < 0 {
                Err(io::Error::last_os_error().kind())
            } else {
                Ok(result)
            }
        },
        || {
            if vcpu_control.request_wakeup().is_ok() {
                wakeup_token.request_wakeup();
            }
        },
    )
}

fn run_loop_wakeup_monitor_with(
    pollfds: &mut [libc::pollfd],
    pollfd_count: libc::nfds_t,
    deadline: Option<Instant>,
    vsock_fds: &[RawFd],
    mut now: impl FnMut() -> Instant,
    mut poll: impl FnMut(
        &mut [libc::pollfd],
        libc::nfds_t,
        libc::c_int,
    ) -> Result<libc::c_int, io::ErrorKind>,
    mut request_wakeup: impl FnMut(),
) -> HvfArm64BootRunLoopWakeupObservation {
    loop {
        for pollfd in pollfds.iter_mut() {
            pollfd.revents = 0;
        }

        let timeout = vsock_wakeup_poll_timeout(deadline, now());
        let poll_result = match poll(pollfds, pollfd_count, timeout) {
            Ok(result) => result,
            Err(io::ErrorKind::Interrupted) => continue,
            Err(_) => {
                request_wakeup();
                return HvfArm64BootRunLoopWakeupObservation {
                    wakeup_requested: true,
                    vsock: HvfArm64BootVsockReadinessObservation {
                        events: Vec::new(),
                        poll_failed: !vsock_fds.is_empty(),
                    },
                };
            }
        };

        let Some(stop_pollfd) = pollfds.first() else {
            return HvfArm64BootRunLoopWakeupObservation::default();
        };
        if pollfd_has_wakeup_event(stop_pollfd.revents) {
            return HvfArm64BootRunLoopWakeupObservation::default();
        }
        let fd_wakeup = pollfds
            .iter()
            .skip(1)
            .any(|pollfd| pollfd_has_wakeup_event(pollfd.revents));
        if fd_wakeup || (poll_result == 0 && deadline.is_some()) {
            request_wakeup();
            let events = pollfds
                .iter()
                .skip(1)
                .filter(|pollfd| {
                    pollfd_has_wakeup_event(pollfd.revents)
                        && vsock_fds.binary_search(&pollfd.fd).is_ok()
                })
                .map(|pollfd| VsockHostReadiness::from_poll_revents(pollfd.fd, pollfd.revents))
                .collect();
            return HvfArm64BootRunLoopWakeupObservation {
                wakeup_requested: true,
                vsock: HvfArm64BootVsockReadinessObservation {
                    events,
                    poll_failed: false,
                },
            };
        }
    }
}

fn vsock_wakeup_poll_timeout(deadline: Option<Instant>, now: Instant) -> libc::c_int {
    let Some(deadline) = deadline else {
        return POLL_FOREVER;
    };
    let Some(remaining) = deadline.checked_duration_since(now) else {
        return 0;
    };
    if remaining.is_zero() {
        return 0;
    }

    let whole_millis = remaining.as_millis();
    let rounded_millis =
        whole_millis.saturating_add(u128::from(remaining.subsec_nanos() % 1_000_000 != 0));
    rounded_millis
        .min(libc::c_int::MAX as u128)
        .try_into()
        .unwrap_or(libc::c_int::MAX)
}

const fn pollfd_has_wakeup_event(revents: libc::c_short) -> bool {
    revents & (libc::POLLIN | libc::POLLOUT | libc::POLLHUP | libc::POLLERR | libc::POLLNVAL) != 0
}

fn lock_boot_mmio_dispatcher(
    dispatcher: &Arc<Mutex<MmioDispatcher>>,
) -> Result<MutexGuard<'_, MmioDispatcher>, HvfArm64BootMmioDispatcherError> {
    dispatcher.try_lock().map_err(|source| match source {
        TryLockError::WouldBlock => HvfArm64BootMmioDispatcherError::Busy,
        TryLockError::Poisoned(_) => HvfArm64BootMmioDispatcherError::Poisoned,
    })
}

fn lock_boot_mmio_dispatcher_runtime(
    dispatcher: &Arc<Mutex<MmioDispatcher>>,
) -> Result<MutexGuard<'_, MmioDispatcher>, HvfArm64BootMmioDispatcherError> {
    dispatcher
        .lock()
        .map_err(|_| HvfArm64BootMmioDispatcherError::Poisoned)
}

