fn replace_vmgenid_for_snapshot_restore(
    runner: &HvfVcpuRunner<'_>,
    backend: &mut HvfBackend,
    runtime_resources: &mut Arm64BootRuntimeResources,
    gic: HvfGicMetadata,
    interrupt_line: GuestInterruptLine,
) -> Result<(), HvfArm64BootVmGenIdRestoreError> {
    let guest_logger = backend.guest_logger();
    let result = (|| {
        runner
            .ensure_snapshot_restore_available()
            .map_err(|source| HvfArm64BootVmGenIdRestoreError::RunnerPreflight { source })?;

        let signaler = HvfGicSpiSignaler::from_metadata(&gic)
            .map_err(|source| HvfArm64BootVmGenIdRestoreError::SignalerPreflight { source })?;
        signaler
            .validate_line(interrupt_line)
            .map_err(|source| HvfArm64BootVmGenIdRestoreError::SignalerPreflight { source })?;

        let memory = backend
            .mapped_guest_memory_mut()
            .map_err(|source| HvfArm64BootVmGenIdRestoreError::GuestMemory { source })?;
        replace_vmgenid_and_signal_with(
            memory,
            &mut runtime_resources.vmgenid_device,
            replace_arm64_boot_vmgenid,
            || signaler.set_level(interrupt_line, true),
        )
    })();
    observe_vmgenid_restore(&guest_logger, &result);
    result
}

pub(crate) fn replace_vmgenid_and_signal_with(
    memory: &mut GuestMemory,
    device: &mut Arm64BootVmGenIdDevice,
    replace: impl FnOnce(
        &mut GuestMemory,
        &mut Arm64BootVmGenIdDevice,
    ) -> Result<(), Arm64BootVmGenIdReplacementError>,
    signal: impl FnOnce() -> Result<(), HvfGicSpiSignalError>,
) -> Result<(), HvfArm64BootVmGenIdRestoreError> {
    replace(memory, device)
        .map_err(|source| HvfArm64BootVmGenIdRestoreError::Replacement { source })?;
    signal().map_err(|source| HvfArm64BootVmGenIdRestoreError::Signal { source })
}

fn update_vmclock_for_snapshot_restore(
    runner: &HvfVcpuRunner<'_>,
    backend: &mut HvfBackend,
    runtime_resources: &mut Arm64BootRuntimeResources,
    gic: HvfGicMetadata,
    interrupt_line: GuestInterruptLine,
) -> Result<(), HvfArm64BootVmClockRestoreError> {
    let guest_logger = backend.guest_logger();
    let result = (|| {
        runner
            .ensure_snapshot_restore_available()
            .map_err(|source| HvfArm64BootVmClockRestoreError::RunnerPreflight { source })?;

        let signaler = HvfGicSpiSignaler::from_metadata(&gic)
            .map_err(|source| HvfArm64BootVmClockRestoreError::SignalerPreflight { source })?;
        signaler
            .validate_line(interrupt_line)
            .map_err(|source| HvfArm64BootVmClockRestoreError::SignalerPreflight { source })?;

        let memory = backend
            .mapped_guest_memory_mut()
            .map_err(|source| HvfArm64BootVmClockRestoreError::GuestMemory { source })?;
        update_vmclock_and_signal_with(
            memory,
            &mut runtime_resources.vmclock_device,
            |memory, device| device.abi.update_after_restore(memory, device.range),
            || signaler.set_level(interrupt_line, true),
        )
    })();
    observe_vmclock_restore(&guest_logger, &result);
    result
}

pub(crate) fn update_vmclock_and_signal_with(
    memory: &mut GuestMemory,
    device: &mut Arm64BootVmClockDevice,
    update: impl FnOnce(
        &mut GuestMemory,
        &mut Arm64BootVmClockDevice,
    ) -> Result<(), VmClockRestoreUpdateError>,
    signal: impl FnOnce() -> Result<(), HvfGicSpiSignalError>,
) -> Result<(), HvfArm64BootVmClockRestoreError> {
    update(memory, device).map_err(|source| HvfArm64BootVmClockRestoreError::Update { source })?;
    signal().map_err(|source| HvfArm64BootVmClockRestoreError::Signal { source })
}

fn restore_time_identity_for_snapshot(
    runner: &HvfVcpuRunner<'_>,
    backend: &mut HvfBackend,
    runtime_resources: &mut Arm64BootRuntimeResources,
    gic: HvfGicMetadata,
    vmgenid_interrupt_line: GuestInterruptLine,
    vmclock_interrupt_line: GuestInterruptLine,
) -> Result<(), HvfArm64BootTimeIdentityRestoreError> {
    let guest_logger = backend.guest_logger();
    let result = (|| {
        runner
            .ensure_snapshot_restore_available()
            .map_err(|source| HvfArm64BootTimeIdentityRestoreError::RunnerPreflight { source })?;

        let signaler = HvfGicSpiSignaler::from_metadata(&gic).map_err(|source| {
            HvfArm64BootTimeIdentityRestoreError::SignalerPreflight {
                device: HvfArm64BootInterruptLinePurpose::VmGenIdDevice,
                source,
            }
        })?;
        signaler
            .validate_line(vmgenid_interrupt_line)
            .map_err(
                |source| HvfArm64BootTimeIdentityRestoreError::SignalerPreflight {
                    device: HvfArm64BootInterruptLinePurpose::VmGenIdDevice,
                    source,
                },
            )?;
        signaler
            .validate_line(vmclock_interrupt_line)
            .map_err(
                |source| HvfArm64BootTimeIdentityRestoreError::SignalerPreflight {
                    device: HvfArm64BootInterruptLinePurpose::VmClockDevice,
                    source,
                },
            )?;

        let memory = backend
            .mapped_guest_memory_mut()
            .map_err(|source| HvfArm64BootTimeIdentityRestoreError::GuestMemory { source })?;
        restore_time_identity_and_signal_with(
            memory,
            &mut runtime_resources.vmgenid_device,
            &mut runtime_resources.vmclock_device,
            replace_arm64_boot_vmgenid,
            |memory, device| device.abi.update_after_restore(memory, device.range),
            || signaler.set_level(vmgenid_interrupt_line, true),
            || signaler.set_level(vmclock_interrupt_line, true),
        )
    })();
    observe_ordered_time_identity_restore(&guest_logger, &result);
    result
}

pub(crate) fn restore_time_identity_and_signal_with(
    memory: &mut GuestMemory,
    vmgenid: &mut Arm64BootVmGenIdDevice,
    vmclock: &mut Arm64BootVmClockDevice,
    replace_vmgenid: impl FnOnce(
        &mut GuestMemory,
        &mut Arm64BootVmGenIdDevice,
    ) -> Result<(), Arm64BootVmGenIdReplacementError>,
    update_vmclock: impl FnOnce(
        &mut GuestMemory,
        &mut Arm64BootVmClockDevice,
    ) -> Result<(), VmClockRestoreUpdateError>,
    signal_vmgenid: impl FnOnce() -> Result<(), HvfGicSpiSignalError>,
    signal_vmclock: impl FnOnce() -> Result<(), HvfGicSpiSignalError>,
) -> Result<(), HvfArm64BootTimeIdentityRestoreError> {
    replace_vmgenid_and_signal_with(memory, vmgenid, replace_vmgenid, signal_vmgenid)
        .map_err(|source| HvfArm64BootTimeIdentityRestoreError::VmGenId { source })?;
    update_vmclock_and_signal_with(memory, vmclock, update_vmclock, signal_vmclock)
        .map_err(|source| HvfArm64BootTimeIdentityRestoreError::VmClock { source })
}

pub(crate) fn observe_vmgenid_restore(
    logger: &GuestLogger,
    result: &Result<(), HvfArm64BootVmGenIdRestoreError>,
) {
    match result {
        Ok(()) => {
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmGenIdReplacementSucceeded);
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmGenIdNotificationSucceeded);
        }
        Err(source) => observe_vmgenid_restore_error(logger, source),
    }
}

fn observe_vmgenid_restore_error(logger: &GuestLogger, error: &HvfArm64BootVmGenIdRestoreError) {
    match error {
        HvfArm64BootVmGenIdRestoreError::Signal { .. } => {
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmGenIdReplacementSucceeded);
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmGenIdNotificationFailed);
        }
        HvfArm64BootVmGenIdRestoreError::RunnerPreflight { .. }
        | HvfArm64BootVmGenIdRestoreError::SignalerPreflight { .. }
        | HvfArm64BootVmGenIdRestoreError::GuestMemory { .. }
        | HvfArm64BootVmGenIdRestoreError::Replacement { .. } => {
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmGenIdReplacementFailed);
        }
    }
}

pub(crate) fn observe_vmclock_restore(
    logger: &GuestLogger,
    result: &Result<(), HvfArm64BootVmClockRestoreError>,
) {
    match result {
        Ok(()) => {
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmClockUpdateSucceeded);
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmClockNotificationSucceeded);
        }
        Err(source) => observe_vmclock_restore_error(logger, source),
    }
}

fn observe_vmclock_restore_error(logger: &GuestLogger, error: &HvfArm64BootVmClockRestoreError) {
    match error {
        HvfArm64BootVmClockRestoreError::Signal { .. } => {
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmClockUpdateSucceeded);
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmClockNotificationFailed);
        }
        HvfArm64BootVmClockRestoreError::Update { source } if source.is_committed() => {
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmClockUpdatePartiallyCommitted)
        }
        HvfArm64BootVmClockRestoreError::RunnerPreflight { .. }
        | HvfArm64BootVmClockRestoreError::SignalerPreflight { .. }
        | HvfArm64BootVmClockRestoreError::GuestMemory { .. }
        | HvfArm64BootVmClockRestoreError::Update { .. } => {
            logger.log_time_identity(LoggerTimeIdentityOutcome::VmClockUpdateFailed);
        }
    }
}

fn observe_ordered_time_identity_restore(
    logger: &GuestLogger,
    result: &Result<(), HvfArm64BootTimeIdentityRestoreError>,
) {
    match result {
        Ok(()) => {
            observe_vmgenid_restore(logger, &Ok(()));
            observe_vmclock_restore(logger, &Ok(()));
            logger.log_time_identity(LoggerTimeIdentityOutcome::OrderedRestoreSucceeded);
        }
        Err(HvfArm64BootTimeIdentityRestoreError::VmGenId { source }) => {
            observe_vmgenid_restore_error(logger, source);
            logger.log_time_identity(if source.is_committed() {
                LoggerTimeIdentityOutcome::OrderedRestorePartiallyCommitted
            } else {
                LoggerTimeIdentityOutcome::OrderedRestoreFailed
            });
        }
        Err(HvfArm64BootTimeIdentityRestoreError::VmClock { source }) => {
            observe_vmgenid_restore(logger, &Ok(()));
            observe_vmclock_restore_error(logger, source);
            logger.log_time_identity(LoggerTimeIdentityOutcome::OrderedRestorePartiallyCommitted);
        }
        Err(
            HvfArm64BootTimeIdentityRestoreError::RunnerPreflight { .. }
            | HvfArm64BootTimeIdentityRestoreError::SignalerPreflight { .. }
            | HvfArm64BootTimeIdentityRestoreError::GuestMemory { .. },
        ) => logger.log_time_identity(LoggerTimeIdentityOutcome::OrderedRestoreFailed),
    }
}

fn signal_device_interrupt(
    line: GuestInterruptLine,
    kind: DeviceInterruptKind,
    signaler: &dyn InterruptSink,
) -> Result<(), DeviceInterruptTriggerError> {
    signaler
        .signal(line)
        .map_err(|source| DeviceInterruptTriggerError::Signal { line, kind, source })
}

#[derive(Debug)]
pub enum HvfArm64BootSessionError {
    BackendAlreadyInitialized,
    SerialInputWithoutDevice,
    UnsupportedVcpuCount {
        vcpu_count: u8,
    },
    CacheTopology {
        source: crate::cache::HvfArm64CacheTopologyError,
    },
    CreateVm {
        source: BackendError,
    },
    CreateGic {
        source: HvfGicError,
    },
    TimerMetadata {
        source: Arm64FdtError,
    },
    InterruptLineStorage {
        source: TryReserveError,
    },
    AllocateInterruptLine {
        purpose: HvfArm64BootInterruptLinePurpose,
        source: HvfInterruptLineAllocationError,
    },
    StartRunner {
        source: HvfVcpuRunnerError,
    },
    StartTopology {
        source: HvfVcpuTopologyError,
    },
    StartDirtyTracking {
        source: HvfDirtyWriteTrackerStartError,
    },
    CpuTemplate {
        source: crate::cpu_template::HvfArm64CpuTemplateError,
    },
    PowerTopology,
    RunCoordinator {
        source: HvfVcpuRunCoordinatorError,
    },
    StartBlockRetryWakeupScheduler {
        source: io::Error,
    },
    StartPmemRetryWakeupScheduler {
        source: io::Error,
    },
    StartEntropyRetryWakeupScheduler {
        source: io::Error,
    },
    StartNetworkRetryWakeupScheduler {
        source: io::Error,
    },
    ReadMpidr {
        source: HvfVcpuRunnerError,
    },
    AssembleResources {
        source: Arm64BootResourceError,
    },
    RegisterBootTimerMmio {
        source: BootTimerMmioRegistrationError,
    },
    MissingPciValidationMsiSignaler,
    PciValidationDeviceType {
        source: VirtioDeviceTypeError,
    },
    PreparePciValidationInterrupts {
        source: HvfGicMsiDeviceInterruptResourceError,
    },
    PciValidationMmioDispatcherPoisoned,
    PublishPciValidationEndpoint {
        source: VirtioPciPublicationError,
    },
    PciData {
        source: HvfArm64BootPciDataError,
    },
    DeviceMetricsBinding {
        kind: &'static str,
        message: String,
    },
    MapGuestMemory {
        source: HvfGuestMemoryMappingError,
    },
    ConfigureBootRegisters {
        source: HvfVcpuRunCoordinatorError,
    },
    PvTimeAddressOverflow {
        index: usize,
    },
    PvTimeConfigStorage {
        source: TryReserveError,
    },
    PvTimePublisher {
        index: usize,
        source: GuestMemoryAccessError,
    },
    ConfigurePvTime {
        source: HvfVcpuRunCoordinatorError,
    },
}

impl fmt::Display for HvfArm64BootSessionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::BackendAlreadyInitialized => {
                f.write_str("HVF arm64 boot session requires a backend without an existing VM")
            }
            Self::SerialInputWithoutDevice => {
                f.write_str("HVF arm64 boot serial input requires a configured serial device")
            }
            Self::UnsupportedVcpuCount { vcpu_count } => write!(
                f,
                "HVF arm64 boot session supports exactly {SINGLE_VCPU_COUNT} vCPU, got {vcpu_count}"
            ),
            Self::CacheTopology { source } => {
                write!(f, "failed to admit HVF arm64 cache topology: {source}")
            }
            Self::CreateVm { source } => write!(f, "failed to create HVF VM: {source}"),
            Self::CreateGic { source } => write!(f, "failed to create HVF GIC: {source}"),
            Self::TimerMetadata { source } => {
                write!(
                    f,
                    "failed to convert HVF timer metadata for arm64 FDT: {source}"
                )
            }
            Self::InterruptLineStorage { source } => {
                write!(
                    f,
                    "failed to allocate HVF interrupt-line metadata: {source}"
                )
            }
            Self::AllocateInterruptLine { purpose, source } => {
                write!(
                    f,
                    "failed to allocate HVF SPI interrupt line for {purpose}: {source}"
                )
            }
            Self::StartRunner { source } => {
                write!(f, "failed to start HVF vCPU runner: {source}")
            }
            Self::StartTopology { source } => {
                write!(f, "failed to start HVF vCPU topology: {source}")
            }
            Self::StartDirtyTracking { source } => {
                write!(f, "failed to start HVF dirty tracking: {source}")
            }
            Self::CpuTemplate { source } => {
                write!(f, "failed to apply HVF arm64 CPU template: {source}")
            }
            Self::PowerTopology => f.write_str("failed to initialize HVF vCPU power topology"),
            Self::RunCoordinator { source } => {
                write!(f, "failed to initialize HVF vCPU run coordinator: {source}")
            }
            Self::StartBlockRetryWakeupScheduler { source } => {
                write!(
                    f,
                    "failed to start HVF block retry wakeup scheduler: {source}"
                )
            }
            Self::StartPmemRetryWakeupScheduler { source } => {
                write!(
                    f,
                    "failed to start HVF pmem retry wakeup scheduler: {source}"
                )
            }
            Self::StartEntropyRetryWakeupScheduler { source } => {
                write!(
                    f,
                    "failed to start HVF entropy retry wakeup scheduler: {source}"
                )
            }
            Self::StartNetworkRetryWakeupScheduler { source } => {
                write!(
                    f,
                    "failed to start HVF network retry wakeup scheduler: {source}"
                )
            }
            Self::ReadMpidr { source } => {
                write!(f, "failed to read primary vCPU MPIDR_EL1: {source}")
            }
            Self::AssembleResources { source } => {
                write!(f, "failed to assemble arm64 boot resources: {source}")
            }
            Self::RegisterBootTimerMmio { source } => {
                write!(f, "failed to register boot timer MMIO: {source}")
            }
            Self::MissingPciValidationMsiSignaler => f.write_str(
                "modern virtio-pci validation requires this VM's GICv2m signal capability",
            ),
            Self::PciValidationDeviceType { source } => {
                write!(
                    f,
                    "failed to prepare PCI validation virtio device type: {source}"
                )
            }
            Self::PreparePciValidationInterrupts { source } => write!(
                f,
                "failed to prepare PCI validation MSI-X interrupt resources: {source}"
            ),
            Self::PciValidationMmioDispatcherPoisoned => {
                f.write_str("PCI validation MMIO dispatcher state is unavailable")
            }
            Self::PublishPciValidationEndpoint { source } => {
                write!(f, "failed to publish PCI validation endpoint: {source}")
            }
            Self::PciData { source } => {
                write!(f, "failed to prepare PCI data devices: {source}")
            }
            Self::DeviceMetricsBinding { kind, message } => {
                write!(f, "failed to bind {kind} transport metrics: {message}")
            }
            Self::MapGuestMemory { source } => {
                write!(
                    f,
                    "failed to map arm64 boot guest memory into HVF: {source}"
                )
            }
            Self::ConfigureBootRegisters { source } => {
                write!(
                    f,
                    "failed to configure primary HVF boot registers: {source}"
                )
            }
            Self::PvTimeAddressOverflow { index } => {
                write!(f, "PVTime record {index} stolen-time address overflows")
            }
            Self::PvTimeConfigStorage { source } => {
                write!(
                    f,
                    "failed to allocate PVTime topology configuration: {source}"
                )
            }
            Self::PvTimePublisher { index, source } => {
                write!(
                    f,
                    "failed to retain PVTime record {index} publisher: {source}"
                )
            }
            Self::ConfigurePvTime { source } => {
                write!(f, "failed to configure HVF PVTime accounting: {source}")
            }
        }
    }
}

impl std::error::Error for HvfArm64BootSessionError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::CacheTopology { source } => Some(source),
            Self::CreateVm { source } => Some(source),
            Self::CreateGic { source } => Some(source),
            Self::TimerMetadata { source } => Some(source),
            Self::InterruptLineStorage { source } => Some(source),
            Self::AllocateInterruptLine { source, .. } => Some(source),
            Self::StartRunner { source } => Some(source),
            Self::StartTopology { source } => Some(source),
            Self::StartDirtyTracking { source } => Some(source),
            Self::CpuTemplate { source } => Some(source),
            Self::RunCoordinator { source } => Some(source),
            Self::StartBlockRetryWakeupScheduler { source } => Some(source),
            Self::StartPmemRetryWakeupScheduler { source } => Some(source),
            Self::StartEntropyRetryWakeupScheduler { source } => Some(source),
            Self::StartNetworkRetryWakeupScheduler { source } => Some(source),
            Self::ReadMpidr { source } => Some(source),
            Self::AssembleResources { source } => Some(source),
            Self::RegisterBootTimerMmio { source } => Some(source),
            Self::PciValidationDeviceType { source } => Some(source),
            Self::PreparePciValidationInterrupts { source } => Some(source),
            Self::PublishPciValidationEndpoint { source } => Some(source),
            Self::PciData { source } => Some(source),
            Self::MapGuestMemory { source } => Some(source),
            Self::ConfigureBootRegisters { source } => Some(source),
            Self::PvTimeConfigStorage { source } => Some(source),
            Self::PvTimePublisher { source, .. } => Some(source),
            Self::ConfigurePvTime { source } => Some(source),
            Self::BackendAlreadyInitialized
            | Self::SerialInputWithoutDevice
            | Self::UnsupportedVcpuCount { .. }
            | Self::DeviceMetricsBinding { .. }
            | Self::PvTimeAddressOverflow { .. }
            | Self::PowerTopology
            | Self::MissingPciValidationMsiSignaler
            | Self::PciValidationMmioDispatcherPoisoned => None,
        }
    }
}

