    #[test]
    fn live_lineage_requires_durability_before_reset_and_commits_one_epoch() {
        let mut uncertain = LiveSnapshotLineage::zero(0);
        let token = uncertain
            .begin_full(Some(0))
            .expect("uncertain Full should begin");
        let reset_called = Cell::new(false);
        assert!(matches!(
            complete_live_snapshot_lineage(
                &mut uncertain,
                token,
                SnapshotCommitDurability::Uncertain {
                    kind: io::ErrorKind::Other,
                },
                None,
                || {
                    reset_called.set(true);
                    Ok(Some(1))
                },
            ),
            Err(HvfSnapshotLineageError::PublicationDurabilityUncertain)
        ));
        assert!(!reset_called.get());
        assert_eq!(
            uncertain.terminal_cause(),
            Some(LiveSnapshotLineageTerminalCause::PublicationDurabilityUncertain)
        );

        let mut durable = LiveSnapshotLineage::zero(4);
        let token = durable
            .begin_full(Some(4))
            .expect("durable Full should begin");
        let reset_called = Cell::new(false);
        complete_live_snapshot_lineage(&mut durable, token, Durable, None, || {
            reset_called.set(true);
            Ok(Some(5))
        })
        .expect("durable publication and reset should commit");
        assert!(reset_called.get());
        assert_eq!(durable.current_dirty_epoch(), Some(5));
        assert!(durable.current_image_binding().is_none());
        assert!(!durable.is_terminal());
    }

    #[test]
    fn live_lineage_terminalizes_every_post_visibility_reset_error() {
        let mut allocation = LiveSnapshotLineage::zero(0);
        let token = allocation
            .begin_full(Some(0))
            .expect("allocation case should begin");
        assert!(matches!(
            complete_live_snapshot_lineage(&mut allocation, token, Durable, None, || {
                Err(HvfDirtyWriteEpochResetError::AllocationFailed)
            }),
            Err(HvfSnapshotLineageError::DirtyEpochReset(
                HvfDirtyWriteEpochResetError::AllocationFailed
            ))
        ));
        assert_eq!(
            allocation.terminal_cause(),
            Some(LiveSnapshotLineageTerminalCause::DirtyEpochResetFailed)
        );

        let mut invalid = LiveSnapshotLineage::zero(0);
        let token = invalid
            .begin_full(Some(0))
            .expect("invalid-state case should begin");
        assert!(matches!(
            complete_live_snapshot_lineage(&mut invalid, token, Durable, None, || {
                Err(HvfDirtyWriteEpochResetError::InvalidState(
                    "injected reset failure",
                ))
            }),
            Err(HvfSnapshotLineageError::DirtyEpochReset(
                HvfDirtyWriteEpochResetError::InvalidState(_)
            ))
        ));
        assert_eq!(
            invalid.terminal_cause(),
            Some(LiveSnapshotLineageTerminalCause::DirtyEpochResetFailed)
        );
    }

    #[derive(Debug)]
    struct UnusedUnpublishedPciInterrupt;

    impl bangbang_runtime::message_interrupt::GuestMessageInterrupt for UnusedUnpublishedPciInterrupt {
        fn matches(&self, _message: bangbang_runtime::message_interrupt::GuestMessage) -> bool {
            false
        }

        fn signal(
            &self,
            _message: bangbang_runtime::message_interrupt::GuestMessage,
        ) -> Result<(), bangbang_runtime::message_interrupt::GuestMessageInterruptSignalError>
        {
            Ok(())
        }
    }

    #[derive(Debug)]
    struct FailingUnpublishedPciInterrupts {
        registry: bangbang_runtime::message_interrupt::GuestMessageInterruptRegistry,
        release_count: usize,
    }

    impl bangbang_runtime::message_interrupt::GuestMessageInterruptResources
        for FailingUnpublishedPciInterrupts
    {
        fn registry(&self) -> bangbang_runtime::message_interrupt::GuestMessageInterruptRegistry {
            self.registry.clone()
        }

        fn release(
            &mut self,
        ) -> Result<(), bangbang_runtime::message_interrupt::GuestMessageInterruptResourcesError>
        {
            self.release_count += 1;
            Err(
                bangbang_runtime::message_interrupt::GuestMessageInterruptResourcesError::new(
                    "secret-unpublished-route-cleanup",
                ),
            )
        }
    }

    #[test]
    fn unpublished_multi_block_pci_route_release_failure_is_retained_and_redacted() {
        let mut interrupts = FailingUnpublishedPciInterrupts {
            registry: bangbang_runtime::message_interrupt::GuestMessageInterruptRegistry::new(
                vec![Arc::new(UnusedUnpublishedPciInterrupt)],
            )
            .expect("single-route test registry should validate"),
            release_count: 0,
        };
        let mut cleanup = Vec::new();

        super::release_unpublished_snapshot_v2_multi_block_pci_interrupts(
            7,
            &mut interrupts,
            &mut cleanup,
        );

        assert_eq!(interrupts.release_count, 1);
        assert_eq!(cleanup.len(), 1);
        assert!(!format!("{cleanup:?}").contains("secret-unpublished"));
        assert!(!cleanup[0].to_string().contains("secret-unpublished"));
    }

    #[test]
    fn multi_block_pci_resource_plan_rejects_mismatched_root_command_line() {
        let (platform, bundle, plan) =
            crate::snapshot_v2_multi_block_platform::tests::rooted_pci_bundle_and_fdt_plan_fixture(
            );
        let prepared = bundle
            .prepare_pci_transport()
            .expect("rooted PCI bundle should prepare");
        let mut plan = plan.into_parts();
        let base_arguments = platform.machine().boot().boot_arguments();

        assert!(super::validate_snapshot_v2_multi_block_pci_resource_plan(
            &prepared,
            &plan,
            base_arguments,
        ));

        plan.command_line = bangbang_runtime::boot::canonical_process_root_block_command_line(
            base_arguments,
            true,
            Some("mismatched-partuuid"),
            true,
        )
        .expect("mismatched root command line should still be syntactically valid");
        assert!(!super::validate_snapshot_v2_multi_block_pci_resource_plan(
            &prepared,
            &plan,
            base_arguments,
        ));
    }

    #[test]
    fn vsock_run_loop_wakeup_token_retains_each_pending_request() {
        let token = super::HvfArm64BootRunLoopWakeupToken::default();

        assert!(!token.take_wakeup_request());
        token.request_wakeup();
        token.request_wakeup();

        assert!(token.take_wakeup_request());
        assert!(token.take_wakeup_request());
        assert!(!token.take_wakeup_request());
    }

    #[test]
    fn run_loop_wakeup_pollfds_preserve_read_and_write_interests() {
        let pollfds = super::run_loop_wakeup_pollfds(vec![13, 11, 13], vec![12, 13, 12], 10)
            .expect("vsock poll descriptors should build");
        let descriptors = pollfds
            .iter()
            .map(|pollfd| (pollfd.fd, pollfd.events, pollfd.revents))
            .collect::<Vec<_>>();

        assert_eq!(
            descriptors,
            [
                (10, libc::POLLIN, 0),
                (11, libc::POLLIN, 0),
                (12, libc::POLLOUT, 0),
                (13, libc::POLLIN | libc::POLLOUT, 0),
            ]
        );
        assert!(super::pollfd_has_wakeup_event(libc::POLLOUT));
    }

    #[test]
    fn vsock_wakeup_poll_timeout_rounds_up_and_clamps_absolute_deadline() {
        let now = Instant::now();

        assert_eq!(super::vsock_wakeup_poll_timeout(None, now), -1);
        assert_eq!(super::vsock_wakeup_poll_timeout(Some(now), now), 0);
        assert_eq!(
            super::vsock_wakeup_poll_timeout(Some(now - Duration::from_nanos(1)), now),
            0
        );
        assert_eq!(
            super::vsock_wakeup_poll_timeout(Some(now + Duration::from_nanos(1)), now),
            1
        );
        assert_eq!(
            super::vsock_wakeup_poll_timeout(Some(now + Duration::from_millis(1)), now),
            1
        );
        assert_eq!(
            super::vsock_wakeup_poll_timeout(
                Some(now + Duration::from_millis(1) + Duration::from_nanos(1)),
                now,
            ),
            2
        );
        assert_eq!(
            super::vsock_wakeup_poll_timeout(
                Some(now + Duration::from_millis(libc::c_int::MAX as u64 + 1)),
                now,
            ),
            libc::c_int::MAX
        );
    }

    #[test]
    fn run_loop_wakeup_monitor_recomputes_deadline_only_timeout_after_interrupt() {
        let now = Instant::now();
        let deadline = now + Duration::from_millis(5);
        let mut pollfds = [libc::pollfd {
            fd: 10,
            events: libc::POLLIN,
            revents: 0,
        }];
        let mut times = VecDeque::from([now, now + Duration::from_millis(2)]);
        let mut outcomes = VecDeque::from([
            Err(io::ErrorKind::Interrupted),
            Ok::<libc::c_int, io::ErrorKind>(0),
        ]);
        let mut timeouts = Vec::new();
        let mut wakeups = 0usize;

        let observation = super::run_loop_wakeup_monitor_with(
            &mut pollfds,
            1,
            Some(deadline),
            &[],
            || times.pop_front().expect("each poll should sample time"),
            |pollfds, count, timeout| {
                assert_eq!(pollfds.len(), 1);
                assert_eq!(count, 1);
                timeouts.push(timeout);
                outcomes.pop_front().expect("poll outcome should exist")
            },
            || wakeups += 1,
        );

        assert!(observation.wakeup_requested);
        assert!(observation.vsock.is_empty());
        assert_eq!(timeouts, [5, 3]);
        assert_eq!(wakeups, 1);
        assert!(times.is_empty());
        assert!(outcomes.is_empty());
    }

    #[test]
    fn run_loop_wakeup_monitor_preserves_stop_precedence_over_fd_and_deadline() {
        let now = Instant::now();
        let mut pollfds = [
            libc::pollfd {
                fd: 10,
                events: libc::POLLIN,
                revents: 0,
            },
            libc::pollfd {
                fd: 11,
                events: libc::POLLIN,
                revents: 0,
            },
        ];
        let mut wakeups = 0usize;

        let observation = super::run_loop_wakeup_monitor_with(
            &mut pollfds,
            2,
            Some(now),
            &[11],
            || now,
            |pollfds, _, timeout| {
                assert_eq!(timeout, 0);
                pollfds[0].revents = libc::POLLIN;
                pollfds[1].revents = libc::POLLERR;
                Ok(2)
            },
            || wakeups += 1,
        );

        assert!(!observation.wakeup_requested);
        assert!(observation.vsock.is_empty());
        assert_eq!(wakeups, 0);
    }

    #[test]
    fn run_loop_wakeup_monitor_preserves_all_simultaneous_vsock_readiness_flags() {
        let now = Instant::now();
        let mut pollfds = [
            libc::pollfd {
                fd: 10,
                events: libc::POLLIN,
                revents: 0,
            },
            libc::pollfd {
                fd: 11,
                events: libc::POLLIN,
                revents: 0,
            },
        ];
        let mut wakeups = 0usize;

        let observation = super::run_loop_wakeup_monitor_with(
            &mut pollfds,
            2,
            Some(now),
            &[11],
            || now,
            |pollfds, _, timeout| {
                assert_eq!(timeout, 0);
                pollfds[1].revents =
                    libc::POLLIN | libc::POLLOUT | libc::POLLERR | libc::POLLHUP | libc::POLLNVAL;
                Ok(1)
            },
            || wakeups += 1,
        );

        assert!(observation.wakeup_requested);
        assert!(!observation.vsock.poll_failed);
        assert_eq!(observation.vsock.events.len(), 1);
        assert_eq!(observation.vsock.events[0].descriptor(), 11);
        assert!(observation.vsock.events[0].readable());
        assert!(observation.vsock.events[0].writable());
        assert!(observation.vsock.events[0].error());
        assert!(observation.vsock.events[0].hangup());
        assert!(observation.vsock.events[0].invalid());
        assert_eq!(wakeups, 1);
    }

    #[test]
    fn run_loop_wakeup_monitor_conservatively_wakes_owner_on_poll_error() {
        let now = Instant::now();
        let mut pollfds = [libc::pollfd {
            fd: 10,
            events: libc::POLLIN,
            revents: 0,
        }];
        let mut wakeups = 0usize;

        let observation = super::run_loop_wakeup_monitor_with(
            &mut pollfds,
            1,
            None,
            &[10],
            || now,
            |_, _, timeout| {
                assert_eq!(timeout, -1);
                Err(io::ErrorKind::PermissionDenied)
            },
            || wakeups += 1,
        );

        assert!(observation.wakeup_requested);
        assert!(observation.vsock.poll_failed);
        assert!(observation.vsock.events.is_empty());
        assert_eq!(wakeups, 1);
    }

    #[test]
    fn vsock_deadline_only_monitor_stops_and_joins_without_waiting_for_deadline() {
        let (runner, _configured) = start_secondary_configure_recording_runner(false);
        let dispatcher = Arc::new(Mutex::new(MmioDispatcher::new()));
        let mut coordinator =
            HvfVcpuRunCoordinator::from_test_runners(vec![runner], vec![0], dispatcher, &[0])
                .expect("test coordinator should build");
        let wakeup = super::HvfArm64BootRunLoopWakeupToken::default();
        let monitor = super::HvfArm64BootRunLoopWakeupMonitor::start(
            super::HvfArm64BootRunLoopWakeupInputs {
                host_read_fds: Vec::new(),
                host_write_fds: Vec::new(),
                vsock_read_fds: Vec::new(),
                vsock_write_fds: Vec::new(),
                deadline: Some(Instant::now() + Duration::from_secs(60 * 60)),
                has_block_wakeup_fds: false,
                has_serial_input_fd: false,
            },
            coordinator.control(),
            wakeup.clone(),
        )
        .expect("deadline-only monitor should start");

        let observation = monitor.finish().expect("monitor should stop and join");
        assert!(!observation.wakeup_requested);
        assert!(observation.vsock.is_empty());
        assert!(!wakeup.take_wakeup_request());
        coordinator
            .shutdown()
            .expect("test coordinator should shut down");
    }

